import type { BankQuestion } from "@/lib/bank";

/** Computer Networks (CS Fundamentals): 581 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "cs-computer-networks-1", "question": "In the OSI model, which layer decides the path a packet takes from one network to another?", "options": ["Network layer", "Data link layer", "Transport layer", "Session layer"], "answer": 0, "explanation": "Routing (logical addressing with IP and path selection) is the job of the network layer, layer 3. The data link layer only moves frames across a single link.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-computer-networks-2", "question": "Which protocol finds the MAC address of a host when only its IPv4 address is known?", "options": ["RARP", "ARP", "DNS", "ICMP"], "answer": 1, "explanation": "ARP (Address Resolution Protocol) maps a known IPv4 address to a MAC address on the local network. RARP did the reverse (MAC to IP) and is obsolete.", "difficulty": "easy", "source": "Wipro · Accenture pattern"},
  {"id":"cs-computer-networks-3","question":"What is the well-known TCP port for HTTPS?","options":["80","8080","443","22"],"answer":2,"explanation":"HTTPS (HTTP over TLS) listens on port 443; plain HTTP uses 80, and 22 is SSH.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-computer-networks-4", "question": "The protocol data unit handled at the data link layer is called a:", "options": ["Packet", "Segment", "Bit stream", "Frame"], "answer": 3, "explanation": "Physical layer → bits, data link → frames, network → packets (datagrams), transport → segments (TCP) or datagrams (UDP).", "difficulty": "easy", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-computer-networks-5", "question": "Which device forwards traffic inside a LAN by looking up destination MAC addresses in a table?", "options": ["Switch", "Hub", "Router", "Repeater"], "answer": 0, "explanation": "A switch is a layer-2 device that learns MAC addresses per port and forwards frames only to the right port. A hub just repeats bits to every port; a router works on IP addresses.", "difficulty": "easy", "source": "HCL · Tech Mahindra pattern"},
  {"id": "cs-computer-networks-6", "question": "Which transport-layer protocol is connectionless and gives no delivery guarantee?", "options": ["TCP", "UDP", "SCTP", "HTTP"], "answer": 1, "explanation": "UDP sends independent datagrams with no handshake, acknowledgement or retransmission. TCP is connection-oriented and reliable; HTTP is an application-layer protocol.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-7","question":"A subnet uses the mask 255.255.255.240. How many usable host addresses does each subnet have?","options":["15","16","14","30"],"answer":2,"explanation":"240 = 11110000, so 4 host bits remain: 2⁴ = 16 addresses, minus the network and broadcast addresses = 14 usable hosts.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-8","question":"Which of these IPv4 addresses is a private (RFC 1918) address?","options":["11.0.0.1","172.32.1.1","192.169.10.1","172.20.5.4"],"answer":3,"explanation":"Private ranges are 10.0.0.0/8, 172.16.0.0–172.31.255.255 (/12) and 192.168.0.0/16. 172.32.x.x lies just outside the /12 block and 192.169.x.x is outside 192.168/16, a common trap.","difficulty":"easy","source":"Wipro · Accenture pattern"},
  {"id":"cs-computer-networks-9","question":"A newly booted client obtains an IP address through DHCP. In what order are the four DHCP messages exchanged?","options":["Discover → Offer → Request → Acknowledge","Request → Offer → Discover → Acknowledge","Discover → Request → Offer → Acknowledge","Offer → Discover → Acknowledge → Request"],"answer":0,"explanation":"The DORA sequence: the client broadcasts DISCOVER, servers reply with OFFER, the client broadcasts REQUEST for one offer, and the chosen server confirms with ACK.","difficulty":"moderate","source":"Cognizant · Capgemini pattern"},
  {"id":"cs-computer-networks-10","question":"DNS normally carries an ordinary name lookup over which transport, and a zone transfer between DNS servers over which?","options":["TCP port 53 for both","UDP port 53 for lookups; TCP port 53 for zone transfers","UDP port 67 for lookups; TCP port 53 for zone transfers","UDP port 53 for both"],"answer":1,"explanation":"Small queries go over UDP 53 for speed; zone transfers (AXFR) and responses too large for UDP use TCP 53. Port 67 belongs to DHCP.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-11","question":"An HTTP server tells the browser that a page has moved for good to a new URL and that bookmarks should be updated. Which status code does it send?","options":["302 Found","304 Not Modified","301 Moved Permanently","307 Temporary Redirect"],"answer":2,"explanation":"301 is a permanent redirect. 302 and 307 are temporary redirects, and 304 means the cached copy is still valid (no redirect at all).","difficulty":"easy","source":"Product-company MCQ pattern"},
  {"id": "cs-computer-networks-12", "question": "A code must be able to correct any 2-bit error in a codeword. What is the minimum Hamming distance it needs?", "options": ["3", "4", "6", "5"], "answer": 3, "explanation": "To correct t errors the minimum distance must be 2t + 1 = 2(2) + 1 = 5. A distance of 3 corrects only single-bit errors; 4 corrects 1 and detects 3.", "difficulty": "moderate", "source": "HCL · Tech Mahindra pattern"},
  {"id": "cs-computer-networks-13", "question": "What is the maximum throughput (fraction of time the channel carries a successful frame) of pure ALOHA?", "options": ["About 18.4% (1/2e)", "About 36.8% (1/e)", "About 50%", "About 9.2% (1/4e)"], "answer": 0, "explanation": "Pure ALOHA has a vulnerable period of 2 frame times, so S = G·e^(−2G), maximised at G = 0.5 giving 1/(2e) ≈ 0.184. Slotted ALOHA halves the vulnerable period and reaches 1/e ≈ 0.368.", "difficulty": "easy", "source": "Wipro · Accenture pattern"},
  {"id":"cs-computer-networks-14","question":"The ping utility checks whether a host is reachable by sending which kind of message?","options":["TCP SYN segment","ICMP Echo Request","UDP datagram to port 7","ARP request"],"answer":1,"explanation":"ping sends ICMP Echo Request and waits for ICMP Echo Reply. ICMP is carried directly inside IP, with no TCP or UDP port.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-15","question":"How many IPv4 addresses (including network and broadcast) are in the block 160.10.8.0/21?","options":["4096","1024","2048","2046"],"answer":2,"explanation":"A /21 leaves 32 − 21 = 11 host bits, so the block has 2¹¹ = 2048 addresses (2046 usable hosts, which is the trap option).","difficulty":"moderate","source":"Cognizant · Capgemini pattern"},
  {"id":"cs-computer-networks-16","question":"A company with 300 PCs and a single public IPv4 address lets all of them browse the web at once. The router keeps a table that maps each internal (IP, port) pair to a different public port. This technique is:","options":["Static NAT","DHCP relay","Proxy ARP","PAT (NAT overload)"],"answer":3,"explanation":"Port Address Translation (NAT overload) shares one public IP by giving every inside connection its own source port. Static NAT maps one private address to one public address and could not serve 300 hosts with one IP.","difficulty":"moderate","source":"IBM · Deloitte pattern"},
  {"id":"cs-computer-networks-17","question":"Which IPv4 header field stops a packet from circulating forever if a routing loop forms?","options":["Time to Live (TTL)","Fragment offset","Identification","Header checksum"],"answer":0,"explanation":"Every router decrements TTL by 1 and drops the packet when it reaches 0, sending back ICMP Time Exceeded. IPv6 calls the same field Hop Limit.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-18","question":"How many parity (check) bits does a single-error-correcting Hamming code need for 11 data bits?","options":["3","4","5","11"],"answer":1,"explanation":"Need the smallest r with 2^r ≥ m + r + 1. For m = 11: r = 3 gives 8 < 15, r = 4 gives 16 ≥ 16, so r = 4 (the (15, 11) code).","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id": "cs-computer-networks-19", "question": "A Go-Back-N protocol uses 3-bit sequence numbers. What is the largest sender window that still works correctly?", "options": ["8", "4", "7", "3"], "answer": 2, "explanation": "With k-bit sequence numbers Go-Back-N allows a window of at most 2^k − 1 = 7. A window of 8 would let the receiver mistake a retransmitted old frame 0 for a new frame 0. (Selective Repeat would be limited to 2^(k−1) = 4.)", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-20","question":"Under classful addressing, 150.20.3.4 belongs to which class, and what is its default subnet mask?","options":["Class A, 255.0.0.0","Class B, 255.255.255.0","Class C, 255.255.255.0","Class B, 255.255.0.0"],"answer":3,"explanation":"First octet 128–191 means class B (150 lies in this range), whose default mask is 255.255.0.0 (/16). Class A is 1–126 and class C is 192–223.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-21","question":"A host has the address 172.16.45.200/20. What is the network address of its subnet?","options":["172.16.32.0","172.16.40.0","172.16.45.0","172.16.48.0"],"answer":0,"explanation":"A /20 mask is 255.255.240.0, so the third octet moves in blocks of 16. 45 lies in 32–47, so the network is 172.16.32.0 (broadcast 172.16.47.255). 172.16.45.0 is what you get by wrongly assuming /24.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-22","question":"What is the directed broadcast address of the subnet containing 10.37.190.77/19?","options":["10.37.190.255","10.37.191.255","10.37.159.255","10.37.255.255"],"answer":1,"explanation":"A /19 mask is 255.255.224.0, so the third octet steps by 32: 160–191. The subnet is 10.37.160.0 and its broadcast is 10.37.191.255.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id": "cs-computer-networks-23", "question": "The block 10.0.0.0/8 must be divided into at least 500 equal subnets, each with as many hosts as possible. How many usable hosts will each subnet have?", "options": ["65,534", "16,382", "32,766", "32,768"], "answer": 2, "explanation": "500 subnets need 9 borrowed bits (2⁹ = 512 ≥ 500; 2⁸ = 256 is too few), giving /17. Host bits = 32 − 17 = 15, so 2¹⁵ − 2 = 32,766 usable hosts. 32,768 forgets to remove network and broadcast.", "difficulty": "hard", "source": "Cognizant · Capgemini pattern"},
  {"id":"cs-computer-networks-24","question":"Which address is in the same subnet as 192.168.5.130/27 and can be assigned to a host?","options":["192.168.5.127","192.168.5.159","192.168.5.160","192.168.5.158"],"answer":3,"explanation":"/27 → blocks of 32 in the last octet, so .130 lies in 128–159. .158 is a usable host; .159 is the broadcast of that subnet, .127 belongs to the previous subnet and .160 to the next.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-25","question":"An ISP wants to advertise the four networks 200.10.4.0/24, 200.10.5.0/24, 200.10.6.0/24 and 200.10.7.0/24 as one route. What is the aggregate?","options":["200.10.4.0/22","200.10.0.0/21","200.10.4.0/23","200.10.4.0/24"],"answer":0,"explanation":"Third octets 4–7 are 000001|00 to 000001|11, so the first 22 bits match and the four /24s fill exactly one /22 starting at 4 (4 is a multiple of 4). A /23 covers only two of them; a /21 would also cover 0–3, which this ISP does not own.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-26","question":"Data bits 10011010 are sent using CRC with generator polynomial x³ + x² + 1. What bit string is actually transmitted?","options":["10011010011","10011010101","1001101101","10011010110"],"answer":1,"explanation":"The generator is 1101, so append 3 zeros (10011010000) and divide modulo 2; the remainder is 101. The transmitted frame is the data followed by the remainder: 10011010101.","difficulty":"hard","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-computer-networks-27","question":"Using the (7, 4) Hamming code with even parity and bit layout p1 p2 d3 p4 d5 d6 d7 (data in positions 3, 5, 6, 7), what codeword is sent for the data 1011?","options":["1010101","0111011","0110011","1011010"],"answer":2,"explanation":"d3 = 1, d5 = 0, d6 = 1, d7 = 1. p1 covers 3, 5, 7: 1⊕0⊕1 = 0. p2 covers 3, 6, 7: 1⊕1⊕1 = 1. p4 covers 5, 6, 7: 0⊕1⊕1 = 0. Codeword p1 p2 d3 p4 d5 d6 d7 = 0 1 1 0 0 1 1.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id": "cs-computer-networks-28", "question": "A stop-and-wait link runs at 1 Mbps with 1000-bit frames and a one-way propagation delay of 20 ms. Ignoring ACK size and processing, what is the link utilisation?", "options": ["About 4.8%", "About 50%", "About 1.2%", "About 2.4%"], "answer": 3, "explanation": "Transmission time Tt = 1000/10⁶ = 1 ms, so a = Tp/Tt = 20. Efficiency = 1/(1 + 2a) = 1/41 ≈ 0.0244, i.e. about 2.4%. Using 1/(1 + a) gives 4.8%, the usual slip of forgetting the ACK's return trip.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-29", "question": "A Selective Repeat protocol uses 4-bit sequence numbers. What is the maximum window size (equal sender and receiver windows)?", "options": ["15", "16", "7", "8"], "answer": 3, "explanation": "For Selective Repeat the window must not exceed half the sequence space: 2^(4−1) = 8. 15 is the Go-Back-N limit (2⁴ − 1), the most common mix-up.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-30","question":"A CSMA/CD network runs at 10 Mbps over a 2 km cable where signals travel at 2 × 10⁸ m/s. What is the minimum frame size needed for collision detection to work?","options":["25 bytes","12.5 bytes","50 bytes","200 bytes"],"answer":0,"explanation":"One-way propagation delay Tp = 2000/(2 × 10⁸) = 10 μs. The frame must still be transmitting after a round trip: Lmin = 2·Tp·B = 2 × 10⁻⁵ × 10⁷ = 200 bits = 25 bytes. 200 bytes confuses bits with bytes; 12.5 bytes uses only one-way delay.","difficulty":"hard","source":"Cognizant · Capgemini pattern"},
  {"id": "cs-computer-networks-31", "question": "A 4000-byte IPv4 datagram (20-byte header, no options) must cross a link with MTU 1500 bytes. What is the fragment offset field value of the last fragment?", "options": ["2960", "370", "1480", "185"], "answer": 1, "explanation": "Each fragment can carry 1480 data bytes (a multiple of 8). 3980 data bytes split as 1480 + 1480 + 1020, so the last fragment starts at byte 2960, and the offset field counts 8-byte units: 2960/8 = 370. 185 is the second fragment's offset; 2960 forgets to divide by 8.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-32","question":"A TCP connection has a 65,535-byte receive window (no window scaling) and a round-trip time of 50 ms. What is the best throughput it can reach, however fast the link is?","options":["About 1.3 Mbps","About 21 Mbps","About 10.5 Mbps","About 655 Mbps"],"answer":2,"explanation":"At most one window can be in flight per RTT: 65,535 × 8 bits / 0.05 s ≈ 10,485,600 bps ≈ 10.5 Mbps. 1.3 Mbps leaves the answer in bytes per second (MBps), and 21 Mbps uses one-way delay instead of RTT.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-33","question":"A client's SYN carries initial sequence number 1000. After the handshake it sends one segment with 200 bytes of data. What sequence number does that segment carry, and what acknowledgement number does the server send back for it?","options":["Sequence 1000, ACK 1200","Sequence 1001, ACK 1200","Sequence 1000, ACK 1201","Sequence 1001, ACK 1201"],"answer":3,"explanation":"The SYN consumes one sequence number, so the first data byte is 1001. The segment covers bytes 1001–1200, and TCP acknowledges the next byte it expects: 1201.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-34","question":"Host A (192.168.1.10/24) sends a packet to 8.8.8.8 through its default gateway 192.168.1.1. Whose MAC address does A's ARP request ask for?","options":["The default gateway 192.168.1.1","8.8.8.8","The DNS server","The broadcast MAC FF:FF:FF:FF:FF:FF"],"answer":0,"explanation":"The destination is off-subnet, so the frame is addressed at layer 2 to the next hop, the gateway, while the IP header still says 8.8.8.8. A never ARPs for a remote IP; FF:FF:FF:FF:FF:FF is only the destination of the ARP request frame itself.","difficulty":"moderate","source":"Wipro · Accenture pattern"},
  {"id":"cs-computer-networks-35","question":"How does traceroute learn the address of each router along the path?","options":["It reads the Record Route option that every router fills in","It sends probes with TTL = 1, 2, 3, … and records the ICMP Time Exceeded reply from each router","It sends one ICMP Echo Request and every router replies with an ICMP Echo Reply","It asks each router through SNMP for its next hop"],"answer":1,"explanation":"Each probe's TTL expires one hop further away; the router that drops it returns ICMP Time Exceeded, revealing its address. The final host answers with Echo Reply (Windows) or Port Unreachable (UDP-based Unix traceroute).","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-36","question":"A router's table holds 10.0.0.0/8 → interface A, 10.1.0.0/16 → interface B, 10.1.128.0/17 → interface C and a default route → interface D. On which interface is a packet for 10.1.130.5 sent?","options":["B","A","C","D"],"answer":2,"explanation":"All three prefixes match 10.1.130.5 (130 ≥ 128 falls in 10.1.128.0/17), and the router uses longest-prefix match, so the /17 entry wins. A packet for 10.1.100.5 would have gone to B.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-37","question":"A token bucket has capacity 1 MB and fills at 2 MB/s; the output line can run at 10 MB/s. Starting with a full bucket, for how long can the host send at the full 10 MB/s?","options":["0.1 s","0.5 s","0.083 s","0.125 s"],"answer":3,"explanation":"Burst length S satisfies C + ρS = MS, so S = C/(M − ρ) = 1/(10 − 2) = 0.125 s. 0.1 s (= C/M) ignores the tokens that keep arriving during the burst.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id":"cs-computer-networks-38","question":"A 3000 Hz telephone channel has a signal-to-noise ratio of 30 dB. What is its Shannon capacity, approximately?","options":["About 30 kbps","About 90 kbps","About 6 kbps","About 15 kbps"],"answer":0,"explanation":"30 dB means SNR = 10^(30/10) = 1000. C = B·log₂(1 + SNR) = 3000 × log₂(1001) ≈ 3000 × 9.97 ≈ 29.9 kbps. Plugging 30 directly gives 3000 × log₂31 ≈ 14.9 kbps, the classic dB trap.","difficulty":"moderate","source":"Cognizant · Capgemini pattern"},
  {"id": "cs-computer-networks-39", "question": "Which side of a TCP connection goes through the TIME_WAIT state, and for how long?", "options": ["The side that closes last (passive close), for 2 × MSL", "Both sides, for one RTT", "The side that closes first (active close), for 2 × MSL", "The server only, for 1 × MSL"], "answer": 2, "explanation": "The active closer sends the final ACK and waits 2·MSL so that a lost final ACK can be resent and stale duplicate segments die out before the same port pair is reused.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-40","question":"A web page consists of a base HTML file and 10 small images on the same server. Using persistent HTTP without pipelining and ignoring transmission times, how many RTTs does it take to fetch everything?","options":["22 RTTs","12 RTTs","3 RTTs","11 RTTs"],"answer":1,"explanation":"One RTT for the TCP handshake and one for the base file = 2 RTT; then each image needs one request-response RTT on the same connection = 10. Total 12. Non-persistent HTTP would need 2 per object = 22; pipelining would need 2 + 1 = 3.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-computer-networks-41", "question": "A user's laptop resolves www.example.org using a local DNS server that has nothing cached. Which description of the lookup is the usual one?", "options": ["The laptop itself contacts the root, TLD and authoritative servers in turn", "The root server forwards the query to the TLD server, which forwards it to the authoritative server", "The laptop sends a recursive query to the local server, which then queries the root, the .org TLD and the authoritative server iteratively", "The local server broadcasts the query on the LAN until the authoritative server answers"], "answer": 2, "explanation": "Stub resolvers ask the local resolver recursively; the local resolver walks the hierarchy with iterative queries, getting a referral from the root and the TLD before the authoritative server answers. Root servers do not perform recursion.", "difficulty": "moderate", "source": "IBM · Deloitte pattern"},
  {"id":"cs-computer-networks-42","question":"A noiseless channel of bandwidth 4 kHz carries a signal with 8 distinct levels. What is the maximum bit rate according to Nyquist?","options":["8 kbps","12 kbps","32 kbps","24 kbps"],"answer":3,"explanation":"Nyquist: C = 2B·log₂L = 2 × 4000 × log₂8 = 8000 × 3 = 24,000 bps. 32 kbps multiplies by 8 levels instead of log₂8 = 3 bits.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id": "cs-computer-networks-43", "question": "How many of the following statements about TCP and UDP are correct?\n1. UDP header is 8 bytes; the minimum TCP header is 20 bytes.\n2. TCP preserves message boundaries, so two send() calls of 100 bytes are always read as two 100-byte reads.\n3. Both TCP and UDP carry a checksum that covers a pseudo-header containing the IP addresses.\n4. UDP can be used for multicast, but TCP cannot.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1 is true (8 vs 20–60 bytes). 2 is false: TCP is a byte stream and may merge or split the data; UDP is the one that preserves datagram boundaries. 3 is true (the UDP checksum is optional in IPv4 but still uses the pseudo-header). 4 is true, since TCP is strictly one-to-one. So three are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-44", "question": "Using VLSM, the block 192.168.1.0/24 is split for three LANs needing 100, 50 and 20 hosts, assigning the largest LAN first from the lowest addresses. What is the subnet given to the 20-host LAN?", "options": ["192.168.1.192/27", "192.168.1.160/27", "192.168.1.128/27", "192.168.1.192/26"], "answer": 0, "explanation": "100 hosts need 7 host bits → 192.168.1.0/25 (0–127). 50 hosts need 6 → 192.168.1.128/26 (128–191). 20 hosts need 5 (30 usable) → next free block 192.168.1.192/27. .128/27 and .160/27 overlap the 50-host subnet; a /26 would waste 32 addresses.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-45", "question": "An organisation owns 200.10.5.0/24, 200.10.6.0/24, 200.10.7.0/24 and 200.10.8.0/24. What is the smallest single CIDR block that covers all four?", "options": ["200.10.4.0/22", "200.10.0.0/20", "200.10.5.0/22", "200.10.0.0/21"], "answer": 1, "explanation": "Third octets: 5 = 00000101, 8 = 00001000. They agree only in the first 4 bits (0000), so the prefix is 16 + 4 = 20 bits: 200.10.0.0/20 (third octet 0–15). 200.10.4.0/22 covers only 4–7, 200.10.5.0/22 is not a valid block boundary, and a /21 covers 0–7 and misses 8.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-46","question":"A sender uses CRC generator 1011 and transmits the data 1101101 followed by its CRC. In transit the third bit from the left is flipped. What remainder does the receiver get when it divides the received 10 bits by 1011, and what does it conclude?","options":["111; error detected","000; frame accepted","001; error detected","010; error detected"],"answer":2,"explanation":"The CRC of 1101101 with 1011 is 111, so 1101101111 is sent and leaves remainder 000. With bit 3 flipped the receiver gets 1111101111; dividing by 1011 leaves 001, which is non-zero, so the error is detected (any single-bit error is caught because the generator has more than one term).","difficulty":"hard","source":"HCL · Tech Mahindra pattern"},
  {"id": "cs-computer-networks-47", "question": "A (7, 4) even-parity Hamming codeword (layout p1 p2 d3 p4 d5 d6 d7) is received as 0110111. Assuming at most one bit is in error, what are the four data bits d3 d5 d6 d7 after correction?", "options": ["1111", "1010", "0111", "1011"], "answer": 3, "explanation": "Check p1 (1,3,5,7): 0⊕1⊕1⊕1 = 1. p2 (2,3,6,7): 1⊕1⊕1⊕1 = 0. p4 (4,5,6,7): 0⊕1⊕1⊕1 = 1. Syndrome = 4 + 1 = 5, so bit 5 is wrong: corrected word 0110011, data 1, 0, 1, 1 = 1011. 1111 is the uncorrected data.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-48","question":"A link has transmission time 1 ms per frame and one-way propagation delay 24.5 ms. Using Selective Repeat with sender window equal to receiver window, what is the minimum number of sequence-number bits needed to keep the link fully busy?","options":["7","5","8","6"],"answer":0,"explanation":"Full utilisation needs window ≥ 1 + 2a = 1 + 2(24.5) = 50 frames. Selective Repeat requires window ≤ 2^(k−1), so 2^(k−1) ≥ 50 → k − 1 = 6 → k = 7. Go-Back-N would need only 2^k − 1 ≥ 50 → k = 6, the trap answer.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-49","question":"TCP Tahoe starts with cwnd = 1 MSS and ssthresh = 16 MSS. cwnd doubles each RTT in slow start (but is capped at ssthresh when doubling would overshoot it) and grows by 1 MSS per RTT in congestion avoidance. A timeout happens during RTT 9. What is cwnd during RTT 15?","options":["16 MSS","11 MSS","17 MSS","10 MSS"],"answer":1,"explanation":"RTT 1–5: 1, 2, 4, 8, 16; RTT 6–9: 17, 18, 19, 20. Timeout at cwnd 20 → ssthresh = 10, cwnd = 1. RTT 10–14: 1, 2, 4, 8, 10 (capped); RTT 15: 11. 16 comes from keeping the old ssthresh, 10 from stopping one RTT early.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-computer-networks-50", "question": "How many of the following statements about TCP congestion control (Reno) are correct?\n1. On three duplicate ACKs, ssthresh is set to half the current cwnd and the lost segment is retransmitted without waiting for a timeout.\n2. On a retransmission timeout, cwnd drops to 1 MSS and slow start begins again.\n3. In slow start, cwnd grows linearly by one MSS per RTT.\n4. The receiver's advertised window, not cwnd, is the only limit on how much unacknowledged data a sender may have.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "1 (fast retransmit / fast recovery) and 2 are correct. 3 is wrong: slow start grows exponentially (doubling per RTT); linear growth is congestion avoidance. 4 is wrong: the sender is limited by min(cwnd, rwnd). So two are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-51","question":"TCP sequence numbers are 32 bits and count bytes. On a 1 Gbps link sending continuously, roughly how long does it take for the sequence numbers to wrap around?","options":["About 4.3 seconds","About 4.3 minutes","About 34 seconds","About 0.5 seconds"],"answer":2,"explanation":"2³² bytes = 4,294,967,296 bytes = 34,359,738,368 bits; at 10⁹ bits/s that is about 34.4 s. 4.3 s comes from treating the sequence space as bits instead of bytes — which is why fast links need the PAWS timestamp option.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-52","question":"Under distance-vector routing, router A has direct links to B (cost 2) and C (cost 5). B advertises distances {D: 7, E: 1} and C advertises {D: 3, E: 4}. What does A's new table give for D and E?","options":["D = 9 via B, E = 3 via B","D = 8 via C, E = 9 via C","D = 3 via C, E = 1 via B","D = 8 via C, E = 3 via B"],"answer":3,"explanation":"Bellman–Ford: D = min(2 + 7, 5 + 3) = min(9, 8) = 8 via C; E = min(2 + 1, 5 + 4) = min(3, 9) = 3 via B. Copying the neighbour's advertised value without adding the link cost gives the third option.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-computer-networks-53", "question": "An undirected network has links A–B 4, A–C 1, B–C 2, B–D 5, C–D 8, C–E 10, D–E 2, D–F 6, E–F 3. What is the cost of the shortest path from A to F found by Dijkstra's algorithm?", "options": ["14", "15", "13", "12"], "answer": 2, "explanation": "Dijkstra from A: C = 1, B = min(4, 1 + 2) = 3, D = min(3 + 5, 1 + 8) = 8, E = min(1 + 10, 8 + 2) = 10, F = min(8 + 6, 10 + 3) = 13 along A–C–B–D–E–F. 14 is A–B–D–E–F (missing the cheaper route to B through C) and 15 is A–C–D–F.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-54","question":"Match each protocol with its default port.\nP. SSH   Q. SMTP   R. SNMP   S. DNS\n1. 25   2. 22   3. 53   4. 161","options":["P-2, Q-1, R-4, S-3","P-2, Q-1, R-3, S-4","P-1, Q-2, R-4, S-3","P-2, Q-4, R-1, S-3"],"answer":0,"explanation":"SSH = 22, SMTP = 25, DNS = 53, SNMP = 161 (agents; traps go to 162). Mixing 22/25 and 53/161 are the usual slips.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-55","question":"A hub with 3 PCs is plugged into one port of switch S1. S1 also connects 4 PCs directly and one port to router R. R's other interface goes to switch S2, which connects 5 PCs. How many collision domains and broadcast domains are there? (Each switch port is its own collision domain.)","options":["8 collision domains, 2 broadcast domains","12 collision domains, 2 broadcast domains","12 collision domains, 1 broadcast domain","14 collision domains, 2 broadcast domains"],"answer":1,"explanation":"S1 has 6 used ports (hub segment, 4 PCs, router link) = 6 collision domains, the hub and its 3 PCs being one. S2 has 6 (router link + 5 PCs). Total 12. Only the router splits broadcast domains, so there are 2. Counting each hub PC separately gives 14.","difficulty":"hard","source":"Cognizant · Capgemini pattern"},
  {"id": "cs-computer-networks-56", "question": "Assertion (A): An ARP request is sent as a layer-2 broadcast, but the ARP reply is normally unicast.\nReason (R): The requester does not yet know the target's MAC address, whereas the replier learns the requester's MAC from the request itself.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The request must reach every host because the target MAC is unknown (hence FF:FF:FF:FF:FF:FF). The request carries the sender's IP and MAC, so the target can reply straight to it with a unicast frame. R explains exactly why the two differ.", "difficulty": "hard", "source": "Wipro · Accenture pattern"},
  {"id": "cs-computer-networks-57", "question": "Assertion (A): DNS uses only UDP, because each query and answer fits in a single datagram.\nReason (R): UDP avoids the connection set-up delay of TCP.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "R is true, which is why ordinary lookups prefer UDP. A is false: DNS falls back to TCP port 53 when a response is truncated (too large for UDP) and always uses TCP for zone transfers, and DNS-over-TLS also runs on TCP.", "difficulty": "hard", "source": "IBM · Deloitte pattern"},
  {"id": "cs-computer-networks-58", "question": "How many of the following statements about DHCP are correct?\n1. The DHCPDISCOVER message is broadcast with source IP 0.0.0.0.\n2. DHCP servers listen on UDP port 67 and clients on UDP port 68.\n3. When the DHCP server is on a different subnet, a relay agent (for example ip helper-address on the router) is needed.\n4. A server can always give a particular client the same address through a reservation tied to its MAC address.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Addresses are normally leased (renewal tried at T1 = 50% and rebinding at T2 = 87.5% of the lease), but a reservation (static binding) on the server hands the same address to a given MAC every time.", "difficulty": "hard", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-computer-networks-59", "question": "How many of the following statements about NAT are correct?\n1. NAT breaks the end-to-end principle because outside hosts cannot start connections to inside hosts without port forwarding.\n2. IPsec AH works through NAT unchanged because AH does not protect the IP header.\n3. NAT must recompute the IP header checksum and also the TCP/UDP checksum when it rewrites addresses.\n4. NAT also rewrites the MAC addresses of inside hosts so that they stay hidden on the Internet.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "1 and 3 are correct (the TCP/UDP checksum covers a pseudo-header containing the IP addresses, so it must be fixed). 2 is wrong: AH authenticates the immutable IP header fields including the addresses, so NAT's rewrite makes the AH check fail. 4 is wrong: MAC addresses never leave the local link anyway; each router rewrites the layer-2 header hop by hop, NAT or not. So two are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-60","question":"A 5000-byte IPv4 datagram (20-byte header) must cross a link with MTU 1420 bytes. What are the fragment offset and total length of the last fragment?","options":["Offset 4200, total length 800 bytes","Offset 525, total length 780 bytes","Offset 525, total length 800 bytes","Offset 350, total length 1420 bytes"],"answer":2,"explanation":"Data per fragment = 1400 bytes (1420 − 20, already a multiple of 8). 4980 data bytes → 1400 + 1400 + 1400 + 780, i.e. 4 fragments. The last starts at byte 4200 → offset 4200/8 = 525, and its total length is 780 + 20 = 800. 780 forgets the header; 4200 forgets the 8-byte unit.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-61","question":"A code has exactly four codewords: 00000, 01011, 10101 and 11110. Which statement about its error handling is correct?","options":["It can detect up to 4-bit errors and correct 2-bit errors","It can detect up to 3-bit errors and correct 2-bit errors","It can detect 1-bit errors but correct none","It can detect up to 2-bit errors and correct 1-bit errors"],"answer":3,"explanation":"Pairwise distances are 3, 3, 4, 4, 3, 3, so d_min = 3 (take the minimum, not the largest 4). Detect d_min − 1 = 2 errors; correct ⌊(d_min − 1)/2⌋ = 1 error.","difficulty":"hard","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-computer-networks-62","question":"In slotted ALOHA, the offered load is G = 2 frames per slot. What fraction of slots carry a successful frame?","options":["About 0.27","About 0.37","About 0.14","About 0.04"],"answer":0,"explanation":"Slotted ALOHA: S = G·e^(−G) = 2 × e^(−2) ≈ 2 × 0.135 ≈ 0.271. 0.37 is the peak, reached only at G = 1; 0.14 drops the factor G (e^(−2) alone); 0.04 wrongly uses the pure-ALOHA formula 2·e^(−4).","difficulty":"hard","source":"Wipro · Accenture pattern"},
  {"id": "cs-computer-networks-63", "question": "For the host 131.45.214.9/22, how many usable host addresses does its subnet have, and what is the last usable host address?", "options": ["1022 hosts; last host 131.45.214.254", "1022 hosts; last host 131.45.215.254", "1024 hosts; last host 131.45.215.255", "510 hosts; last host 131.45.215.254"], "answer": 1, "explanation": "/22 → third octet in blocks of 4: 212–215. Network 131.45.212.0, broadcast 131.45.215.255. Host bits = 10 → 2¹⁰ − 2 = 1022 usable, and the last usable is one below the broadcast: 131.45.215.254.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-64","question":"Which one of these is NOT a function of the transport layer?","options":["Splitting application data into segments and reassembling them","Delivering data to the right process using port numbers","Choosing the route a packet takes across routers","End-to-end flow control between the two hosts"],"answer":2,"explanation":"Segmentation, process-to-process delivery (ports) and end-to-end flow/error control belong to the transport layer. Path selection across routers is a network-layer job.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-computer-networks-65", "question": "How many of the following statements about IPv6 are correct?\n1. The base IPv6 header has a fixed size of 40 bytes.\n2. IPv6 has no broadcast; multicast and anycast replace it.\n3. Routers fragment IPv6 packets when they exceed the next link's MTU.\n4. The IPv6 header drops the header checksum that IPv4 has.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 2 and 4 are correct. 3 is wrong: in IPv6 only the source host fragments (using the Fragment extension header after Path MTU discovery); routers drop oversized packets and send ICMPv6 Packet Too Big. So three are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-66", "question": "How many of the following statements about HTTPS (TLS) are correct?\n1. The server's certificate lets the client verify the server's identity through a chain of trusted CAs.\n2. Bulk application data is encrypted with a symmetric session key agreed during the handshake.\n3. HTTPS hides the destination IP address of the server from on-path observers.\n4. In TLS 1.3 the server's certificate travels in plaintext so that middleboxes can inspect it.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "1 and 2 are correct. 3 is wrong: the IP header is outside TLS, so the server's address (and usually the hostname via SNI) is still visible. 4 is wrong: TLS 1.3 encrypts everything after ServerHello, including the certificate, using handshake keys. So two are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-67", "question": "A 100 Mbps path has a one-way propagation delay of 25 ms. To keep it full, a TCP sender needs a window equal to the bandwidth-delay product of one RTT. What is the smallest TCP window-scale shift count that allows this window?", "options": ["3", "5", "9", "4"], "answer": 3, "explanation": "BDP = 100 × 10⁶ × 0.05 s = 5 × 10⁶ bits = 625,000 bytes. The 16-bit window field holds at most 65,535; 65,535 × 2³ = 524,280 is too small, while 65,535 × 2⁴ = 1,048,560 suffices, so shift = 4. Using one-way delay (312,500 bytes) would wrongly suggest 3.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-68", "question": "How many of the following OSI layer descriptions are correct?\n1. The session layer manages dialogue control and synchronisation checkpoints.\n2. The presentation layer handles translation, encryption and compression.\n3. The transport layer provides end-to-end (process-to-process) delivery.\n4. The data link layer provides node-to-node delivery and detects errors using a trailer such as the FCS.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are standard OSI descriptions. The tempting doubt is 4, but framing, MAC addressing and error detection with a frame check sequence (CRC trailer) are exactly the data link layer's node-to-node job; ports belong to the transport layer.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-computer-networks-69", "question": "Which of these addresses (written with its prefix length) can be assigned to a host interface?", "options": ["172.17.0.0/15", "10.10.15.255/20", "10.10.16.0/20", "192.168.1.255/23"], "answer": 0, "explanation": "172.16.0.0/15 spans 172.16.0.0–172.17.255.255, so 172.17.0.0 is an ordinary host address in the middle of the block despite ending in .0. 10.10.15.255/20 and 192.168.1.255/23 are broadcast addresses, and 10.10.16.0/20 is a network address.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-70", "question": "Go-Back-N with window size 3 sends frames 1 to 7. The first transmission of frame 3 is lost; nothing else is lost. The sender fills its window before frame 3's timer expires. How many frame transmissions take place in total?", "options": ["8", "10", "9", "11"], "answer": 1, "explanation": "Frames 1, 2, 3(lost) go out; ACKs for 1 and 2 slide the window so 4 and 5 are sent (5 so far) but the receiver discards them. Frame 3 times out, so 3, 4, 5 are resent (8), then 6 and 7 (10). Selective Repeat would need only 8.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-71", "question": "What is the 16-bit Internet checksum (ones'-complement of the ones'-complement sum) of the words 0xF0F0 and 0x1F1F?", "options": ["0x100F", "0x1010", "0xEFEF", "0xEFF0"], "answer": 2, "explanation": "0xF0F0 + 0x1F1F = 0x1100F. Fold the carry: 0x100F + 0x1 = 0x1010. Complement: 0xEFEF. Skipping the carry wrap-around gives ~0x100F = 0xEFF0.", "difficulty": "hard", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-computer-networks-72","question":"Which set contains ONLY protocols that normally run over UDP?","options":["HTTP/2, TFTP, SNMP","FTP, SNMP, DHCP","TFTP, SMTP, DNS zone transfer","TFTP, SNMP, DHCP"],"answer":3,"explanation":"TFTP (69), SNMP (161/162) and DHCP (67/68) use UDP. FTP, SMTP, DNS zone transfers and HTTP/2 run over TCP (HTTP/3 is the one on QUIC/UDP).","difficulty":"moderate","source":"Wipro · Accenture pattern"},
  {"id": "cs-computer-networks-73", "question": "How many of the following statements about routing protocols are correct?\n1. RIP uses hop count and treats 16 hops as unreachable.\n2. OSPF is a link-state protocol in which every router runs Dijkstra on its link-state database.\n3. Split horizon with poison reverse completely removes count-to-infinity in every topology.\n4. BGP is a path-vector protocol used between autonomous systems.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 2 and 4 are correct. 3 is wrong: split horizon and poison reverse fix two-node loops, but loops of three or more routers can still count to infinity. So three are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-74", "question": "How many of the following statements about the CRC generator x³ + x + 1 (1011) are correct?\n1. It detects every single-bit error.\n2. It detects every burst error of length 3 or less.\n3. It detects every error that flips an odd number of bits.\n4. The CRC it produces is 3 bits long.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 2 and 4 are correct (degree 3 → 3-bit CRC, catches all bursts ≤ 3). 3 is false: a generator detects all odd-weight errors only if it has (x + 1) as a factor, i.e. if it evaluates to 0 at x = 1; here 1 + 1 + 1 = 1 (mod 2), so (x + 1) is not a factor. So three are correct.", "difficulty": "hard", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-computer-networks-75","question":"A router forwards an IPv4 packet with no fragmentation, no NAT and no options. Which fields of the IP header does it change?","options":["TTL and header checksum only","TTL, header checksum and identification","TTL, header checksum and source IP address","TTL only"],"answer":0,"explanation":"The router decrements TTL, and because the header changed it must recompute the header checksum. Identification and addresses are untouched (addresses change only with NAT); the MAC addresses do change, but they are in the frame header, not the IP header.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id":"cs-computer-networks-76","question":"Which OSI layer is responsible for data format translation, encryption and compression, so that the receiving application can understand the data?","options":["Session layer","Presentation layer","Application layer","Transport layer"],"answer":1,"explanation":"The presentation layer handles syntax and representation: character encoding, encryption and compression. The session layer manages dialogues (sessions); the application layer provides network services to the user program.","difficulty":"easy","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-77","question":"An email client sends an outgoing message to its mail server. Which protocol does it normally use for this step?","options":["POP3","IMAP","SMTP","SNMP"],"answer":2,"explanation":"SMTP is used to send (push) mail, both client-to-server and server-to-server. POP3 and IMAP are used to retrieve mail from a mailbox; SNMP is for network management.","difficulty":"easy","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-computer-networks-78","question":"A network 10.5.6.0/26 is to be split into equal subnets of size /29. How many such subnets can be made?","options":["6","3","16","8"],"answer":3,"explanation":"Going from /26 to /29 borrows 3 bits, giving 2³ = 8 subnets (each with 8 addresses, 6 usable). 6 confuses the subnet count with the usable hosts per /29.","difficulty":"moderate","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-computer-networks-79","question":"What are the minimum header sizes of a UDP datagram and a TCP segment?","options":["UDP 8 bytes, TCP 20 bytes","UDP 20 bytes, TCP 20 bytes","UDP 8 bytes, TCP 60 bytes","UDP 4 bytes, TCP 20 bytes"],"answer":0,"explanation":"UDP has a fixed 8-byte header (ports, length, checksum). TCP needs at least 20 bytes and up to 60 bytes with options. 60 bytes is TCP’s maximum, not minimum.","difficulty":"easy","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-80","question":"What is the network address of the subnet that contains the host 192.168.10.77/27?","options":["192.168.10.72","192.168.10.64","192.168.10.0","192.168.10.96"],"answer":1,"explanation":"A /27 has blocks of 32 in the last octet: 0, 32, 64, 96, … 77 falls in 64–95, so the network is 192.168.10.64 (broadcast .95). .96 is the next subnet.","difficulty":"moderate","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-computer-networks-81","question":"Which DNS record type maps a host name to an IPv6 address?","options":["A","CNAME","AAAA","PTR"],"answer":2,"explanation":"AAAA (“quad-A”) records hold 128-bit IPv6 addresses; A records hold IPv4 addresses. CNAME is an alias to another name, and PTR maps an address back to a name.","difficulty":"easy","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-82","question":"A switch receives a frame whose destination MAC address is not yet in its MAC address table. What does the switch do?","options":["Drops the frame and sends an ICMP error","Sends an ARP request for the destination MAC","Sends the frame back out of the incoming port","Floods the frame out of every port except the one it arrived on"],"answer":3,"explanation":"An unknown unicast is flooded to all other ports in the VLAN; when the destination replies, the switch learns its port. Switches do not send ICMP or ARP for frames they forward — those are layer-3 mechanisms.","difficulty":"easy","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-computer-networks-83","question":"A video-calling app sends small voice packets every 20 ms. Why do such apps usually prefer UDP over TCP for the media stream?","options":["A late packet is useless, and TCP’s retransmission with in-order delivery would hold back newer packets behind a lost one","UDP encrypts packets, while TCP does not","TCP cannot carry packets smaller than 1 KB","UDP guarantees delivery faster than TCP"],"answer":0,"explanation":"For real-time audio, a retransmitted packet arrives too late to be played, and TCP would also block all later data until the gap is filled (head-of-line blocking). UDP lets the app skip losses. UDP guarantees nothing, and neither protocol encrypts by itself.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-84","question":"What is the broadcast address of the subnet containing 10.20.30.40/13?","options":["10.20.255.255","10.23.255.255","10.31.255.255","10.16.255.255"],"answer":1,"explanation":"A /13 mask is 255.248.0.0, so the second octet moves in blocks of 8: 16–23 contains 20. Network 10.16.0.0, broadcast 10.23.255.255. 10.20.255.255 treats it like a /16.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-85","question":"Which address is in the same subnet as 172.16.8.1/21?","options":["172.16.16.1","172.16.7.255","172.16.15.254","172.17.8.1"],"answer":2,"explanation":"A /21 mask is 255.255.248.0: the third octet moves in blocks of 8, so 172.16.8.0/21 spans 172.16.8.0 to 172.16.15.255. Only 172.16.15.254 falls inside. 172.16.7.255 is the broadcast of the previous block.","difficulty":"moderate","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-computer-networks-86","question":"A sender transmits bytes 1–4000 as four 1000-byte TCP segments. Segment 2 (bytes 1001–2000) is lost; segments 1, 3 and 4 arrive in order. Using cumulative acknowledgements (ACK = next byte expected), which ACK numbers does the receiver send?","options":["1001, 3001, 4001","1000, 1000, 1000","1001, 2001, 4001","1001, 1001, 1001"],"answer":3,"explanation":"After segment 1 the receiver expects byte 1001. Segments 3 and 4 are out of order, so each triggers a duplicate ACK for 1001. Two duplicates after the original ACK are what fast retransmit counts. 1000 forgets that the ACK names the NEXT byte expected.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-87","question":"A 1 MB file (take 1 MB = 10⁶ bytes) is sent in one burst over an 8 Mbps link with a one-way propagation delay of 20 ms. How long after the first bit is sent does the last bit arrive?","options":["1.02 s","1 s","0.145 s","1.04 s"],"answer":0,"explanation":"Transmission time = 8 × 10⁶ bits / 8 × 10⁶ bps = 1 s; the last bit then needs 20 ms to propagate: 1.02 s. 0.145 s treats MB as megabits; 1.04 s adds a round trip.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-computer-networks-88","question":"An organisation owns 172.20.0.0/16 and needs equal-sized subnets, each with at least 1000 usable host addresses. What is the maximum number of such subnets?","options":["32","64","128","16"],"answer":1,"explanation":"1000 hosts need 10 host bits (2¹⁰ − 2 = 1022; 9 bits give only 510). That makes each subnet a /22, and 16 − 10 = 6 bits are left for subnetting: 2⁶ = 64. 128 uses only 9 host bits.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-89","question":"An access-control list needs the wildcard mask that corresponds to the subnet mask 255.255.248.0. What is it?","options":["0.0.8.255","0.0.248.255","0.0.7.255","255.255.7.0"],"answer":2,"explanation":"A wildcard mask is the bitwise inverse of the subnet mask: 255 − each octet = 0.0.7.255. 0.0.8.255 is the block size, not its inverse.","difficulty":"moderate","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-computer-networks-90","question":"In distance-vector routing, which technique stops a router from advertising a route back out of the interface through which it learned that route?","options":["Route poisoning","Hold-down timer","Triggered update","Split horizon"],"answer":3,"explanation":"Split horizon suppresses advertising a route back towards the neighbour it came from, which breaks simple two-router loops. Route poisoning advertises a failed route with infinite metric; hold-down timers ignore new information briefly; triggered updates send changes immediately.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-91","question":"An ISP wants to advertise the eight networks 192.168.4.0/24 through 192.168.11.0/24 with a single CIDR prefix. What is the smallest single prefix that covers all of them?","options":["192.168.0.0/20","192.168.4.0/21","192.168.8.0/21","192.168.4.0/22"],"answer":0,"explanation":"Eight /24s would fit a /21, but /21 blocks must start at a multiple of 8 in the third octet: 0–7 or 8–15. The range 4–11 crosses that boundary, so the smallest single block is 192.168.0.0/20 (third octet 0–15). 192.168.4.0/21 is not a valid network address.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-computer-networks-92","question":"You type https://shop.example.com into a browser that has nothing cached. In which order do these happen?\n1. TLS handshake\n2. DNS resolution\n3. HTTP GET request\n4. TCP three-way handshake","options":["2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1","2, 4, 1, 3"],"answer":3,"explanation":"The browser first needs the IP address (DNS), then a TCP connection, then TLS on top of TCP, and only then sends the HTTP request inside the encrypted channel. TLS cannot start before TCP is established, and the GET must be encrypted, so it comes last.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-93","question":"What is the shortest valid form of the IPv6 address 2001:0db8:0000:0000:0000:ff00:0042:8329?","options":["2001:db8::ff:42:8329","2001:db8::ff00:42:8329","2001:db8:0:0:0:ff00:42:8329:","2001:db8::ff00::42:8329"],"answer":1,"explanation":"Drop leading zeros in each group (0db8 → db8, 0042 → 42) and replace the single longest run of zero groups with ::. “ff00” keeps its trailing zeros; :: may appear only once, so the last option is invalid.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-94","question":"Starting from 172.16.32.0/23, subnets are allocated largest first, each at the next aligned boundary, for LANs needing 200, 100 and 50 hosts. What is the broadcast address of the 50-host subnet?","options":["172.16.33.127","172.16.32.255","172.16.33.191","172.16.33.255"],"answer":2,"explanation":"200 hosts → /24: 172.16.32.0/24. 100 hosts → /25: 172.16.33.0/25. 50 hosts → /26: 172.16.33.128/26, whose broadcast is 172.16.33.191. 172.16.33.127 is the broadcast of the 100-host subnet.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-computer-networks-95","question":"A web server listens on TCP port 443. Three browsers on the same client machine connect to it at the same time. How does the server’s operating system tell the three connections apart?","options":["By the 4-tuple (source IP, source port, destination IP, destination port); each browser connection uses a different source port","The server opens a new listening port for each connection","By the client’s MAC address in each frame","It cannot; only one connection per client IP is allowed"],"answer":0,"explanation":"A TCP connection is identified by its 4-tuple. All three share the server IP and port 443 and the client IP, but the client OS gives each an ephemeral source port. The listening port does not change, and MAC addresses do not survive routers.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-96","question":"A TCP sender has cwnd = 12 KB. The receiver last advertised a window of 8 KB, and 3 KB of data is already sent but not yet acknowledged. How much more new data may the sender transmit right now?","options":["9 KB","5 KB","8 KB","12 KB"],"answer":1,"explanation":"Effective window = min(cwnd, rwnd) = min(12, 8) = 8 KB. With 3 KB already in flight, 8 − 3 = 5 KB more can be sent. 9 KB uses cwnd and ignores the receiver’s limit.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-computer-networks-97","question":"For the host 200.1.1.100/28, what are the first and last usable host addresses of its subnet?","options":["200.1.1.96 and 200.1.1.111","200.1.1.97 and 200.1.1.111","200.1.1.97 and 200.1.1.110","200.1.1.101 and 200.1.1.114"],"answer":2,"explanation":"A /28 has blocks of 16: 96–111 contains 100. 96 is the network address and 111 the broadcast, so usable hosts are .97 to .110. The first option lists the network and broadcast addresses themselves.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-98","question":"A TCP Reno sender starts transmission round 1 with cwnd = 1 MSS and ssthresh = 32 MSS. In slow start cwnd doubles every round but is never raised above ssthresh; at or above ssthresh it grows by 1 MSS per round. A loss is detected by three duplicate ACKs during round 9 and by a timeout during round 15. On triple duplicate ACK, ssthresh = floor(cwnd/2) and the next round starts with cwnd = ssthresh; on timeout, ssthresh = floor(cwnd/2) and cwnd restarts at 1 MSS. What is cwnd in round 22?","options":["13 MSS","18 MSS","12 MSS","14 MSS"],"answer":0,"explanation":"Rounds 1-6: 1, 2, 4, 8, 16, 32 (slow start reaches ssthresh). Rounds 7-9: 33, 34, 35. Triple duplicate ACK at 35: ssthresh = 17, and rounds 10-15 are 17, 18, 19, 20, 21, 22. Timeout at 22: ssthresh = 11, cwnd = 1. Rounds 16-19: 1, 2, 4, 8. Doubling 8 would give 16, above ssthresh, so round 20 is 11, then 12 and 13 in rounds 21 and 22. The 18 MSS answer comes from letting slow start overshoot to 16 and then adding 1 per round; 12 is the value one round too early.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-99","question":"A TCP sender must deliver a file of exactly 100 segments. It starts with cwnd = 1 segment and ssthresh = 8 segments; cwnd doubles per round below ssthresh and grows by 1 per round from ssthresh onwards. The receiver advertises a constant window of 10 segments, there are no losses, and in each round the sender transmits min(cwnd, receiver window) segments. In which round is the last segment of the file sent?","options":["Round 12","Round 13","Round 7","Round 11"],"answer":1,"explanation":"Segments per round: 1, 2, 4, 8 (slow start), then 9, 10 in congestion avoidance. From round 7 onwards cwnd is 11 or more, but the receiver window caps each round at 10. Running total: 1, 3, 7, 15, 24, 34 after six rounds, then +10 per round: 44, 54, 64, 74, 84, 94, 104. The total first reaches 100 in round 13. Ignoring the receiver window gives round 12 (57, 70, 84, 99, 115); pure doubling with no threshold gives round 7.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-100","question":"A TCP sender has EstimatedRTT = 100 ms and DevRTT = 10 ms. Two new RTT samples arrive: 140 ms, then 80 ms. For each sample it first updates DevRTT = 0.75 x DevRTT + 0.25 x |Sample - EstimatedRTT| using the old EstimatedRTT, and then EstimatedRTT = 0.875 x EstimatedRTT + 0.125 x Sample. With timeout = EstimatedRTT + 4 x DevRTT, what is the retransmission timeout after the second sample?","options":["140.625 ms","172.5 ms","179.375 ms","181.875 ms"],"answer":2,"explanation":"Sample 140: DevRTT = 7.5 + 0.25 x 40 = 17.5; EstimatedRTT = 87.5 + 17.5 = 105. Sample 80: DevRTT = 13.125 + 0.25 x |80 - 105| = 13.125 + 6.25 = 19.375; EstimatedRTT = 91.875 + 10 = 101.875. Timeout = 101.875 + 4 x 19.375 = 179.375 ms. Updating EstimatedRTT before DevRTT gives 172.5 ms, which is not the order stated; adding only 2 x DevRTT gives 140.625 ms.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-101","question":"A client opens a TCP connection with initial sequence number 5000; the server chooses 9000. After the three-way handshake the client sends three data segments of 400, 300 and 500 bytes, the server replies with one segment of 700 bytes, and all data is acknowledged. The client then sends a FIN carrying no data. What are the sequence number and acknowledgment number in that FIN segment, and what acknowledgment number does the server use to acknowledge the FIN?","options":["FIN: seq 6201, ack 9700; server acknowledges 6202","FIN: seq 6200, ack 9700; server acknowledges 6201","FIN: seq 6201, ack 9701; server acknowledges 6201","FIN: seq 6201, ack 9701; server acknowledges 6202"],"answer":3,"explanation":"A SYN consumes one sequence number, so the client's first data byte is 5001 and the server's is 9001. After 400 + 300 + 500 = 1200 bytes the client's next sequence number is 6201, which the FIN uses. The server sent bytes 9001-9700, so the client acknowledges 9701. A FIN also consumes one sequence number, so the server acknowledges 6202. The answers with 6200 or 9700 forget that the SYN used a number; acknowledging 6201 forgets that the FIN does too.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-102","question":"Two stations 3000 km apart are joined by a 4 Mbps link on which signals travel at 2 x 10^8 m/s. Frames are 2000 bytes long, ACKs are negligibly short and there are no errors. With Go-Back-N and a sender window of 5 frames, what is the throughput?","options":["About 2.35 Mbps","About 0.47 Mbps","About 2.67 Mbps","4 Mbps"],"answer":0,"explanation":"Transmission time Tt = 16000 bits / 4 Mbps = 4 ms; propagation time Tp = 3000 km / (2 x 10^8 m/s) = 15 ms. One cycle is Tt + 2Tp = 34 ms, i.e. 1 + 2a = 8.5 frame times. In each cycle the sender can send only 5 frames, so utilisation = 5/8.5 = 0.588 and throughput = 0.588 x 4 = 2.35 Mbps. 0.47 Mbps is the stop-and-wait figure (1/8.5); 2.67 Mbps uses 1 + a instead of 1 + 2a; 4 Mbps would need a window of at least 9.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-103","question":"A stop-and-wait link runs at 1 Mbps with a one-way propagation delay of 10 ms. Data frames are 5000 bits, ACKs are 500 bits, and each data frame is lost independently with probability 0.2 (ACKs are never lost). The timeout is set exactly equal to the time of one successful send-and-acknowledge cycle. What is the expected throughput of data bits?","options":["About 196.1 kbps","About 156.9 kbps","160 kbps","800 kbps"],"answer":1,"explanation":"One cycle = frame 5 ms + propagation 10 ms + ACK 0.5 ms + propagation 10 ms = 25.5 ms, and a failed attempt costs the same because the timeout equals the cycle. Expected attempts per frame = 1/(1 - 0.2) = 1.25, so each frame takes 31.875 ms on average. Throughput = 5000 bits / 31.875 ms = 156.9 kbps. 196.1 kbps ignores the losses, 160 kbps ignores the ACK's transmission time, and 800 kbps is just 0.8 x the link rate.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-104","question":"A sender must deliver frames 1 to 12. Every 6th frame transmission (counting retransmissions too) is lost; ACKs are never lost. With Go-Back-N and window size 4, after a frame is lost the sender still transmits the following frames of its window (up to 3 more, if they exist) before it times out and goes back to the lost frame. With Selective Repeat only the lost frame is resent. How many frame transmissions are needed in total under Go-Back-N and under Selective Repeat?","options":["21 and 14","23 and 15","23 and 14","19 and 15"],"answer":2,"explanation":"Go-Back-N: transmissions 1-5 carry frames 1-5; the 6th (frame 6) is lost, then frames 7, 8, 9 are sent uselessly (transmissions 7-9). Go back: 6, 7, then frame 8 is the 12th transmission and is lost; 9, 10, 11 follow (13-15). Go back: 8, 9, then frame 10 is the 18th and is lost; 11, 12 follow (19, 20). Go back: 10, 11, 12 (21-23). Total 23. Selective Repeat: 12 frames plus one retransmission per loss; with 14 transmissions two (the 6th and 12th) are lost and 12 succeed, so 14. Counting 15 assumes a third loss that is never needed.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-105","question":"A stop-and-wait sender has 6 frames to deliver over a 100 kbps link with one-way propagation delay 20 ms. Frames are 1000 bits and ACKs are negligibly short. A 60 ms retransmission timer is started when the last bit of a frame leaves the sender. Every 3rd frame transmission (counting retransmissions) is lost; ACKs are never lost. How long after the start is the ACK of the sixth frame received?","options":["400 ms","300 ms","420 ms","440 ms"],"answer":3,"explanation":"Frame time = 1000/100 kbps = 10 ms. A successful transmission takes 10 + 2 x 20 = 50 ms; a lost one takes 10 + 60 = 70 ms before the retransmission starts. Six frames must succeed: of the first 8 transmissions the 3rd and 6th are lost and six succeed. Time = 6 x 50 + 2 x 70 = 440 ms. 300 ms ignores the losses; 420 ms starts the timer when the frame starts instead of when it ends; 400 ms treats a lost attempt as costing only 50 ms.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-106","question":"A 20 Mbps link has a one-way propagation delay of 8 ms and carries 1250-byte frames; ACKs are negligibly short. The sender window is chosen as the smallest size that keeps the link 100% utilised. What is the minimum number of sequence-number bits needed for Go-Back-N and for Selective Repeat (receiver window equal to sender window) respectively?","options":["6 bits and 7 bits","6 bits and 6 bits","5 bits and 6 bits","7 bits and 8 bits"],"answer":0,"explanation":"Tt = 10000 bits / 20 Mbps = 0.5 ms, so a = 8/0.5 = 16 and the window for full utilisation is 1 + 2a = 33 frames. Go-Back-N needs at least W + 1 = 34 sequence numbers, so 6 bits (64). Selective Repeat needs at least 2W = 66 sequence numbers, so 7 bits (128); 6 bits give only 64. Using a window of 1 + a = 17 leads to 5 and 6 bits, and forgetting the 2W rule gives 6 and 6.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-107","question":"An IPv4 datagram of total length 4020 bytes (20-byte header, no options) is forwarded over a link with MTU 1500 bytes and then over a link with MTU 620 bytes. Each router fragments whatever it receives into the largest fragments its outgoing link allows, and nothing is reassembled until the destination. How many fragments reach the destination, and what is the fragment-offset field of the one carrying the final bytes of the payload?","options":["7 fragments; offset 450","8 fragments; offset 445","8 fragments; offset 450","8 fragments; offset 3560"],"answer":1,"explanation":"MTU 1500 allows 1480 payload bytes: the 4000-byte payload becomes 1480 + 1480 + 1040 (offsets 0, 185, 370). MTU 620 allows 600 payload bytes: each 1480-byte fragment becomes 600 + 600 + 280 and the 1040-byte one becomes 600 + 440, giving 3 + 3 + 2 = 8 fragments. The last starts at payload byte 2960 + 600 = 3560, so its offset field is 3560/8 = 445 (length 440 + 20 = 460). Fragmenting the original directly at MTU 620 would give 7 fragments with last offset 450, but routers re-fragment the fragments they receive; 3560 is the byte position, not the field value in 8-byte units.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-108","question":"A router receives an IPv4 fragment with header length field 5, total length 1196, fragment offset 294 and the More Fragments bit set. Numbering the original datagram's payload bytes from 0, which bytes does this fragment carry, and what fragment-offset value will the next fragment of the same datagram have?","options":["Bytes 2352 to 3547; next offset 444","Bytes 294 to 1469; next offset 1470","Bytes 2352 to 3527; next offset 441","Bytes 2352 to 3527; next offset 442"],"answer":2,"explanation":"Header = 5 x 4 = 20 bytes, so the payload is 1196 - 20 = 1176 bytes. The offset is in units of 8 bytes: first byte = 294 x 8 = 2352, last byte = 2352 + 1176 - 1 = 3527. The next fragment starts at byte 3528, i.e. offset 3528/8 = 441. Treating the offset as a byte count gives 294 to 1469; using the total length 1196 as the payload gives 3547; 442 is an off-by-one, since 1176/8 = 147 exactly and 294 + 147 = 441.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-109","question":"A sender protects the 10-bit message 1011001110 with a CRC using the generator 10011 (x^4 + x + 1) and transmits the resulting 14-bit codeword. Each string below is a corrupted version of that codeword. Which one will the receiver's CRC check accept as error-free?","options":["10110011110100","10111010100101","10000111100101","10111010000101"],"answer":3,"explanation":"Dividing 10110011100000 by 10011 (modulo 2) leaves remainder 0101, so the codeword is 10110011100101. An error goes undetected only if the error pattern itself is divisible by the generator. 10111010000101 differs from the codeword in bit positions 5, 8 and 9 from the left, i.e. the error pattern is 10011 shifted - a multiple of the generator - so the remainder is still 0000. The others have error patterns with two bits, or a burst of at most 4 bits, which x^4 + x + 1 always detects (remainders 0110, 1100 and 0010).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-110","question":"A 12-bit Hamming codeword protects 8 data bits. Positions are numbered 1 to 12 from the left, even-parity check bits sit at positions 1, 2, 4 and 8 (the check bit at position p covers every position whose binary number has bit p set), and data bits fill positions 3, 5, 6, 7, 9, 10, 11, 12 in order. The word 001001110000 is received with at most one bit in error. Which position is in error, and what 8 data bits were sent?","options":["Position 10; data 10110100","No data bit is wrong; data 10110000","Position 5; data 11110000","Position 12; data 10110001"],"answer":0,"explanation":"Recompute the four parity checks on 001001110000: check 1 (positions 1,3,5,7,9,11) is even, check 2 (2,3,6,7,10,11) is odd, check 4 (4,5,6,7,12) is even, check 8 (8,9,10,11,12) is odd. The failing checks sum to 2 + 8 = 10, so position 10 is wrong. Flipping it gives 001001110100, whose data bits (positions 3,5,6,7,9,10,11,12) are 10110100. Reading the syndrome bits in reverse order points to position 5, which is the trap; leaving the word uncorrected gives 10110000.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-111","question":"A 100 Mbps CSMA/CD network has its two farthest stations 500 m of cable apart, with two repeaters on the path between them. Signals travel at 2 x 10^8 m/s in the cable and each repeater adds a delay of 1 microsecond in each direction. What is the minimum frame size that guarantees a station is still transmitting when a collision reaches it?","options":["500 bits","900 bits","450 bits","700 bits"],"answer":1,"explanation":"One-way delay = 500/(2 x 10^8) s = 2.5 microseconds of cable + 2 x 1 microsecond of repeaters = 4.5 microseconds. The frame must last a full round trip, 9 microseconds, so it needs 9 x 10^-6 x 100 x 10^6 = 900 bits. 500 bits ignores the repeaters, 450 bits uses only the one-way delay, and 700 bits counts the repeater delay in one direction only.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-112","question":"Two Ethernet stations A and B collide. For A this is the 1st collision of its current frame, so it picks its backoff K uniformly from {0, 1}; for B it is the 3rd collision of its frame, so it picks K uniformly from {0, 1, ..., 7}. What is the probability that A picks a strictly smaller backoff than B and therefore transmits first?","options":["7/8","3/4","13/16","1/2"],"answer":2,"explanation":"There are 2 x 8 = 16 equally likely pairs. If A picks 0, B must pick 1-7: 7 pairs. If A picks 1, B must pick 2-7: 6 pairs. So P(A first) = 13/16. The remaining 3/16 splits into 2/16 for a repeat collision (equal picks) and 1/16 for B going first (A = 1, B = 0). 7/8 forgets the case where A picks 1; 1/2 wrongly treats the two stations as symmetric - binary exponential backoff favours the station with fewer collisions.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-113","question":"Routers A, B and C run a basic distance-vector protocol with no split horizon or poisoned reverse. Link costs are A-B = 3, B-C = 2 and A-C = 40, and the tables are stable (B reaches C at cost 2, A reaches C at cost 5 via B). The cost of link B-C now rises to 30. B recomputes first and advertises to A; from then on A and B alternately recompute and advertise whenever their distance to C changes. Counting every change of the distance-to-C entry at A or B (including B's first), how many changes occur before the tables are stable, and what are the final distances to C?","options":["8 changes; A = 29, B = 26","2 changes; A = 33, B = 30","10 changes; A = 40, B = 30","10 changes; A = 33, B = 30"],"answer":3,"explanation":"B still believes A can reach C at cost 5, so it picks min(30, 3 + 5) = 8 - a route that actually loops back through B. Then A: min(40, 3 + 8) = 11; B: 14; A: 17; B: 20; A: 23; B: 26; A: 29; B: min(30, 3 + 29) = 30; A: min(40, 3 + 30) = 33; B: min(30, 36) = 30, unchanged. B's entry took the values 8, 14, 20, 26, 30 and A's 11, 17, 23, 29, 33: 10 changes in all. Only 2 changes would be needed if B knew A's route went through B itself, which is what poisoned reverse provides. A does not end at 40 because 3 + 30 = 33 through B is cheaper than the direct link.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-114","question":"Five routers use distance-vector routing with link costs A-B = 1, B-C = 2, C-D = 1, D-E = 3, A-E = 12, A-D = 7 and B-D = 5. Initially each router knows only the costs of its own links. In each round all routers simultaneously send their current vectors to their neighbours and then all recompute. What is A's distance to E after exactly two rounds?","options":["9","10","7","12"],"answer":0,"explanation":"After r rounds a router knows the best path of at most r + 1 hops. Start: A-E = 12 (1 hop). After round 1 (2 hops): A-D-E = 7 + 3 = 10. After round 2 (3 hops): A-B-D-E = 1 + 5 + 3 = 9. Only after round 3 does A learn the true shortest path A-B-C-D-E = 1 + 2 + 1 + 3 = 7, which needs 4 hops. So after two rounds the entry is 9; 7 is the converged value, and 10 is the value one round earlier.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-115","question":"Dijkstra's algorithm is run from S on an undirected network with link costs S-A 7, S-B 2, S-C 6, A-B 3, B-D 8, A-D 4, B-C 5, C-E 5, D-E 1, D-F 6 and E-F 9. In what order are the nodes finalised, and what successive tentative labels does node E receive?","options":["S, B, A, C, D, E, F; E is labelled 10 only","S, B, A, C, D, E, F; E is labelled 11, then 10","S, B, C, A, D, E, F; E is labelled 11, then 10","S, B, A, D, C, E, F; E is labelled 10 only"],"answer":1,"explanation":"From S: A = 7, B = 2, C = 6. Finalise B (2): A improves to 5, D = 10, C stays 6 (2 + 5 = 7 is worse). Finalise A (5): D improves to 9. Finalise C (6): E = 11. Finalise D (9): E improves to 10, F = 15. Finalise E (10): F stays 15 (10 + 9 = 19). Finalise F (15). C (6) is finalised before D (9), so E is first labelled 11 through C and only later lowered to 10 through D. A (5) leaves the queue before C (6) because of the relaxation through B.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-116","question":"The block 10.20.64.0/20 is allocated with VLSM, always taking the lowest free addresses and handling requests in this order: LANs needing 900, 400, 200 and 100 hosts, then three point-to-point links needing 2 hosts each. Every subnet is the smallest that fits its need. Which subnet does the third point-to-point link receive, and how many addresses of the /20 are left unallocated?","options":["10.20.72.8/30; 2164 addresses","10.20.71.136/30; 2176 addresses","10.20.71.136/30; 2164 addresses","10.20.71.132/30; 2168 addresses"],"answer":2,"explanation":"900 hosts need a /22 (1022 usable): 10.20.64.0/22. 400 need a /23: 10.20.68.0/23. 200 need a /24: 10.20.70.0/24. 100 need a /25: 10.20.71.0/25. The links take /30s from 10.20.71.128: .128/30, .132/30 and .136/30. Allocated = 1024 + 512 + 256 + 128 + 3 x 4 = 1932 of 4096, leaving 2164. 2176 forgets the three /30s; 10.20.72.8/30 would follow only if the /25 had been rounded up to a /24; .132/30 is the second link, not the third.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-117","question":"A router uses longest-prefix matching with these entries: 10.4.0.0/14 -> interface A, 10.6.0.0/15 -> interface B, 10.6.128.0/17 -> interface C, 10.7.64.0/18 -> interface D. How many distinct destination IPv4 addresses are forwarded out of interface B?","options":["114688","131072","98304","81920"],"answer":3,"explanation":"10.6.0.0/15 covers 10.6.0.0-10.7.255.255, which is 2^17 = 131072 addresses. Two more specific entries lie inside it: 10.6.128.0/17 (2^15 = 32768 addresses) and 10.7.64.0/18 (2^14 = 16384 addresses), and a longer prefix always wins. So B gets 131072 - 32768 - 16384 = 81920. 131072 ignores both more-specific routes, and 98304 or 114688 subtract only one of them.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-118","question":"A site owns 172.18.72.0/22, 172.18.76.0/23 and 172.18.80.0/22 and wants to advertise them with one prefix. What is the smallest single prefix that covers all three, and how many addresses inside that prefix do NOT belong to any of the three networks?","options":["172.18.64.0/19; 5632 addresses","172.18.64.0/20; 1536 addresses","172.18.72.0/20; 1536 addresses","172.18.64.0/19; 2560 addresses"],"answer":0,"explanation":"The third octet runs from 72 (01001000) to 83 (01010011). These share only the leading bits 010, so the common prefix is 16 + 3 = 19 bits: 172.18.64.0/19, covering 64-95 in the third octet, 8192 addresses. The three networks hold 1024 + 512 + 1024 = 2560 addresses, so 8192 - 2560 = 5632 addresses are covered but not owned. A /20 starting at 64 stops at 79 and misses 172.18.80.0/22; 172.18.72.0/20 is not a valid block boundary; 2560 is the owned count, not the excess.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-119","question":"From the block 192.168.0.0/22, three subnets have already been assigned: 192.168.1.64/26, 192.168.2.0/25 and 192.168.3.240/28. How many /27 subnets of the block are still completely free (overlapping none of the assigned ranges)?","options":["26","25","24","28"],"answer":1,"explanation":"A /22 contains 2^(27-22) = 32 subnets of size /27 (32 addresses each). The /26 (64 addresses) occupies 2 of them, the /25 (128 addresses) occupies 4, and the /28 (16 addresses) spoils 1 more, because the /27 192.168.3.224/27 that contains it is no longer completely free. 32 - 2 - 4 - 1 = 25. Answering 26 forgets that a partly used /27 cannot be handed out.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-120","question":"Host X sends 10 packets of 1000 bytes each to host Y through two store-and-forward routers. The three links on the path have rates 2 Mbps, 1 Mbps and 4 Mbps in that order. X transmits the packets back to back starting at t = 0; propagation and processing delays are negligible and queues never overflow. At what time has Y completely received the last packet?","options":["50 ms","140 ms","86 ms","82 ms"],"answer":2,"explanation":"Each packet is 8000 bits, so it takes 4 ms, 8 ms and 2 ms on the three links. The first packet finishes the second link at 4 + 8 = 12 ms. That link is the bottleneck: packets arrive every 4 ms but leave every 8 ms, so packet 10 finishes it at 12 + 9 x 8 = 84 ms and reaches Y after 2 ms more, at 86 ms. 140 ms wrongly sends packets one at a time end to end (10 x 14 ms); 50 ms assumes the first link sets the pace (10 x 4 + 8 + 2).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-121","question":"A 4800-byte message is sent over a path of 4 store-and-forward links of equal rate (3 routers), with negligible propagation delay. The message is cut into equal packets, each carrying p bytes of data plus a 20-byte header, and the packets are sent back to back. Which of these values of p delivers the whole message soonest?","options":["p = 120 bytes","p = 1200 bytes","p = 480 bytes","p = 240 bytes"],"answer":3,"explanation":"With N packets over k links, the last packet arrives after (N + k - 1) packet transmission times, so the delay is proportional to (4800/p + 3) x (p + 20) byte-times. p = 1200: 7 x 1220 = 8540. p = 480: 13 x 500 = 6500. p = 240: 23 x 260 = 5980. p = 120: 43 x 140 = 6020. So 240 bytes is best: larger packets waste time being stored and forwarded whole at each hop, while at 120 bytes the header overhead starts to dominate.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-122","question":"A host is shaped by a token bucket of capacity 6 Mb that fills at 4 Mbps; the bucket is full at t = 0. The output link can carry at most 10 Mbps. A burst of 20 Mb of data becomes ready at t = 0. How long does it take to send the whole burst?","options":["3.5 s","5 s","2 s","2.5 s"],"answer":0,"explanation":"While tokens remain, the host sends at the 10 Mbps peak while tokens arrive at 4 Mbps, so the bucket drains at 6 Mbps and lasts S = 6/(10 - 4) = 1 s, in which 10 Mb are sent. The remaining 10 Mb can go only at the token rate of 4 Mbps, taking 2.5 s. Total 3.5 s. 5 s ignores the stored tokens (20/4), 2 s ignores the shaper altogether (20/10), and 2.5 s is only the second phase.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-123","question":"Stations sharing a 56 kbps pure ALOHA channel send 1000-bit frames. Together (new frames plus retransmissions) they attempt 28 frames per second, with attempts forming a Poisson process. How many frames per second get through successfully?","options":["About 17.0 frames/s","About 10.3 frames/s","28 frames/s","About 5.2 frames/s"],"answer":1,"explanation":"Frame time = 1000/56000 s, so the channel can carry 56 frames per second and the offered load is G = 28/56 = 0.5 frames per frame time. Pure ALOHA throughput is S = G x e^(-2G) = 0.5 x e^(-1) = 0.184 per frame time, i.e. 0.184 x 56 = 10.3 frames/s. 17.0 uses the slotted ALOHA formula G x e^(-G); 28 assumes no collisions at all.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-124","question":"An HDLC-style link uses the flag 01111110 and bit stuffing: the sender inserts a 0 after every run of five consecutive 1s in the data. The 27-bit data field 011111011111101111110011111 is to be sent. How many bits are transmitted between the opening and closing flags?","options":["29 bits","30 bits","31 bits","28 bits"],"answer":2,"explanation":"A 0 is stuffed after every five consecutive 1s, whatever the next data bit is. The data has runs of 5, 6, 6 and 5 ones. Each run gets exactly one stuffed 0 (in a run of six, the count restarts after the stuffed 0, and the single remaining 1 does not reach five). That is 4 stuffed bits: 0111110011111010111110100111110, so 27 + 4 = 31 bits. Stuffing only where a sixth 1 actually follows gives 29; skipping the run at the very end gives 30 - but without that last 0, the data's final 11111 followed by the flag's leading 0 would be safe only by luck, and the rule is applied mechanically.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-125","question":"Hosts A, B, C, D and E are each attached to their own port of one Ethernet switch whose MAC table is empty. These frames are then sent in order (source -> destination): A -> B, B -> A, C -> A, D -> C, A -> E, E -> D, B -> E, and finally C sends a broadcast frame. How many of these eight frames are delivered to host D's port?","options":["5","3","2","4"],"answer":3,"explanation":"The switch learns the source of every frame and floods a frame only if the destination is unknown or broadcast. A -> B: B unknown, flooded (D sees it). B -> A and C -> A: A is known, forwarded only to A. D -> C: C is known, forwarded only to C. A -> E: E has not sent anything yet, so it is flooded (D sees it). E -> D: D is known, delivered to D. B -> E: E is now known, forwarded only to E. The broadcast from C reaches every port, including D. D's port therefore carries 4 frames: two unknown-unicast floods, one frame addressed to D, and the broadcast.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-126","question":"A leaky bucket holds at most 5 packets. In each clock tick, newly arrived packets are first placed in the bucket (those that do not fit are dropped), and then up to 2 packets are sent. The bucket starts empty and the arrivals in ticks 1 to 6 are 4, 5, 0, 6, 1 and 3 packets. After tick 6, how many packets have been dropped and how many are still waiting in the bucket?","options":["4 dropped; 3 waiting","2 dropped; 5 waiting","4 dropped; 5 waiting","7 dropped; 0 waiting"],"answer":0,"explanation":"Tick 1: 4 in, send 2, 2 left. Tick 2: 2 + 5 = 7, two dropped, 5 held, send 2, 3 left. Tick 3: no arrivals, send 2, 1 left. Tick 4: 1 + 6 = 7, two dropped, send 2, 3 left. Tick 5: 3 + 1 = 4, send 2, 2 left. Tick 6: 2 + 3 = 5 fits exactly, send 2, 3 left. Total dropped 4, with 3 waiting. Check: 19 arrived = 12 sent + 4 dropped + 3 waiting. Reporting 5 waiting forgets the send in tick 6.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-127","question":"A browser with nothing cached fetches a page made of a base HTML file and 9 small images, all on one server. Resolving the server's name takes two DNS queries of 25 ms each. The round-trip time to the server is 40 ms and transmission times are negligible. The browser uses non-persistent HTTP and, after receiving the base file, opens at most 4 parallel TCP connections at a time. How long does it take to fetch the whole page?","options":["850 ms","370 ms","290 ms","170 ms"],"answer":1,"explanation":"DNS: 2 x 25 = 50 ms. Each non-persistent fetch costs 2 RTT = 80 ms (one RTT for the TCP handshake, one for the request and response). Base file: 80 ms. The 9 images need ceil(9/4) = 3 batches of parallel connections, each 80 ms: 240 ms. Total 50 + 80 + 240 = 370 ms. 850 ms fetches the images one after another (10 x 80 + 50); 290 ms assumes two batches are enough; 170 ms would need a persistent pipelined connection (50 + 80 + 40).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-128","question":"For the host 172.29.115.201/21, what is the directed broadcast address of its subnet and how many usable host addresses does the subnet have?","options":["172.29.115.255, 2046","172.29.119.255, 2048","172.29.119.255, 2046","172.29.127.255, 2046"],"answer":2,"explanation":"/21 leaves 11 host bits, so blocks of 8 in the third octet: 115 falls in 112–119, giving network 172.29.112.0 and broadcast 172.29.119.255. Usable hosts = 2¹¹ − 2 = 2046. 172.29.127.255 would be the /20 answer.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-129","question":"The block 10.0.0.0/8 is cut into /19 subnets numbered 0, 1, 2, … in address order (subnet 0 is 10.0.0.0/19). What is the network address of subnet number 999?","options":["10.124.224.0","10.125.0.0","10.31.56.0","10.31.224.0"],"answer":0,"explanation":"Each /19 holds 2¹³ = 8192 addresses (32 in the third octet), so 8 subnets fit in each value of the second octet. 999 = 124 × 8 + 7, so the second octet is 124 and the third is 7 × 32 = 224, giving 10.124.224.0. 10.125.0.0 is subnet 1000 (an off-by-one).","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-130","question":"A router's forwarding table holds 131.16.0.0/12 → R1, 131.28.0.0/14 → R2, 131.30.0.0/15 → R3, 131.30.128.0/17 → R4 and a default route → R5. Where are packets for 131.31.200.1, 131.29.4.4 and 131.15.0.1 sent, in that order?","options":["R4, R2, R1","R3, R2, R5","R3, R1, R5","R4, R2, R5"],"answer":1,"explanation":"131.31.200.1 is inside 131.30.0.0/15 (covers 131.30–131.31) but not 131.30.128.0/17 (only 131.30.128–255), so R3. 131.29.4.4 matches the /12 and /14; the longer /14 wins → R2. 131.15.x is below 131.16.0.0/12 (131.16–131.31), so only the default matches → R5.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-131","question":"A router must summarise 198.51.96.0/21, 198.51.104.0/22 and 198.51.110.0/23 into the smallest single prefix. Which prefix is it, and how many addresses does it cover that are in none of the three routes?","options":["198.51.96.0/20, 0","198.51.96.0/19, 4608","198.51.104.0/21, 512","198.51.96.0/20, 512"],"answer":3,"explanation":"The routes span third octets 96–103, 104–107 and 110–111, so the smallest aligned block is 96–111 = 198.51.96.0/20 (4096 addresses). It also covers 198.51.108.0/23, which none of the routes includes: 512 extra addresses, which is why such summaries can attract traffic for unassigned space.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-132","question":"192.168.40.0/24 is split with VLSM, largest requirement first, each at the lowest free aligned address, for LANs needing 60, 28 and 12 hosts and one point-to-point link (2 hosts). What is the broadcast address of the 12-host LAN, and the first usable address on the point-to-point link?","options":["192.168.40.111 and 192.168.40.113","192.168.40.111 and 192.168.40.112","192.168.40.103 and 192.168.40.105","192.168.40.127 and 192.168.40.129"],"answer":0,"explanation":"60 hosts → /26 (.0–.63); 28 → /27 (.64–.95); 12 → /28 (.96–.111, since a /29 holds only 6 hosts); the link → /30 (.112–.115). The /30's first usable address is .113, because .112 is its network address.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-133","question":"An organisation owns 150.80.0.0/16 and subnets it so that every subnet supports at least 500 hosts while creating as many subnets as possible. How many subnets result, and how many usable hosts does each have?","options":["64 subnets, 1022 hosts","128 subnets, 512 hosts","128 subnets, 510 hosts","256 subnets, 254 hosts"],"answer":2,"explanation":"500 hosts need 9 host bits (2⁹ − 2 = 510 ≥ 500, while 2⁸ − 2 = 254 is too few). That leaves 16 − 9 = 7 subnet bits, so 2⁷ = 128 subnets of 510 usable hosts each (prefix /23).","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-134","question":"An IPv4 datagram with total length 2400 bytes (20-byte header, DF = 0) first crosses a link with MTU 1000 and then a link with MTU 576; routers fragment as needed and nothing is reassembled on the way. How many fragments reach the destination, and what is the fragment-offset field of the fourth fragment in address order?","options":["5 fragments, offset 190","6 fragments, offset 191","4 fragments, offset 122","5 fragments, offset 191"],"answer":3,"explanation":"MTU 1000 allows 976 data bytes (multiple of 8): 976 + 976 + 428 at offsets 0, 122, 244. On MTU 576 each 976-byte piece splits into 552 + 424 (552 = largest multiple of 8 ≤ 556), while the 428-byte piece fits. Offsets: 0, 69, 122, 191, 244, so the fourth is 191 (= 122 + 552/8).","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-135","question":"Host A sends three TCP segments to B: seq 3200 (400 bytes), seq 3600 (500 bytes) and seq 4100 (300 bytes). The second is lost; B ACKs every segment it receives. After A's retransmission of the lost segment arrives, what acknowledgement number does B send?","options":["4100","4400","4401","3600"],"answer":1,"explanation":"B buffers the out-of-order segment 4100–4399 and keeps sending ACK 3600 (a duplicate). When bytes 3600–4099 arrive, the gap is filled and the cumulative ACK jumps past the buffered data to 4400, the next byte B expects.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-136","question":"A TCP Reno sender begins round 1 with cwnd = 1 MSS and ssthresh = 20 MSS. In slow start cwnd doubles every round but never jumps past ssthresh (it is capped at ssthresh); at or above ssthresh it grows by 1 MSS per round. Triple duplicate ACKs are detected at the end of round 9 (ssthresh = ⌊cwnd/2⌋, cwnd = ssthresh), and a timeout at the end of round 12 (ssthresh = ⌊cwnd/2⌋, cwnd = 1). What is cwnd during round 17?","options":["8 MSS","6 MSS","12 MSS","7 MSS"],"answer":3,"explanation":"cwnd per round: 1, 2, 4, 8, 16, 20, 21, 22, 23, 11, 12, 13, 1, 2, 4, 6, 7. Round 9 has cwnd 23, so ssthresh = 11 and cwnd = 11; it reaches 13 in round 12, the timeout sets ssthresh = 6 and cwnd = 1; then 1, 2, 4, 6 (capped), 7 in round 17.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-137","question":"A TCP segment times out and is retransmitted; an ACK covering it then arrives. Under Karn's algorithm, what does the sender do?","options":["It takes no RTT sample from this ACK and keeps the doubled RTO until a segment sent only once is acknowledged","It samples the RTT from the first transmission and updates SRTT and the RTO","It samples the RTT from the retransmission and halves the backed-off RTO","It resets the RTO to its initial 3-second value and restarts slow start"],"answer":0,"explanation":"The ACK of a retransmitted segment is ambiguous, so it is not used for SRTT. Karn's rule also keeps the exponentially backed-off timeout; otherwise an RTO that is too small would cause endless spurious retransmissions.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-138","question":"A 1 Gbps path has a round-trip time of 80 ms. What is the smallest TCP window-scale shift count that lets a single connection keep the path full?","options":["7","8","9","14"],"answer":1,"explanation":"The bandwidth-delay product is 10⁹ × 0.08 / 8 = 10,000,000 bytes. 65,535 × 2⁷ ≈ 8.39 MB is too small, while 65,535 × 2⁸ ≈ 16.8 MB suffices, so the shift is 8. 14 is the maximum shift allowed, not the minimum needed.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-139","question":"A 1 Mbps link carries 1000-bit frames with a one-way propagation delay of 15 ms (ACKs negligible). What is the minimum number of sequence-number bits for 100% utilisation with Go-Back-N, and with Selective Repeat?","options":["5 bits and 5 bits","4 bits and 5 bits","5 bits and 6 bits","6 bits and 6 bits"],"answer":2,"explanation":"Tt = 1 ms and Tt + 2Tp = 31 ms, so the window must be at least 31 frames. Go-Back-N needs 2ᵏ − 1 ≥ 31 → k = 5; Selective Repeat needs window ≤ 2ᵏ/2, i.e. 2ᵏ ≥ 62 → k = 6.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-140","question":"Stop-and-wait runs on a 4 Mbps link with 2000-bit frames and a one-way propagation delay of 2 ms; ACKs are negligibly short. Each frame is independently corrupted with probability 0.2 (corrupted frames time out and are resent, with the timeout equal to one round trip after the frame ends). What is the useful throughput?","options":["444.4 kbps","284.4 kbps","3200.0 kbps","355.6 kbps"],"answer":3,"explanation":"Each attempt takes Tt + 2Tp = 0.5 + 4 = 4.5 ms and on average 1/(1 − 0.2) = 1.25 attempts are needed, i.e. 5.625 ms per delivered frame: 2000 / 5.625 ms ≈ 355.6 kbps. Ignoring errors gives 444.4 kbps; 3200 kbps forgets propagation delay entirely.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-141","question":"The message 1101011011 is protected by CRC with generator polynomial x⁴ + x³ + 1. What is the transmitted bit string?","options":["11010110110100","11010110111110","11010110110010","11010110110000"],"answer":0,"explanation":"Append four 0s and divide modulo 2 by 11001; the remainder is 0100, which replaces the appended zeros. Using x⁴ + x + 1 (10011) by mistake gives 1110. The receiver divides the whole frame by 11001 and checks for a zero remainder.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-142","question":"How many of the following statements about CRC are correct?\n1. If the generator has (x + 1) as a factor, every error with an odd number of flipped bits is detected.\n2. A generator of degree r with a nonzero constant term detects every burst error of length ≤ r.\n3. A CRC detects every 2-bit error, whatever the generator and frame length.\n4. The CRC remainder can be computed with shift registers and XOR gates.","options":["2","4","3","1"],"answer":2,"explanation":"1, 2 and 4 are standard results. Statement 3 is false: two isolated errors xⁱ + xʲ are missed when the generator divides x^(j−i) + 1, so detecting all double errors needs a generator whose order exceeds the frame length (e.g. a primitive polynomial and short enough frames).","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-143","question":"A memory word holds 57 data bits protected by a SEC-DED code (single-error correcting, double-error detecting) built as a Hamming code plus one overall parity bit. How many check bits are needed in total?","options":["6","7","8","5"],"answer":1,"explanation":"Hamming SEC needs 2ʳ ≥ m + r + 1: r = 6 gives 64 ≥ 57 + 6 + 1 = 64, just enough. One extra overall parity bit adds double-error detection, so 7 check bits in total (a (64, 57) code).","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-144","question":"Data is arranged as a block with an even-parity bit for every row and every column (2-D parity). Which error pattern is NOT detected?","options":["Three flipped bits in the same row","Four flipped bits at the corners of a rectangle (two rows × two columns)","Two flipped bits in the same column","Three flipped bits in three different rows and columns"],"answer":1,"explanation":"With four corner errors every affected row and every affected column has exactly two flips, so all parities still check. Two errors in one column still upset two row parities; any 3-bit error leaves at least one row or column with an odd count, so 2-D parity detects all 1-, 2- and 3-bit errors.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-145","question":"A 100 Mbps CSMA/CD network uses a 64-byte minimum frame. Signals travel at 2 × 10⁸ m/s, and the hubs on the longest path add a total one-way delay of 1.06 µs. What is the maximum cable length between the two farthest stations?","options":["512 m","88 m","300 m","600 m"],"answer":2,"explanation":"The frame time 512 bits / 100 Mbps = 5.12 µs must cover a round trip: 2(d/v + 1.06 µs) ≤ 5.12 µs, so d/v ≤ 1.5 µs and d ≤ 300 m. Without the hub delay it would be 512 m.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-146","question":"For classic Ethernet the efficiency is often approximated as 1/(1 + 5a), where a = propagation delay / frame transmission time. What is it for a 10 Mbps LAN 1 km long (signal speed 2 × 10⁸ m/s) carrying 1000-bit frames?","options":["0.80","0.91","0.95","0.67"],"answer":0,"explanation":"Tp = 1000 m / 2×10⁸ = 5 µs and Tt = 1000 / 10⁷ = 100 µs, so a = 0.05 and efficiency = 1/1.25 = 0.80. 0.91 uses the stop-and-wait form 1/(1 + 2a), which does not model collisions.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-147","question":"Five stations share a slotted-ALOHA channel; each transmits in a given slot independently with probability 0.2. What fraction of slots carry a successful transmission?","options":["0.0819","0.3679","0.3277","0.4096"],"answer":3,"explanation":"A slot succeeds when exactly one of the five transmits: 5 × 0.2 × 0.8⁴ = 0.4096. 0.0819 is the probability for one particular station, and 1/e ≈ 0.3679 is the large-N limit.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-148","question":"Router C runs distance-vector routing. Its link costs are C–B 6, C–D 3, C–E 5. It receives these vectors (distances to A, B, C, D, E, F): from B (5, 0, 8, 12, 6, 2), from D (16, 12, 6, 0, 9, 10), from E (7, 6, 3, 9, 0, 4). What are C's new routes to A and to F?","options":["A: 12 via E; F: 9 via E","A: 11 via B; F: 9 via E","A: 19 via D; F: 13 via D","A: 11 via B; F: 8 via B"],"answer":3,"explanation":"To A: via B 6 + 5 = 11, via D 3 + 16 = 19, via E 5 + 7 = 12, so 11 via B. To F: via B 6 + 2 = 8, via D 3 + 10 = 13, via E 5 + 4 = 9, so 8 via B. C ignores its own old table and the cheapest direct link (D) does not matter.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-149","question":"A BGP router (no vendor-specific weight, all routes learned over eBGP, all valid) has three routes to 203.0.113.0/24:\nX: LOCAL_PREF 200, AS_PATH length 4, MED 10\nY: LOCAL_PREF 100, AS_PATH length 2, MED 0\nZ: LOCAL_PREF 200, AS_PATH length 3, MED 50\nWhich route is selected?","options":["Y","Z","X","X or Z, chosen by lowest router ID"],"answer":1,"explanation":"Highest LOCAL_PREF is compared first, which eliminates Y despite its shortest path. Between X and Z the shorter AS_PATH wins, so Z; MED is compared only after AS path length (and normally only between routes from the same neighbouring AS).","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-150","question":"A laptop asks its local DNS server (recursive service) for www.campus.example.com. The local server has nothing cached except the address of the .com TLD servers, and it resolves names iteratively. The example.com server is authoritative for campus.example.com too. How many DNS messages (queries and replies) are exchanged in total?","options":["6","8","4","10"],"answer":0,"explanation":"Laptop ↔ local (2), local ↔ .com TLD (2, which refers it to the example.com server), local ↔ example.com authoritative (2). The cached TLD address removes the root round trip that would make it 8.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-151","question":"A base HTML page references 8 small images on the same server. The browser uses NON-persistent HTTP with up to 4 parallel TCP connections. Ignoring transmission times and DNS, how many RTTs does it take from the request for the page until all images have arrived?","options":["10 RTTs","4 RTTs","6 RTTs","18 RTTs"],"answer":2,"explanation":"The base file costs 2 RTTs (TCP handshake + request/response). The 8 images go in 2 waves of 4 parallel connections, each wave costing 2 RTTs, so 2 + 4 = 6. Serial non-persistent fetching would take 2 + 16 = 18 RTTs, and one persistent connection without pipelining 2 + 8 = 10.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-152","question":"A 20 kHz channel has a signal-to-noise ratio of 63 (linear). How many signal levels are needed so that a Nyquist-rate signal reaches the Shannon capacity?","options":["64","8","4","6"],"answer":1,"explanation":"Shannon: C = 20k × log₂(64) = 120 kbps. Nyquist: 2B log₂L = 40k × log₂L = 120k gives log₂L = 3, so L = 8. Choosing 64 levels confuses the SNR + 1 term with the level count.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-153","question":"What baud rates do 10 Mbps Ethernet (Manchester coding) and 100BASE-TX's 4B/5B stage (100 Mbps of data) require?","options":["10 Mbaud and 100 Mbaud","20 Mbaud and 80 Mbaud","20 Mbaud and 125 Mbaud","5 Mbaud and 125 Mbaud"],"answer":2,"explanation":"Manchester puts a transition in the middle of every bit, i.e. two signal elements per bit: 2 × 10 = 20 Mbaud. 4B/5B sends 5 code bits for every 4 data bits: 100 × 5/4 = 125 Mbaud (then MLT-3 lowers the fundamental frequency further).","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-154","question":"Router R has three interfaces. Interface 1 connects to switch S1 with 6 hosts. Interface 2 connects to hub H1 with 4 hosts. Interface 3 connects to switch S2, which has 2 hosts plus hub H2 (with 3 hosts) attached. No VLANs are used. How many broadcast domains and collision domains are there?","options":["3 broadcast, 11 collision","1 broadcast, 12 collision","3 broadcast, 15 collision","3 broadcast, 12 collision"],"answer":3,"explanation":"Each router interface is one broadcast domain: 3. Collision domains: every switch port is its own (S1: 6 hosts + uplink = 7; S2: 2 hosts + uplink + the port to H2 = 4) and each hub with everything on it is one (H1 with R's port = 1; H2 is already counted as S2's port). 7 + 1 + 4 = 12.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-155","question":"A host builds its IPv6 interface identifier from its MAC address 00:1A:2B:3C:4D:5E using modified EUI-64. What is the interface identifier?","options":["021a:2bff:fe3c:4d5e","001a:2bff:fe3c:4d5e","021a:2bfe:ff3c:4d5e","021a:2b3c:4d5e:fffe"],"answer":0,"explanation":"Split the MAC in half, insert FF:FE in the middle (00:1A:2B:FF:FE:3C:4D:5E) and flip the universal/local bit (bit 7 of the first byte): 0x00 → 0x02. Forgetting the flip gives 001a:2bff:fe3c:4d5e.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-156","question":"Assertion (A): With the same window size, Selective Repeat usually needs a larger sequence-number space than Go-Back-N.\nReason (R): A Selective Repeat receiver accepts and buffers out-of-order frames, so after lost ACKs it must not mistake a retransmitted old frame for a new frame in its window.","options":["Both A and R are true, but R is not the correct explanation of A","A is true but R is false","Both A and R are true, and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"GBN's receiver window is 1, so W ≤ 2ᵏ − 1 suffices; SR's receiver window equals W, and the sender and receiver windows must not overlap after all ACKs are lost, which forces W ≤ 2ᵏ⁻¹. That overlap danger is exactly what R describes.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-157","question":"A client sends SYN with seq = 7000. The server replies SYN-ACK with seq = 22000. The client then sends the final ACK carrying 100 bytes of data, and the server answers with 50 bytes of data. What are the seq and ack numbers on that server data segment?","options":["seq 22001, ack 7101","seq 22000, ack 7100","seq 22001, ack 7100","seq 22050, ack 7101"],"answer":0,"explanation":"SYN consumes one sequence number on each side: client data starts at 7001 and server data at 22001. The client's 100 bytes cover 7001–7100, so the server acknowledges 7101, and its own first data byte is 22001.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-158","question":"How many /27 subnets fit inside the block 172.16.64.0/18, and how many usable hosts does each have?","options":["256 subnets, 30 hosts","512 subnets, 32 hosts","64 subnets, 30 hosts","512 subnets, 30 hosts"],"answer":3,"explanation":"Going from /18 to /27 borrows 9 bits, giving 2⁹ = 512 subnets; each /27 has 5 host bits, so 2⁵ − 2 = 30 usable hosts. 256 would come from counting from /19.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-159","question":"A network admin knows that 10.1.37.6 and 10.1.42.200 are in the same subnet while 10.1.48.1 is in a different one. Which subnet mask is consistent with this?","options":["255.255.248.0","255.255.240.0","255.255.224.0","255.255.255.0"],"answer":1,"explanation":"In the third octet, 37 = 0010 0101, 42 = 0010 1010 and 48 = 0011 0000. 37 and 42 agree only in their first 4 bits, so the mask can cover at most 4 bits of the third octet (/20); 48 differs from them already in that 4th bit, so /20 is also needed to separate it. /21 splits 37 from 42, /19 puts 48 in the same subnet. Only 255.255.240.0 (/20) works.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-160","question":"An IPv4 packet has HLEN = 8 and total length = 1000. How many bytes of options does the header carry, and how many bytes of payload does the packet carry?","options":["12 bytes of options, 968 bytes of payload","0 bytes of options, 992 bytes of payload","3 bytes of options, 992 bytes of payload","12 bytes of options, 980 bytes of payload"],"answer":0,"explanation":"HLEN counts 4-byte words: 8 × 4 = 32-byte header, of which 20 are the fixed part, so 12 bytes of options. Total length includes the header: 1000 − 32 = 968 bytes of payload.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-161","question":"A long-lived TCP Reno flow is in steady state congestion avoidance: its window grows by 1 MSS per RTT up to W = 40 segments, then a single loss halves it, and the cycle repeats. With MSS = 1500 bytes and RTT = 100 ms, what is its average throughput?","options":["4.8 Mbps","2.4 Mbps","3.6 Mbps","0.45 Mbps"],"answer":2,"explanation":"The window saw-tooths between W/2 and W, so its average is 0.75W = 30 segments per RTT: 30 × 1500 × 8 / 0.1 s = 3.6 Mbps. 4.8 Mbps assumes the window stays at its peak; 0.45 forgets to convert bytes to bits.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-162","question":"A transport protocol numbers BYTES (like TCP). On a 10 Gbps link with a maximum segment lifetime of 120 s, how many sequence-number bits are needed so that no number is reused while an old segment with it may still exist?","options":["32","37","41","38"],"answer":3,"explanation":"In 120 s the link sends 10¹⁰/8 × 120 = 1.5 × 10¹¹ bytes; log₂(1.5 × 10¹¹) ≈ 37.1, so 38 bits. TCP's 32 bits wrap in about 3.4 s at 10 Gbps, which is why PAWS timestamps exist. Adding 3 extra bits would be counting bits instead of bytes.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-163","question":"In a TCP connection the client calls close() first and the server closes later. Which sequence of states does the SERVER go through from ESTABLISHED?","options":["CLOSE_WAIT → LAST_ACK → CLOSED","FIN_WAIT_1 → FIN_WAIT_2 → TIME_WAIT → CLOSED","CLOSE_WAIT → TIME_WAIT → CLOSED","LAST_ACK → CLOSE_WAIT → CLOSED"],"answer":0,"explanation":"The passive closer receives FIN and enters CLOSE_WAIT; when its application closes it sends its own FIN and waits in LAST_ACK for the ACK, then goes to CLOSED. FIN_WAIT_1/2 and TIME_WAIT belong to the active closer (the client here).","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-164","question":"A remote-shell client writes one keystroke (1 byte) at a time to a TCP socket with Nagle's algorithm enabled; the RTT is 50 ms and the user types 40 keys per second. What does Nagle's algorithm do?","options":["Sends every keystroke immediately in its own segment, because the data is urgent","Sends the first byte at once, then coalesces later keystrokes until the outstanding data is ACKed","Holds all bytes until a full MSS has accumulated","Holds all bytes until the 200 ms delayed-ACK timer fires"],"answer":1,"explanation":"Nagle allows only one unacknowledged small segment in flight; bytes typed during the 50 ms wait are coalesced, so about 2 keys go in each segment here. It never waits for a full MSS when no data is outstanding, which is why it adds little delay for interactive traffic unless it meets delayed ACKs.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-165","question":"Which pair correctly matches the fix with the side that causes silly window syndrome?\n(i) receiving application reads data one byte at a time\n(ii) sending application writes data one byte at a time","options":["(i) Nagle's algorithm on the sender; (ii) Clark's solution on the receiver","(i) Karn's algorithm; (ii) the persist timer","(i) Clark's rule on the receiver; (ii) Nagle's algorithm on the sender","(i) delayed ACKs only; (ii) the persist timer"],"answer":2,"explanation":"A slowly reading receiver produces tiny window updates; Clark's rule makes it advertise zero until it can offer an MSS or half its buffer. A slowly writing sender produces tiny segments; Nagle's algorithm coalesces them. Karn's algorithm is about RTT samples and the persist timer about zero-window probes.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-166","question":"How many of the following statements about UDP are correct?\n1. The UDP checksum covers a pseudo-header containing the source and destination IP addresses.\n2. In IPv4 the UDP checksum may be set to 0 (not used), but in IPv6 it is mandatory.\n3. The UDP length field counts the 8-byte header plus the data.\n4. UDP preserves message boundaries: one sendto() produces one datagram.\n5. UDP retransmits a datagram if the checksum fails at the receiver.","options":["3","5","4","2"],"answer":2,"explanation":"1–4 are true. Statement 5 is false: a UDP receiver silently discards a datagram with a bad checksum, and UDP itself never retransmits; any recovery is left to the application.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-167","question":"A sender must deliver frames 1–8 with a window of 4. Only the first transmission of frame 3 is lost; nothing else is lost, and the sender always fills its window before the timeout for frame 3 fires. How many frame transmissions are needed in total with Go-Back-N, and with Selective Repeat?","options":["10 with Go-Back-N, 9 with Selective Repeat","12 with Go-Back-N, 12 with Selective Repeat","9 with Go-Back-N, 9 with Selective Repeat","12 with Go-Back-N, 9 with Selective Repeat"],"answer":3,"explanation":"GBN: frames 1–6 go out (the window slides to 3–6 after 1 and 2 are ACKed), the receiver discards 4–6, so on timeout 3, 4, 5, 6 are resent, then 7 and 8: 6 + 4 + 2 = 12. SR resends only frame 3: 8 + 1 = 9.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-168","question":"A 2 Mbps link uses Selective Repeat with a window of 10 frames. The propagation delay is 8 times the frame transmission time and ACKs are negligible. What throughput is achieved?","options":["1.176 Mbps","2.000 Mbps","2.222 Mbps","0.118 Mbps"],"answer":0,"explanation":"A frame's ACK returns after Tt + 2Tp = 17 Tt, while the window lets 10 frames out, so efficiency = 10/17 ≈ 0.588 and throughput ≈ 1.176 Mbps. Using 1 + a instead of 1 + 2a forgets the ACK's return trip; 0.118 Mbps is the stop-and-wait value.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-169","question":"A block code has minimum Hamming distance 5. Which statement is correct?","options":["It can correct all 3-bit errors","It can correct all 1-bit errors and at the same time detect all 2- and 3-bit errors","It can detect all 5-bit errors","It can correct all 2-bit errors and at the same time detect all 3-bit errors"],"answer":1,"explanation":"With distance d you can correct c and also detect e > c errors if c + e + 1 ≤ d: c = 1, e = 3 gives 5 ≤ 5. Pure correction reaches ⌊(5 − 1)/2⌋ = 2, pure detection reaches 4, but c = 2 with e = 3 needs d ≥ 6.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-170","question":"Compute the 16-bit Internet checksum (ones' complement of the ones' complement sum) of the words 0xABCD, 0xF00F, 0x1234 and 0x8E91.","options":["0xC35C","0xC35E","0x3CA3","0xC35D"],"answer":0,"explanation":"Add with end-around carry: the ones' complement sum is 0x3CA3; inverting gives 0xC35C. Dropping the carries instead of folding them back gives 0xC35E, and 0x3CA3 forgets the final complement.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-171","question":"A PPP-style link uses byte stuffing with a FLAG byte at each end of the frame and an ESC byte placed before any FLAG or ESC that occurs in the data. The payload is: A, FLAG, B, ESC, ESC, C. How many bytes are sent for the whole frame, including both flags?","options":["9","10","11","13"],"answer":2,"explanation":"The data FLAG gets one ESC, and each of the two ESC bytes gets one ESC: 6 + 3 = 9 payload bytes after stuffing, plus 2 frame flags = 11. Escaping only the FLAG would give 9 bytes in total (7 + 2).","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-172","question":"Link-state routing runs Dijkstra from S on an undirected network with link costs S–A 3, S–B 1, B–A 1, A–C 2, B–C 5, C–D 1, B–D 7, A–D 6. In what order are nodes made permanent, and what is the cost to D?","options":["S B A D C; cost 6","S B A C D; cost 6","S A B C D; cost 5","S B A C D; cost 5"],"answer":3,"explanation":"S (0), B (1), then A (2 via B, beating 3 direct), C (4 via A, beating 6 via B), D (5 via C, beating 7 via A and 8 via B). The path is S–B–A–C–D with cost 5.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-173","question":"Which statement about split horizon with poisoned reverse in distance-vector routing is correct?","options":["It prevents every count-to-infinity problem","It stops two-router loops but not count-to-infinity in loops of three or more routers","It replaces periodic updates with triggered updates","It makes the protocol converge in one update after any link failure"],"answer":1,"explanation":"Advertising ∞ back to the next hop stops two routers from bouncing a dead route between themselves. In a triangle, A can learn the stale route from C, which learned it from B, so the count can still climb; RIP limits the damage with infinity = 16 and hold-down timers.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-174","question":"A host that has just booted broadcasts an ARP request asking for its OWN IP address. Why?","options":["To learn its own MAC address from the switch","To obtain an IP address, since ARP replaces DHCP on boot","To detect whether another host already uses that IP and to refresh neighbours' ARP caches with its MAC","To find the MAC address of its default gateway"],"answer":2,"explanation":"This is gratuitous ARP: a reply means an address conflict, and the broadcast also updates stale cache entries (used after NIC changes and in failover). Hosts already know their own MAC; addresses come from DHCP or static configuration.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-175","question":"A DHCP server sits on 10.0.0.0/24 and serves clients on 10.5.7.0/24 through a relay agent on that client router interface (10.5.7.1). How does the server know which pool to allocate from?","options":["The client puts its subnet number in the ciaddr field of DHCPDISCOVER","The relay writes its interface address 10.5.7.1 into giaddr; the server picks the matching pool","The server looks at the source MAC address of the request","The server allocates from its own subnet 10.0.0.0/24 and the router translates it"],"answer":1,"explanation":"The client has no address yet (ciaddr = 0.0.0.0) and its broadcast cannot cross the router. The relay unicasts the message to the server with giaddr = the receiving interface's address; the server uses giaddr to choose the scope and sends its reply back to the relay.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-176","question":"Classic UNIX traceroute sends UDP probes with increasing TTL. How does it know that a probe has reached the destination host itself?","options":["The destination answers with ICMP Time Exceeded with TTL 0","The destination sends a UDP echo reply","The last router sends ICMP Echo Reply on behalf of the host","The destination answers with ICMP Port Unreachable, because the probe targets an unlikely high UDP port"],"answer":3,"explanation":"Intermediate routers drop the probe when TTL reaches 0 and send ICMP Time Exceeded, revealing each hop. The destination does not decrement TTL to 0 for itself; it finds no process on the port and returns Port Unreachable, which ends the trace.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-177","question":"A browser re-requests a cached image with the header If-Modified-Since. The image has not changed on the server. What does the server send?","options":["304 Not Modified with no body","200 OK with the full image","302 Found pointing to the cached copy","204 No Content with the new Last-Modified date"],"answer":0,"explanation":"A conditional GET lets the server answer 304 with headers only, so the browser reuses its cached copy and saves bandwidth. 200 would resend the body, 302 is a temporary redirect, and 204 means the request succeeded with no content to show.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-178","question":"How many of the following statements are correct?\n1. HTTP/2 multiplexes many requests as streams over one TCP connection.\n2. HTTP/2 removes all head-of-line blocking, including the blocking caused by a lost TCP segment.\n3. HTTP/2 compresses headers (HPACK).\n4. HTTP/3 runs over QUIC on UDP so that a lost packet stalls only the stream it belongs to.","options":["4","3","2","1"],"answer":1,"explanation":"1, 3 and 4 are true. HTTP/2 removes application-level head-of-line blocking, but all streams share one TCP byte stream, so one lost segment still stalls every stream until it is retransmitted; that is what QUIC fixes.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-179","question":"Alice writes an email in a web browser using a webmail service; it is delivered to Bob's mail server and Bob reads it in a desktop client that keeps folders in sync on the server. Which protocols are used on the three hops: Alice's browser → her mail server, her mail server → Bob's mail server, Bob's server → Bob's client?","options":["SMTP, SMTP, POP3","HTTP(S), SMTP, POP3","HTTP(S), SMTP, IMAP","SMTP, HTTP, IMAP"],"answer":2,"explanation":"A webmail user talks to the service over HTTP(S); servers relay mail to each other with SMTP; a client that keeps folders synchronised on the server uses IMAP. POP3 typically downloads and does not sync folders.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-180","question":"How many of the following statements about FTP are correct?\n1. FTP sends control information out-of-band on a separate TCP connection (server port 21).\n2. In active mode the server opens the data connection from its port 20 to a port the client announced.\n3. The control connection is closed after each file transfer.\n4. In passive mode the client opens the data connection to a port chosen by the server, which suits clients behind NAT.","options":["3","4","2","1"],"answer":0,"explanation":"1, 2 and 4 are true. Statement 3 is reversed: the control connection is persistent for the whole session, while a new data connection is opened for each file or directory listing.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-181","question":"A router holds 50 packets on average (queued plus in service), and packets arrive at an average of 10,000 per second. What is the average time a packet spends in the router?","options":["0.5 ms","50 ms","200 ms","5 ms"],"answer":3,"explanation":"Little's law: N = λT, so T = N/λ = 50 / 10,000 s = 5 ms. It holds for any stable queue regardless of the arrival and service distributions.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-182","question":"Packets of 1500 bytes arrive at a router output link of 10 Mbps as a Poisson stream of 800 packets/s; transmission times are exponential with that mean (an M/M/1 queue). What is the average time a packet spends at the link (waiting plus transmitting)?","options":["1.2 ms","30 ms","0.96 ms","28.8 ms"],"answer":1,"explanation":"μ = 10⁷ / 12,000 ≈ 833.3 packets/s, so ρ = 0.96 and T = 1/(μ − λ) = 1/33.3 s = 30 ms. The bare transmission time is only 1.2 ms; near ρ = 1 the queueing delay dominates.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-183","question":"A 600 kbps link is shared by 20 users who each need 100 kbps while active and are active independently 20% of the time. With packet switching, what is the probability that more than 6 users are active at once (so the link is overloaded)?","options":["0.913","0.055","0.087","0.000"],"answer":2,"explanation":"P(X > 6) for X ~ Binomial(20, 0.2) is 1 − Σ_(k=0..6) C(20,k)0.2ᵏ0.8²⁰⁻ᵏ ≈ 0.087. Circuit switching could admit only 6 users; packet switching serves 20 with overload this rarely. 0.055 is P(X = 7) alone.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-184","question":"An IEEE 802.1Q tag adds how many bytes to an Ethernet frame, and how many VLAN IDs are usable for ordinary VLANs?","options":["4 bytes; 4096 VLAN IDs","2 bytes; 4094 VLAN IDs","4 bytes; 1024 VLAN IDs","4 bytes; 4094 VLAN IDs"],"answer":3,"explanation":"The tag is 4 bytes (TPID 0x8100 plus a 16-bit TCI with 3 priority bits, 1 DEI bit and a 12-bit VLAN ID). 12 bits give 4096 values, but 0 and 4095 are reserved, leaving 4094.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-185","question":"Four switches run classic Spanning Tree. Their bridge IDs (priority, MAC) are S1 (32768, 00:00:0C:11:11:11), S2 (32768, 00:00:0C:00:00:05), S3 (28672, 00:00:0C:99:99:99), S4 (32768, 00:00:0A:FF:FF:FF). Which becomes the root bridge?","options":["S3","S4","S2","S1"],"answer":0,"explanation":"The lowest bridge ID wins, and priority is compared before the MAC address. S3's priority 28672 is lower than 32768, so it wins despite having the highest MAC; among the others S4's MAC would be the lowest.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-186","question":"With a /20 mask, which pair of addresses lies in the SAME subnet?","options":["172.16.31.200 and 172.16.32.1","172.16.15.1 and 172.16.16.1","172.16.47.255 and 172.16.40.0","172.16.63.1 and 172.16.64.1"],"answer":2,"explanation":"/20 makes blocks of 16 in the third octet: 0–15, 16–31, 32–47, 48–63, 64–79. 40 and 47 both fall in 32–47; 31|32, 15|16 and 63|64 each straddle a boundary even though the addresses are numerically close.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-187","question":"192.168.64.0/18 is divided into /22 subnets numbered from 1 in address order. What are the first and last usable host addresses of subnet 6?","options":["192.168.88.1 – 192.168.91.254","192.168.84.1 – 192.168.87.254","192.168.84.0 – 192.168.87.255","192.168.84.1 – 192.168.84.254"],"answer":1,"explanation":"Each /22 spans 4 values of the third octet; subnet 6 starts 5 × 4 = 20 above 64, at 192.168.84.0, and ends at 192.168.87.255. The usable range excludes those two. The option starting at 192.168.88.1 counts from 0.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-188","question":"A 6000-byte message crosses 3 store-and-forward links (2 routers), each 1 Mbps with 1 ms propagation delay. It is cut into packets with 1000-byte payloads, and each packet carries a 40-byte header. Ignoring processing and queueing, how long after the first bit is sent does the last bit arrive?","options":["69.56 ms","152.76 ms","67.00 ms","77.88 ms"],"answer":0,"explanation":"Each packet takes 1040 × 8 / 10⁶ = 8.32 ms per link. With pipelining, the last of 6 packets leaves the source after 6 × 8.32 ms and then needs 2 more link transmissions: (6 + 3 − 1) × 8.32 + 3 × 1 = 69.56 ms. Sending the whole message hop by hop without pipelining would take 152.76 ms.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-189","question":"For the same 6000-byte message over 3 store-and-forward links of 1 Mbps (1 ms propagation each) with a 40-byte header on every packet, which payload size gives the smallest end-to-end delay?","options":["200 bytes","500 bytes","250 bytes","1000 bytes"],"answer":2,"explanation":"Delay = (k + 2)·(p + 40)·8/R + 3 ms with k = 6000/p packets. Totals: 200 B → 64.44 ms, 250 B → 63.32 ms, 500 B → 63.48 ms, 1000 B → 69.56 ms. Smaller packets pipeline better, but below about 250 bytes the 40-byte headers start to cost more than pipelining saves.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-190","question":"A TCP sender must send a 50-segment file. It starts with cwnd = 1, ssthresh = 8 (slow start doubles cwnd each RTT, capped at ssthresh; then +1 per RTT), and the receiver's advertised window is fixed at 12 segments. No losses occur. In how many RTT rounds is the file sent (a round sends min(cwnd, rwnd) segments)?","options":["7","8","9","6"],"answer":1,"explanation":"Segments per round: 1, 2, 4, 8, 9, 10, 11, 12 (rwnd = 12 would cap later rounds but never binds before the file is done). Running totals reach 45 after 7 rounds and 57 in round 8, so the last 5 segments go in round 8.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-191","question":"A TCP sender uses RFC 6298 estimation (α = 1/8, β = 1/4): first RTTVAR ← (1−β)RTTVAR + β|SRTT − R|, then SRTT ← (1−α)SRTT + αR, and RTO = SRTT + 4·RTTVAR. Starting from SRTT = 80 ms and RTTVAR = 8 ms, samples of 120, 60 and 100 ms arrive in that order. What is the RTO after the third sample?","options":["116.14 ms","102.36 ms","167.02 ms","157.02 ms"],"answer":3,"explanation":"After the three updates SRTT ≈ 84.14 ms and RTTVAR ≈ 18.22 ms, so RTO = 84.14 + 4 × 18.22 ≈ 157.02 ms. Updating RTTVAR with the NEW SRTT, or forgetting the factor 4, gives different values.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-192","question":"A client's SYN carries ISN = 4,294,967,000. After the handshake it sends a 500-byte segment and then an 800-byte segment. What is the sequence number of the 800-byte segment, and what acknowledgement number does the server send after receiving both?","options":["204 and 1004","4294967501 and 4294968301","205 and 1004","205 and 1005"],"answer":3,"explanation":"Data starts at ISN + 1 because the SYN consumes one number. The second segment starts at ISN + 501 = 4,294,967,501, which wraps modulo 2³² to 205; the ACK is ISN + 1301 mod 2³² = 1005.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-193","question":"A Selective Repeat receiver uses 3-bit sequence numbers and a window of 4; it currently expects frames 6, 7, 0, 1 (6 is the next in-order frame). Frames arrive in the order 7, 0, 3, 6, each error-free. After these arrivals, which frames have been delivered to the network layer, and what is the receiver window?","options":["6, 7, 0 delivered; window 1, 2, 3, 4","6, 7, 0, 3 delivered; window 4, 5, 6, 7","Only 6 delivered; window 7, 0, 1, 2","6, 7, 0 delivered; window 1, 2, 3 with 3 already buffered"],"answer":0,"explanation":"7 and 0 are inside the window and are buffered; 3 is outside (only 6, 7, 0, 1 are acceptable) and is discarded. When 6 arrives it is delivered with the buffered 7 and 0, and the window slides to 1, 2, 3, 4. Frame 3 must be sent again.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-194","question":"A (15, 11) Hamming code uses even parity with check bits at positions 1, 2, 4 and 8 (positions numbered 1–15 from the left). The word 111101100011001 is received. Assuming at most one bit is wrong, which position is in error?","options":["Position 5","Position 13","Position 11","No error"],"answer":1,"explanation":"Recompute each check over the positions whose index has that bit set: the failing checks are the ones for 1, 4 and 8, and 1 + 4 + 8 = 13. Reading the syndrome bits in reverse (1011 = 11) or missing the check for 8 (giving 5) are the usual slips.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-195","question":"A CRC uses the generator x³ + 1 (1001). Which of these error patterns (bits written from the highest power down) would go UNDETECTED?","options":["101000","110000","100100","100010"],"answer":2,"explanation":"An error E(x) is missed exactly when the generator divides it. 100100 is x⁵ + x² = x²(x³ + 1), a multiple of the generator. The others leave nonzero remainders; x³ + 1 is a poor generator because any two errors exactly 3 positions apart slip through.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-196","question":"After its 4th consecutive collision on a frame, a 10 Mbps Ethernet station picks K uniformly from {0, …, 2⁴ − 1} and waits K slot times (51.2 µs each). What is its expected backoff before retrying?","options":["409.6 µs","384 µs","768 µs","179.2 µs"],"answer":1,"explanation":"K is uniform on 0..15, so E[K] = 7.5 and the expected wait is 7.5 × 51.2 = 384 µs. Using 2⁴ instead of 2⁴ − 1 as the top value gives 409.6 µs; 15 slots is the maximum, not the mean.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-197","question":"An ISP holds 200.30.0.0/16 and allocates, in address order and without gaps: 32 customers with 512 addresses each, then 64 customers with 128 addresses each, then 256 customers with 32 addresses each. What is the last address given to the final customer, and how many addresses remain unallocated?","options":["200.30.127.255, 32768","200.30.159.255, 24576","200.30.127.255, 24576","200.30.95.255, 40960"],"answer":0,"explanation":"Group 1 uses 32 × 512 = 16,384 addresses (third octet 0–63), group 2 uses 8192 (64–95), group 3 uses 8192 (96–127). The last address is 200.30.127.255 and 65,536 − 32,768 = 32768 remain.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-198","question":"Which group of four consecutive /24 networks can be advertised as exactly one /22 with no extra address space?","options":["200.16.37.0/24 – 200.16.40.0/24","200.16.42.0/24 – 200.16.45.0/24","200.16.36.0/24 – 200.16.39.0/24","200.16.50.0/24 – 200.16.53.0/24"],"answer":2,"explanation":"A /22 covers four /24s whose third octet starts at a multiple of 4. 36 = 4 × 9, so 36–39 aggregate to 200.16.36.0/22. 37–40, 42–45 and 50–53 each straddle a /22 boundary (52 would be needed for the last).","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-199","question":"A router has 10.0.0.0/8 → A, 10.128.0.0/9 → B and 10.192.0.0/10 → C, using longest-prefix match. How many destination addresses are forwarded to B?","options":["8,388,608","2,097,152","12,582,912","4,194,304"],"answer":3,"explanation":"10.128.0.0/9 holds 2²³ addresses, but its upper half 10.192.0.0/10 (2²² addresses) is captured by the longer prefix to C. So B gets 2²³ − 2²² = 4,194,304; A gets the lower half of the /8, 8,388,608.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-200","question":"A browser fetches a 100 KB base page and then 3 embedded objects of 200 KB each from one server over a single persistent HTTP connection WITHOUT pipelining. The bottleneck is 10 Mbps, RTT = 40 ms, 1 KB = 1000 bytes; ignore DNS, headers and TCP slow start. How long from the start of the TCP handshake until the last object is received?","options":["640 ms","760 ms","880 ms","720 ms"],"answer":1,"explanation":"Handshake 40 ms; base page 40 + 80 ms; each object 40 + 160 ms. Total = 40 + 120 + 3 × 200 = 760 ms. Pipelining all three requests would save two RTTs; non-persistent HTTP would add a handshake (40 ms) per object.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-201","question":"A resolver caches an A record whose TTL is 300 s. Clients look the name up at t = 0, 100, 250, 420, 650 and 700 s, with nothing cached at t = 0. How many times must the resolver fetch the record from the authoritative server?","options":["3","6","1","2"],"answer":3,"explanation":"t = 0: fetch, valid until 300; 100 and 250 are hits. t = 420: expired, fetch again, valid until 720, so 650 and 700 are hits. Two fetches in all.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-202","question":"A satellite path offers 50 Mbps with an RTT of 540 ms. A TCP connection without window scaling has a 65,535-byte window. Roughly what fraction of the link can it use?","options":["3.88%","0.24%","1.94%","100%"],"answer":2,"explanation":"At most one window per RTT: 65,535 × 8 / 0.54 s ≈ 971 kbps, i.e. 1.94% of 50 Mbps. Using the one-way delay doubles it; forgetting bits per byte shrinks it 8×. Window scaling fixes this.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-203","question":"An HDLC receiver removes the 0 that the sender stuffed after every five consecutive 1s. What data does it recover from the bit string 0111110111110011111010 (flags already removed)?","options":["0111111111101111110","011111111110011111010","01111111111011111100","0111111111110111110"],"answer":0,"explanation":"Scan for 11111 followed by 0 and drop that 0: there are three such places, so 22 bits shrink to 19: 0111111111101111110. Removing only the first stuffed 0 leaves the others in the data.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-204","question":"A receiver has these fragments of one IPv4 datagram (all with 20-byte headers): offset 0, total length 1420, MF = 1; offset 175, total length 1420, MF = 1; offset 525, total length 620, MF = 0. How many data bytes are still missing, and what was the original datagram's total length?","options":["1400 bytes missing; total length 4800","1200 bytes missing; total length 4820","No bytes missing; total length 3460","1400 bytes missing; total length 4820"],"answer":3,"explanation":"The fragments carry bytes 0–1399, 1400–2799 and 4200–4799 (offset × 8). Bytes 2800–4199 (1400 bytes) are missing. The last fragment ends at byte 4799, so the payload is 4800 bytes and the original total length 4800 + 20 = 4820.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-205","question":"A TCP receiver has a 64 KB buffer with LastByteRcvd − LastByteRead = 20 KB. The sender has LastByteSent − LastByteAcked = 30 KB, and its congestion window is 60 KB. How much more new data may the sender transmit right now?","options":["44 KB","14 KB","30 KB","34 KB"],"answer":1,"explanation":"rwnd = 64 − 20 = 44 KB; the usable window is min(cwnd, rwnd) − in-flight = min(60, 44) − 30 = 14 KB. 44 KB ignores what is already in flight; 30 KB uses cwnd instead of rwnd.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-206","question":"After a timeout a TCP sender restarts with cwnd = 1 MSS and ssthresh = 32 MSS (slow start doubles cwnd per RTT, capped at ssthresh; afterwards +1 MSS per RTT). Counting the restart round as RTT 1, in which RTT is cwnd first equal to 40 MSS?","options":["RTT 14","RTT 13","RTT 15","RTT 7"],"answer":0,"explanation":"cwnd: 1, 2, 4, 8, 16, 32 (RTT 6), then 33, 34, …, reaching 40 eight RTTs later, in RTT 14. Assuming slow start continues past ssthresh would give 64 in RTT 7.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-207","question":"Host A pings host B through one store-and-forward router: A–router is 10 Mbps, router–B is 100 Mbps, each with 5 ms propagation delay. The echo request and the echo reply are each 1000 bytes. Ignoring processing and queueing, what RTT does ping report?","options":["10.88 ms","23.20 ms","21.76 ms","20.00 ms"],"answer":2,"explanation":"One way: 0.8 ms (10 Mbps) + 0.08 ms (100 Mbps) + 10 ms propagation = 10.88 ms, because the router must receive the whole packet before forwarding it. The reply has the same total, so RTT = 21.76 ms. Treating both links as 10 Mbps gives 23.20 ms.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-208","question":"Host X on LAN1 sends an IP packet to host Y on LAN3. The path is X → router R1 → LAN2 → router R2 → Y. All ARP caches are empty, and nobody has talked before. How many ARP request broadcasts are sent before the packet reaches Y?","options":["1","3","2","4"],"answer":1,"explanation":"ARP resolves only next hops on the same link: X asks for R1's MAC on LAN1, R1 asks for R2's MAC on LAN2, and R2 asks for Y's MAC on LAN3. X never learns Y's MAC.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-209","question":"Stop-and-wait runs over a geostationary satellite hop with one-way propagation 270 ms at 1 Mbps (ACKs negligible). What is the smallest frame size that achieves at least 50% link utilisation?","options":["270 kbits","1080 kbits","540 kbits","67.5 kbits"],"answer":2,"explanation":"Utilisation = Tt / (Tt + 2Tp) ≥ 0.5 means Tt ≥ 2Tp = 540 ms, i.e. a frame of 540 kbits at 1 Mbps. Using Tp instead of 2Tp gives 270 kbits.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-210","question":"A (7, 4) Hamming code is used for single-error correction. A codeword suffers exactly TWO bit errors. What does the decoder do?","options":["It detects the double error and asks for retransmission","It corrects both errors because the syndrome has 3 bits","It sees a zero syndrome and accepts the word unchanged","Its nonzero syndrome points to a third bit, which it flips, giving a wrong codeword"],"answer":3,"explanation":"The minimum distance is 3, so a double error lands at distance 1 from a different codeword; the syndrome is the XOR of the two error positions, which is nonzero and names some other position. Detecting doubles needs an extra overall parity bit (SEC-DED).","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-211","question":"A 900-byte binary file is attached to an email using Base64 (no line breaks). How many characters does the encoded attachment occupy?","options":["1200","900","1125","1800"],"answer":0,"explanation":"Base64 maps every 3 bytes to 4 ASCII characters: 900 / 3 × 4 = 1200, a 33% increase. MIME line breaks every 76 characters would add a little more.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-212","question":"Which TLS key-exchange choice gives forward secrecy, so that a later leak of the server's long-term private key does not reveal past sessions?","options":["RSA key transport of the pre-master secret","A longer RSA certificate key","Pre-shared key without (EC)DHE","Ephemeral (EC)Diffie–Hellman, as in ECDHE"],"answer":3,"explanation":"With ECDHE each session's secret comes from fresh key pairs that are discarded afterwards; the long-term key only signs the exchange. With RSA key transport the pre-master secret is encrypted with the server key, so anyone who later obtains that key can decrypt recorded traffic.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-213","question":"Which task is NOT performed by the data link layer?","options":["Framing the bit stream","Retransmitting a lost packet end to end between hosts several routers apart","Adding source and destination MAC addresses","Detecting bit errors with a CRC"],"answer":1,"explanation":"The data link layer works hop by hop on a single link: framing, MAC addressing, error detection and sometimes link-level retransmission. End-to-end reliability across routers is the transport layer's job (e.g. TCP).","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-214","question":"A leaky bucket holds at most 6 packets and sends at most 3 per tick. Each tick, arrivals are added first (any overflow beyond 6 is dropped), then up to 3 packets leave. Arrivals over 8 ticks are [5, 0, 7, 2, 0, 0, 3, 0]. How many packets are dropped, and how many leave in tick 4?","options":["1 dropped; 3 leave in tick 4","4 dropped; 3 leave in tick 4","1 dropped; 2 leave in tick 4","0 dropped; 3 leave in tick 4"],"answer":0,"explanation":"Queue after each tick: 5 → 2; 2 → 0 (sends 2); 0 + 7 = 7 > 6 so 1 is dropped, sends 3, leaving 3; 3 + 2 = 5, sends 3. Output per tick: [3, 2, 3, 3, 2, 0, 3, 0]. Total dropped 1.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-215","question":"A switch's MAC table ages out entries after 300 s. Host H was learned on port 3 and then moved silently to port 7 without sending anything. Another host now sends a frame to H. What happens?","options":["It floods the frame because the entry for H is no longer valid","It sends the frame out of both port 3 and port 7","It forwards the frame only out of port 3, so H misses it until the entry is refreshed or ages out","It drops the frame and returns an ICMP error to the sender"],"answer":2,"explanation":"A switch learns only from SOURCE addresses of frames it receives. Until H transmits from port 7 (refreshing the entry) or the 300 s timer expires, the table still says port 3. This is why hosts send gratuitous ARP after moving.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-216","question":"10.0.0.0/8 is divided into /22 subnets numbered from 0 in address order. Host 10.45.200.17 uses the mask 255.255.252.0. What is the number of its subnet and the subnet's broadcast address?","options":["Subnet 2931, broadcast 10.45.203.255","Subnet 2930, broadcast 10.45.200.255","Subnet 2930, broadcast 10.45.203.255","Subnet 5860, broadcast 10.45.201.255"],"answer":2,"explanation":"Each /22 spans 4 values of the third octet, so there are 64 per second-octet value. The subnet starts at 10.45.200.0 and ends at 10.45.203.255; its number is (45 × 256 + 200) / 4 = 2930. Counting from 1 gives 2931.","difficulty":"very-hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-217","question":"An organisation needs three LANs with 1000, 500 and 250 hosts, carved with VLSM from ONE contiguous CIDR block. What is the longest prefix (smallest block) that can hold all three?","options":["/22","/20","/23","/21"],"answer":3,"explanation":"Hosts plus network and broadcast need blocks of 1024, 512 and 256 addresses (/22, /23, /24), 1792 in total. That exceeds 1024 but fits in 2048, so a /21 is required. Adding the rounded block sizes (not the raw host counts) is the safe method, since blocks must be aligned powers of two.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-218","question":"A TCP sender transmits segments 1–8 back to back; segment 3 is lost and every other segment arrives. The receiver sends an ACK for every arriving segment. The arrival of which segment produces the duplicate ACK that triggers fast retransmit?","options":["Segment 6","Segment 5","Segment 4","Segment 7"],"answer":0,"explanation":"Segments 1 and 2 produce ACKs asking for 3. Segment 4 then generates the first duplicate, 5 the second and 6 the third duplicate ACK, which triggers fast retransmit of segment 3 without waiting for the timeout.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-219","question":"A TCP Reno sender (RFC 5681 fast recovery) has cwnd = 16 MSS when the third duplicate ACK arrives. Four MORE duplicate ACKs arrive, and then a new ACK that acknowledges all outstanding data. What is cwnd just before that new ACK, and right after it?","options":["8 MSS, then 9 MSS","15 MSS, then 8 MSS","19 MSS, then 16 MSS","11 MSS, then 1 MSS"],"answer":1,"explanation":"On the third duplicate: ssthresh = 16/2 = 8 and cwnd = ssthresh + 3 = 11 (inflated for the three segments that left the network). Each further duplicate adds 1 MSS: 11 + 4 = 15. The new ACK ends fast recovery and deflates cwnd to ssthresh = 8.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-220","question":"Selective Repeat uses 4-bit sequence numbers with the largest window that is safe. Frames take 1 ms to transmit on a 2 Mbps link, the one-way propagation delay is 10 ms and ACKs are negligible. What is the maximum throughput?","options":["1.429 Mbps","1.524 Mbps","1.455 Mbps","0.762 Mbps"],"answer":3,"explanation":"With k = 4 bits Selective Repeat allows W = 2^(k−1) = 8. One cycle lasts Tt + 2Tp = 21 ms, so utilisation = 8/21 ≈ 0.381 and throughput ≈ 0.762 Mbps. 15 is the Go-Back-N window for 4 bits.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-221","question":"CRC-32 (degree 32, nonzero constant term) is used on long frames. If a burst error of length exactly 33 bits occurs (all burst patterns equally likely), what is the probability it goes undetected?","options":["1/2³¹","0, every burst up to 33 bits is detected","1/2³²","1/2³³"],"answer":0,"explanation":"Bursts of length ≤ 32 are always caught. For length r + 1 = 33 the burst's first and last bits are 1, leaving 31 free middle bits; it escapes only if it equals the generator times x^i, one pattern in 2³¹. Longer bursts escape with probability 1/2³².","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-222","question":"A sender computes the 16-bit Internet checksum of the words 4500, 003C, 1C46, 4000, 4006 (hex) and sends 0x1E77. At the receiver the ones'-complement sum of the five data words plus the received checksum is computed. Which result means 'no error detected'?","options":["0x0000","0xFFFF","0x0100","0xE188"],"answer":1,"explanation":"The data words sum (with end-around carry) to 0xE188, and the checksum is its complement 0x1E77. Adding them gives all ones, 0xFFFF; any other result (for example 0x0100 after one bit flip in the checksum) signals an error.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-223","question":"A host sends a UDP datagram with 10 bytes of application data over IPv4 (20-byte header, no options) on Ethernet II. How many padding bytes does the Ethernet frame need, and what is the frame size from destination MAC through FCS?","options":["No padding; 52-byte frame","8 bytes of padding; 72-byte frame","8 bytes of padding; 64-byte frame","36 bytes of padding; 64-byte frame"],"answer":2,"explanation":"The IP packet is 20 + 8 + 10 = 38 bytes, but the Ethernet payload must be at least 46 bytes, so 8 bytes of padding are added. 14 header + 46 payload + 4 FCS = 64 bytes; the 8-byte preamble is not counted.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-224","question":"On 1 Gbps Ethernet every minimum-size frame (64 bytes) also costs an 8-byte preamble/SFD and a 12-byte inter-frame gap on the wire. What is the maximum number of frames per second?","options":["About 1.49 million","About 1.95 million","About 1.74 million","About 14.88 million"],"answer":0,"explanation":"Each frame occupies 64 + 8 + 12 = 84 byte-times = 672 bits, so 10⁹ / 672 ≈ 1,488,095 frames/s. Ignoring preamble and gap gives 1.95 million, an overestimate often used by mistake when sizing routers.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-225","question":"A site receives the IPv6 prefix 2001:db8:abcd::/48 and gives every LAN a /64. How many LAN subnets are possible, and how many interface IDs does each /64 offer?","options":["256 subnets; 2⁶⁴ interface IDs each","65,536 subnets; 2⁶⁴ − 2 usable IDs each","65,536 subnets; 2⁶⁴ interface IDs each","4096 subnets; 2⁸⁰ interface IDs each"],"answer":2,"explanation":"64 − 48 = 16 subnet bits give 2¹⁶ = 65,536 subnets. IPv6 has no broadcast address, so subtracting 2 as in IPv4 is wrong (although the subnet-router anycast address uses the all-zero ID).","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-226","question":"Which DNS name is queried for a reverse lookup of the IPv4 address 192.0.2.45, and what record type answers it?","options":["192.0.2.45.in-addr.arpa, PTR","45.2.0.192.in-addr.arpa, PTR","45.2.0.192.in-addr.arpa, A","192.0.2.45.ip6.arpa, CNAME"],"answer":1,"explanation":"Reverse names write the octets in reverse order under in-addr.arpa, so the most significant octet sits nearest the root, matching DNS's right-to-left hierarchy. The record that maps the name back to a host name is PTR.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-227","question":"A 4 MB file (1 MB = 10⁶ bytes) travels over a path of three links with rates 2 Mbps, 5 Mbps and 1 Mbps. Ignoring propagation and packetisation effects, roughly how long does the transfer take?","options":["4 s","16 s","3.2 s","32 s"],"answer":3,"explanation":"Throughput is limited by the bottleneck link, 1 Mbps: 4 × 10⁶ × 8 bits / 10⁶ bps = 32 s. 16 s would use the 2 Mbps link and 4 s confuses bytes with bits.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-228","question":"On a 1 Gbps link where signals travel at 2 × 10⁸ m/s, how long is one bit on the wire, and how many bits fill a 1000 km link?","options":["0.2 m per bit; 5 × 10⁶ bits","2 m per bit; 5 × 10⁵ bits","0.2 m per bit; 5 × 10⁹ bits","5 m per bit; 2 × 10⁵ bits"],"answer":0,"explanation":"Bit width = v / R = 2 × 10⁸ / 10⁹ = 0.2 m. The link holds R × Tp = 10⁹ × (10⁶ m / 2 × 10⁸ m/s = 5 ms) = 5 × 10⁶ bits, the bandwidth-delay product of one direction.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-229","question":"OSPF computes interface cost as 100 Mbps / bandwidth (minimum 1). Path X uses two 1 Gbps links and one 10 Mbps link; path Y uses four 100 Mbps links. Which path is chosen and with what cost?","options":["Path X, cost 3","Path Y, cost 4","Path X, cost 12","Path Y, cost 0.4"],"answer":1,"explanation":"With a 100 Mbps reference, 1 Gbps and 100 Mbps links both cost 1 (the minimum), and 10 Mbps costs 10. X = 1 + 1 + 10 = 12, Y = 4 × 1 = 4, so Y wins. Counting hops (3 vs 4) is what RIP would do.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-230","question":"How does BGP prevent routing loops between autonomous systems?","options":["It uses split horizon with poisoned reverse, like RIP","It limits AS_PATH length to 15, after which a route is unreachable","A router rejects any route whose AS_PATH already contains its own AS number","It floods link-state packets and runs Dijkstra on the AS graph"],"answer":2,"explanation":"BGP is a path-vector protocol: the full AS path travels with each route, so seeing your own AS means the route has looped. The 15-hop limit belongs to RIP, and flooding plus Dijkstra describes OSPF/IS-IS.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-231","question":"An IPv4 multicast group address is mapped to an Ethernet MAC address by placing its low-order 23 bits after the prefix 01:00:5E (with a 0 bit before them). What MAC does 239.130.5.77 map to, and how many IPv4 multicast groups share that MAC?","options":["01:00:5e:82:05:4d, 32 groups","01:00:5e:02:05:4d, 16 groups","01:00:5e:82:05:4d, 1 group","01:00:5e:02:05:4d, 32 groups"],"answer":3,"explanation":"Only the low 23 bits are copied, so 130 = 1000 0010 loses its top bit and becomes 0x02: the MAC is 01:00:5e:02:05:4d. Class D addresses have 28 variable bits and only 23 are copied, so 2⁵ = 32 groups share each MAC.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-232","question":"Which statement correctly contrasts a leaky bucket with a token bucket shaper?","options":["A token bucket outputs at a constant rate, while a leaky bucket allows bursts","Both allow unlimited bursts as long as the average rate is met","A leaky bucket outputs at a constant rate, while a token bucket allows bursts up to the bucket size and then the token rate","A leaky bucket drops tokens, while a token bucket drops packets only when tokens remain"],"answer":2,"explanation":"The leaky bucket smooths any input into a fixed output rate (excess packets wait or are dropped). The token bucket saves up credit while idle, so a source can send a burst of up to C bytes at line rate, then continues at ρ.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-233","question":"In an 802.11 WLAN, stations A and C are both in range of the access point B but cannot hear each other. Which problem does this create, and which mechanism mitigates it?","options":["The exposed-terminal problem; RTS/CTS reservation","The hidden-terminal problem; collision detection (CSMA/CD)","The near-far problem; power control","The hidden-terminal problem; RTS/CTS reservation"],"answer":3,"explanation":"A and C both sense an idle medium and transmit to B, colliding at B. With RTS/CTS, B's CTS is heard by both, so the other station defers for the announced duration. Wireless stations cannot detect collisions while transmitting, so CSMA/CD is not used.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-234","question":"Station B is sending to A. Station C, in range of B but not of A, wants to send to D, which is out of B's range. C senses B's transmission and defers, although its transmission would not have harmed A's reception. What is this called?","options":["The hidden-terminal problem","The exposed-terminal problem","The capture effect","Head-of-line blocking"],"answer":1,"explanation":"C is 'exposed' to B's signal and needlessly holds back, wasting capacity. In the hidden-terminal case it is the opposite: two senders cannot hear each other and collide at a common receiver.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-235","question":"A noiseless 3 kHz channel carries 64-QAM symbols at the Nyquist rate. What is the maximum bit rate?","options":["36 kbps","18 kbps","384 kbps","6 kbps"],"answer":0,"explanation":"Nyquist allows 2B = 6000 symbols/s, and 64-QAM carries log₂64 = 6 bits per symbol: 6000 × 6 = 36,000 bps. 18 kbps uses B instead of 2B; 384 kbps multiplies by 64 instead of 6.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-236","question":"What minimum signal-to-noise ratio (in dB) does a 200 kHz channel need to carry 1 Mbps according to Shannon?","options":["14.9 dB","15.1 dB","31 dB","29.8 dB"],"answer":0,"explanation":"C = B log₂(1 + S/N) gives log₂(1 + S/N) = 10⁶ / 2×10⁵ = 5, so S/N = 31, i.e. 10 log₁₀ 31 ≈ 14.9 dB. Reporting the ratio 31 itself as dB, or using 20 log (a voltage ratio formula), are common slips.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-237","question":"A UDP server and a TCP server are written with BSD sockets. Which statement is correct?","options":["Both servers call listen() and accept() before receiving data","Only the UDP server needs bind(); a TCP server gets a port from accept()","Only the TCP server calls listen() and accept(); the UDP server binds and calls recvfrom()","The TCP server calls connect() to wait for clients"],"answer":2,"explanation":"listen() turns a TCP socket into a passive one and accept() returns a new connected socket per client. UDP is connectionless: after bind() to a port the server reads datagrams with recvfrom(), learning each sender's address from it. connect() is the client's call.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-238","question":"What is the maximum size of the options area in a TCP header?","options":["20 bytes","40 bytes","60 bytes","44 bytes"],"answer":1,"explanation":"The 4-bit data-offset field counts 32-bit words, so the header is at most 15 × 4 = 60 bytes; subtracting the 20-byte fixed header leaves 40 bytes for options (MSS, window scale, SACK, timestamps).","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-239","question":"An attacker floods a server with SYNs from spoofed addresses and never completes the handshake. Which defence lets the server keep NO per-connection state until the final ACK arrives?","options":["Increasing the TIME_WAIT duration on the server","Disabling Nagle's algorithm on the listening socket","Advertising a larger receive window in the SYN-ACK","SYN cookies, which encode the state in the server's initial sequence number"],"answer":3,"explanation":"The SYN backlog is what fills up. With SYN cookies the SYN-ACK's ISN is a keyed hash of the 4-tuple, a timestamp and the MSS, so no entry is stored; a genuine client's ACK (ISN + 1) lets the server verify and recreate the state.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-240","question":"Which statement about firewalls is correct?","options":["A stateless filter recognises replies to inside connections from their payload","A stateful firewall admits replies to inside-initiated connections by tracking connection state","A stateful firewall inspects only IP headers and never TCP flags","An application-layer proxy operates only at the network layer"],"answer":1,"explanation":"A stateful firewall keeps a table of active connections (addresses, ports, TCP state) and matches returning packets against it. Stateless filters judge each packet alone using header fields (at best the ACK flag); proxies work at the application layer.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-241","question":"192.168.0.0/16 is divided into /26 subnets. In how many of these subnets is an address ending in .255 the BROADCAST address, and in how many is an address ending in .0 usable by a host?","options":["256 and 256","1024 and 0","512 and 256","256 and 0"],"answer":3,"explanation":"Each /24 contains four /26s; only the last one (.192–.255) has .255 as its broadcast, giving 256 subnets. An address ending in .0 is always the first address of the first /26 of its /24, i.e. a network address, so it is never usable here (it can be with shorter prefixes such as /23).","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-242","question":"A host with address 172.16.5.10/23 wants to reach 172.16.4.200. What does it do?","options":["Delivers directly on its LAN (ARP for 172.16.4.200), because both are in 172.16.4.0/23","Sends the packet to its default gateway, because the third octets differ","Broadcasts the packet to 172.16.5.255","Drops it, because 172.16.4.200 is a network address"],"answer":0,"explanation":"A /23 covers two consecutive values of the third octet starting at an even number: 172.16.4.0–172.16.5.255. Both addresses fall inside, so the host ARPs for the target directly. Comparing octets as if the mask were /24 is the trap.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-243","question":"A TCP connection runs over a 100 Mbps path with one-way propagation delay 10 ms. The window is fixed at 64 KB (65,536 bytes) and segments are 1500 bytes; ignore ACK size. What steady throughput is achieved (take one RTT = 2 × propagation + one segment's transmission time)?","options":["100.0 Mbps","52.4 Mbps","26.1 Mbps","3.3 Mbps"],"answer":2,"explanation":"The window-limited rate is 65,536 × 8 bits per (20 ms + 0.12 ms) ≈ 26.1 Mbps, well under the 100 Mbps link. Using only the one-way delay doubles it, and forgetting bits gives 3.3 Mbps.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-244","question":"Which pair correctly matches DNS record types with their purpose? MX, CNAME, NS, AAAA","options":["MX: mail server for the domain; CNAME: IPv6 address; NS: alias to a canonical name; AAAA: authoritative name server","MX: name server; CNAME: mail exchanger; NS: IPv4 address; AAAA: alias","MX: mail server for the domain; CNAME: alias to a canonical name; NS: authoritative name server; AAAA: IPv6 address","MX: alias to a canonical name; CNAME: mail server; NS: IPv6 address; AAAA: name server"],"answer":2,"explanation":"MX gives the mail exchangers (with preferences), CNAME makes one name an alias of another, NS names the authoritative servers for a zone, and AAAA holds an IPv6 address (A holds IPv4).","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-245","question":"Which statement about IPv4 fragmentation is correct?","options":["Only the destination host reassembles fragments; routers may fragment further but never reassemble","The last router before the destination reassembles fragments","Every router reassembles and re-fragments for the next link","IPv4 routers never fragment; only the source may"],"answer":0,"explanation":"Fragments may take different paths, so reassembly is left to the destination. IPv4 routers fragment when DF = 0 and the MTU is too small; it is IPv6 that forbids router fragmentation and relies on path-MTU discovery.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-246","question":"A router ACL entry reads: permit 10.1.0.0 with wildcard mask 0.0.254.255. Which destination address does it match?","options":["10.1.7.9","10.1.6.9","10.2.6.9","10.1.255.1"],"answer":1,"explanation":"Wildcard bits that are 0 must match. 0.0.254.255 leaves only the lowest bit of the third octet (and the first two octets) to check: it must be 0. So the entry matches 10.1.x.y with x EVEN: 10.1.6.9 matches, 10.1.7.9 and 10.1.255.1 have odd third octets, and 10.2.6.9 fails the second octet.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-247","question":"Which of these addresses (with its prefix length) can be assigned to a host interface?","options":["172.16.48.0/19","172.16.31.255/19","172.16.32.0/19","172.16.47.255/20"],"answer":0,"explanation":"/19 blocks the third octet in steps of 32 (0–31, 32–63), /20 in steps of 16. 172.16.31.255/19 is the broadcast of 0–31, 172.16.32.0/19 is a network address, 172.16.47.255/20 is the broadcast of 32–47. But 172.16.48.0/19 lies in the middle of 32–63, so it is an ordinary host address despite ending in .0.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-248","question":"Under old classful rules that forbid the all-zeros and all-ones subnets, a Class B network uses the mask 255.255.255.192. How many usable subnets and how many hosts per subnet does it provide?","options":["1024 subnets, 62 hosts","1022 subnets, 64 hosts","254 subnets, 62 hosts","1022 subnets, 62 hosts"],"answer":3,"explanation":"A Class B default mask is /16, so /26 borrows 10 bits: 2¹⁰ − 2 = 1022 subnets under the old rule, each with 2⁶ − 2 = 62 hosts. Modern CIDR practice allows subnet zero and would count 1024.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-249","question":"How many of the following statements about special IPv4 addresses are correct?\n1. 169.254.0.0/16 is used for link-local (APIPA) addresses when DHCP fails.\n2. Any address in 127.0.0.0/8 refers to the local host.\n3. 100.64.0.0/10 is reserved as shared address space for carrier-grade NAT.\n4. A router forwards a packet addressed to 255.255.255.255 out of all its interfaces.\n5. 0.0.0.0 may be used as a source address by a host that does not yet know its own address.","options":["5","3","4","2"],"answer":2,"explanation":"1, 2, 3 and 5 are true (DHCPDISCOVER uses source 0.0.0.0). Statement 4 is false: 255.255.255.255 is the limited broadcast, confined to the local link; routers never forward it.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-250","question":"What is the correct canonical (RFC 5952) text form of the IPv6 address 2001:0db8:0000:0000:0001:0000:0000:0001?","options":["2001:db8:0:0:1::1","2001:db8::1::1","2001:0db8::1:0:0:1","2001:db8::1:0:0:1"],"answer":3,"explanation":"Leading zeros are dropped in every group, and '::' may replace only ONE run of zero groups. Both zero runs have length 2, and RFC 5952 compresses the first (leftmost) one in a tie, giving 2001:db8::1:0:0:1. Using '::' twice is ambiguous and invalid.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-251","question":"Before using the address 2001:db8::2aa:ff:fe28:9c5a, an IPv6 host performs duplicate address detection by sending a Neighbor Solicitation to the address's solicited-node multicast group. Which group is it?","options":["ff02::1:ff00:9c5a","ff02::2:ff28:9c5a","ff02::1:ff28:9c5a","ff05::1:ff28:9c5a"],"answer":2,"explanation":"The solicited-node group is ff02::1:ff00:0/104 with the low 24 bits of the unicast address appended: 28:9c5a → ff02::1:ff28:9c5a. It is link-local scope (ff02); ff05 is site-local scope, and copying only 16 bits gives ff00:9c5a.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-252","question":"Two hosts on Ethernet (MTU 1500) use IPv4 without options and TCP with the timestamps option (which takes 12 bytes per segment including padding). How many bytes of application data fit in one full-sized segment?","options":["1460","1448","1480","1436"],"answer":1,"explanation":"1500 − 20 (IP) − 20 (TCP) = 1460 is the advertised MSS, but the timestamp option occupies 12 bytes of the TCP header in every segment, leaving 1448 bytes of data. 1480 forgets the TCP header.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-253","question":"What is the largest UDP payload that a single IPv4 datagram (no IP options) can carry?","options":["65,507 bytes","65,535 bytes","65,515 bytes","65,527 bytes"],"answer":0,"explanation":"The IPv4 total-length field is 16 bits, so at most 65,535 bytes including the 20-byte IP header and 8-byte UDP header: 65,535 − 28 = 65,507. Such a datagram is of course fragmented on most links.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-254","question":"A TCP receiver using SACK has received bytes 1–1000, then 4001–5000, then 2001–3000, in that order; byte 1001 is still missing. What does the ACK sent after 2001–3000 arrives carry?","options":["ACK 3001 with SACK block 4001–5001","ACK 1001 with SACK blocks 4001–5001 first, then 2001–3001","ACK 5001 with no SACK blocks","ACK 1001 with SACK blocks 2001–3001 first, then 4001–5001"],"answer":3,"explanation":"The cumulative ACK stays at 1001 (the first missing byte). SACK blocks give [left edge, right edge) of received runs, and RFC 2018 requires the block containing the most recently received segment to be listed first, so 2001–3001 precedes 4001–5001.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-255","question":"A TCP receiver advertises a zero window, and later its window-update segment (which reopens the window) is lost. What prevents the connection from deadlocking?","options":["The retransmission timer, which resends the last data segment until it is ACKed","The sender's persist timer, which keeps sending zero-window probes","The keepalive timer, which closes the connection after 2 hours","The TIME_WAIT timer, which waits 2 MSL before resending"],"answer":1,"explanation":"With a zero window the sender has no data in flight, so no retransmission timer would fire, and window updates themselves are not retransmitted. The persist timer makes the sender probe periodically (with exponential backoff) so the lost update is eventually replaced.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-256","question":"The data 1011011011 is sent with a CRC using the generator x³ + x² + 1. Which 3-bit remainder is appended?","options":["111","001","010","000"],"answer":0,"explanation":"Append three 0s and divide modulo 2 by 1101; the remainder is 111. Dividing by 1011 (x³ + x + 1) by mistake gives 001. The receiver divides the whole 13-bit frame by 1101 and expects remainder 000.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-257","question":"Stop-and-wait runs at 1 Mbps with 1000-byte data frames and 64-byte ACK frames. The one-way propagation delay is 5 ms and each side needs 0.5 ms to process a frame. What is the link utilisation?","options":["44.4%","43.2%","41.0%","57.1%"],"answer":2,"explanation":"One cycle = 8 ms (data) + 0.512 ms (ACK) + 10 ms (two propagations) + 1 ms (two processing delays) = 19.512 ms, so utilisation = 8 / 19.512 ≈ 41.0%. Ignoring the ACK and processing gives 44.4%.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-258","question":"Using the classic CSMA/CD efficiency model η = 1 / (1 + 2BLe / cF) (B = bit rate, L = cable length, c = signal speed, F = frame length in bits, e ≈ 2.718), what is the efficiency of 1 Gbps Ethernet with 1 km of cable, c = 2 × 10⁸ m/s and 1024-byte frames?","options":["45.0%","37.6%","3.6%","23.2%"],"answer":3,"explanation":"2BLe / cF = 2 × 10⁹ × 1000 × 2.718 / (2 × 10⁸ × 8192) ≈ 3.32, so η ≈ 23.2%. The low value is why gigabit Ethernet needed carrier extension or switched full-duplex links.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-259","question":"How many of the following statements about classic Ethernet binary exponential backoff are correct?\n1. After the n-th collision a station waits K slot times with K chosen uniformly from 0 to 2ⁿ − 1.\n2. The range stops growing after the 10th collision (0 to 1023).\n3. After 16 failed attempts the frame is discarded and an error reported.\n4. Backoff guarantees that two colliding stations never collide again on the next attempt.","options":["4","2","3","1"],"answer":2,"explanation":"1–3 describe IEEE 802.3. Statement 4 is false: both stations can pick the same K (probability 1/2ⁿ when both have had n collisions), which is why the range keeps doubling.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-260","question":"Switch S4 has two paths to the STP root bridge. Port 1 connects via a 100 Mbps link (cost 19) to S2, whose root path cost is 4. Port 2 connects via a 1 Gbps link (cost 4) to S3, whose root path cost is 23. Which port becomes S4's root port, and what is S4's root path cost?","options":["Port 1, cost 23","Port 2, cost 27","Port 2, cost 4","Port 1, cost 19"],"answer":0,"explanation":"Root path cost through a port = neighbour's advertised root path cost + the cost of the link to it: port 1 gives 4 + 19 = 23, port 2 gives 23 + 4 = 27. The lower total wins, even though port 2 is the faster local link.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-261","question":"Four CDMA stations use the orthogonal chip sequences A = (+1, +1, +1, +1), B = (+1, −1, +1, −1), C = (+1, +1, −1, −1), D = (+1, −1, −1, +1); a station sends its sequence for bit 1, its negation for bit 0, or nothing. The receiver sees S = (1, 1, -1, 3). What did each station send?","options":["A sent 1, B sent 1, C silent, D sent 0","A sent 1, B sent 0, C silent, D sent 1","A sent 1, B sent 0, C sent 0, D sent 1","A sent 0, B sent 0, C silent, D sent 1"],"answer":1,"explanation":"Decode by the normalised inner product S·X / 4: A gives (1 + 1 − 1 + 3)/4 = 1, B gives (1 − 1 − 1 − 3)/4 = −1 (bit 0), C gives (1 + 1 + 1 − 3)/4 = 0 (silent), D gives (1 − 1 + 1 + 3)/4 = 1. Orthogonality makes the other stations' terms vanish.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-262","question":"A network of 1200 routers uses hierarchical routing with three levels: 10 clusters, each of 6 regions, each of 20 routers. How many routing-table entries does each router need (compared with 1200 for flat routing)?","options":["69","36","34","120"],"answer":2,"explanation":"A router needs an entry for each router in its region (20), each OTHER region in its cluster (5) and each OTHER cluster (9): 20 + 5 + 9 = 34. A two-level split into 30 regions of 40 would need 40 + 29 = 69. The saving costs some path optimality.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-263","question":"In a network of 5 routers where every pair is directly connected, a source floods a packet: each router that receives it forwards a copy on every line except the one it arrived on, and copies carry a hop counter initialised to 2 that is decremented per hop (a copy arriving with counter 0 is not forwarded). How many packet transmissions occur in total?","options":["16","20","12","8"],"answer":0,"explanation":"Hop 1: the source sends on its 4 lines (4 transmissions, counter now 1). Each of the 4 receivers forwards on its 3 other lines: 12 transmissions, which arrive with counter 0 and stop. Total 4 + 12 = 16, even though only 4 routers needed the packet.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-264","question":"Match the ICMP message types: P. 0  Q. 3  R. 5  S. 11  with  1. Redirect  2. Echo reply  3. Time exceeded  4. Destination unreachable.","options":["P-2, Q-3, R-1, S-4","P-2, Q-4, R-1, S-3","P-4, Q-2, R-3, S-1","P-1, Q-4, R-2, S-3"],"answer":1,"explanation":"Type 0 is echo reply (8 is echo request), 3 is destination unreachable (including 'fragmentation needed'), 5 is redirect, and 11 is time exceeded, which traceroute relies on.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-265","question":"How does IPv4 Path MTU Discovery learn the smallest MTU on a path?","options":["Each router appends its MTU to an IP option, and the receiver reports the minimum","The sender sends progressively larger pings until one times out","The destination returns the MTU of its own link in the TCP SYN-ACK","The sender sets DF; a router that would have to fragment returns ICMP 'fragmentation needed' with its MTU"],"answer":3,"explanation":"PMTUD relies on DF and ICMP type 3 code 4 messages; the sender lowers its packet size accordingly. Firewalls that block all ICMP cause 'PMTU black holes'. The MSS option in a SYN reflects only the endpoints' own links.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-266","question":"A DHCP client gets an 8-hour lease at 09:00. By default, at what times does it first try to RENEW with the same server (unicast), and when does it start REBINDING (broadcast to any server) if renewal keeps failing?","options":["13:00 and 16:00","13:00 and 17:00","17:00 and 16:00","11:00 and 15:00"],"answer":0,"explanation":"T1 defaults to 50% of the lease (4 h → 13:00), when the client unicasts DHCPREQUEST to its server. T2 defaults to 87.5% (7 h → 16:00), when it broadcasts to any server. At 17:00 the lease expires and the address must be dropped.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-267","question":"Why can an attacker on the same LAN redirect a victim's traffic to itself with ARP spoofing, and which switch feature defends against it?","options":["ARP uses TCP, so replies can be hijacked; port security on routers stops it","ARP replies are unauthenticated and accepted unsolicited; Dynamic ARP Inspection blocks forged ones","ARP replies are broadcast, so anyone can read them; VLANs encrypt them","ARP caches never expire; rebooting the switch clears the poison"],"answer":1,"explanation":"A host updates its cache from any ARP reply, even one it never asked for, so forged replies map the gateway's IP to the attacker's MAC. DAI drops ARP packets whose IP–MAC pair does not match the trusted DHCP snooping table.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-268","question":"Ignoring DNS and transmission time, how many RTTs pass from the start of the TCP handshake until the first byte of the HTTP response arrives over HTTPS with (i) a full TLS 1.2 handshake and (ii) a full TLS 1.3 handshake?","options":["(i) 3 RTTs, (ii) 2 RTTs","(i) 4 RTTs, (ii) 4 RTTs","(i) 4 RTTs, (ii) 3 RTTs","(i) 5 RTTs, (ii) 3 RTTs"],"answer":2,"explanation":"TCP's handshake takes 1 RTT. TLS 1.2 needs 2 RTTs (ClientHello/ServerHello…, then key exchange/Finished), TLS 1.3 only 1, and the HTTP request/response adds 1: 1 + 2 + 1 = 4 versus 1 + 1 + 1 = 3. TLS 1.3 0-RTT resumption can cut it to 2.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-269","question":"Which set contains ONLY idempotent HTTP methods (repeating the same request has the same effect on the server as sending it once)?","options":["GET, POST, PUT","POST, PATCH, DELETE","PUT, POST, HEAD","GET, PUT, DELETE"],"answer":3,"explanation":"GET and HEAD do not change state, PUT replaces a resource with the same content each time, and DELETE leaves the resource deleted. POST (and in general PATCH) can create or change something on every call, which is why browsers warn before resubmitting a POST.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-270","question":"A reverse proxy forwards a request to an application server. Which status does the proxy return to the client when the application server sends back an invalid response, and which when the application server does not answer in time?","options":["504 Gateway Timeout, then 502 Bad Gateway","500 Internal Server Error, then 408 Request Timeout","502 Bad Gateway, then 504 Gateway Timeout","503 Service Unavailable, then 504 Gateway Timeout"],"answer":2,"explanation":"502 means the gateway received an invalid response from upstream; 504 means it gave up waiting. 408 is the server timing out the CLIENT's request, and 503 means the server itself is overloaded or in maintenance.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-271","question":"The zone example.com is delegated to the name server ns1.example.com. Why must the .com servers also return an A record for ns1.example.com in the referral?","options":["The server's name lies inside the zone it serves, so its address must come from the parent (glue)","Because NS records may contain IP addresses only, never names","To let the resolver skip the example.com server entirely","Because the A record is needed only for reverse DNS"],"answer":0,"explanation":"The name server's name lies inside the zone it serves, so a resolver cannot find its address without first contacting it. The parent zone therefore includes 'glue' A/AAAA records with the referral.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-272","question":"A DNS answer is too large for a 512-byte UDP response and EDNS(0) is not in use. What happens?","options":["The server fragments the answer into several UDP datagrams with sequence numbers","The server sends a truncated response with the TC bit set, and the client retries the query over TCP","The server silently drops the extra records","The client sends the query again with a larger UDP port number"],"answer":1,"explanation":"Classic DNS limits UDP messages to 512 bytes; the TC (truncated) flag tells the client to repeat the query over TCP port 53. EDNS(0) lets clients advertise larger UDP buffers, which DNSSEC responses often need.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-273","question":"A 1 Gb file must reach 100 peers. The server uploads at 50 Mbps; every peer downloads at 10 Mbps and uploads at 2 Mbps. What are the minimum distribution times for client-server and for P2P distribution?","options":["2000 s and 100 s","10000 s and 400 s","20 s and 400 s","2000 s and 400 s"],"answer":3,"explanation":"Client-server: max(NF/us, F/dmin) = max(2000, 100) = 2000 s. P2P: max(F/us, F/dmin, NF/(us + Σui)) = max(20, 100, 10¹¹ / (50 + 200) Mbps = 400) = 400 s. Peer uploads add 200 Mbps of capacity, but the aggregate term still dominates.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-274","question":"A TDM system carries 30 voice channels, each sampled 8000 times per second with 8-bit samples, plus 2 overhead slots of 8 bits in every frame. What is the line rate, and what fraction carries voice?","options":["2.048 Mbps; 93.75%","1.920 Mbps; 100%","2.048 Mbps; 6.25%","1.544 Mbps; 93.75%"],"answer":0,"explanation":"Each 125 µs frame has 32 slots × 8 bits = 256 bits, so the line rate is 256 × 8000 = 2.048 Mbps (the E1 rate). Voice uses 30/32 = 93.75%. 1.544 Mbps is the T1 rate (24 channels + 1 framing bit).","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-275","question":"A 1.2 Mb file is sent over a circuit-switched TDM link of 2.048 Mbps divided into 32 equal slots; the circuit gets one slot, and setting it up takes 400 ms. How long until the file is fully sent?","options":["0.99 s","18.75 s","17.98 s","19.15 s"],"answer":3,"explanation":"One slot gives 2.048 Mbps / 32 = 64 kbps, so transmission takes 1.2 × 10⁶ / 64,000 = 18.75 s, plus 0.4 s setup = 19.15 s. Using the full link rate (0.99 s) ignores that the circuit owns only one slot.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-276","question":"Bursts of 9 packets (1500 bytes each) arrive at the same instant on an empty 10 Mbps output link, and the link finishes each burst before the next one arrives. What is the average queueing delay per packet (not counting its own transmission)?","options":["9.6 ms","5.4 ms","4.8 ms","1.2 ms"],"answer":2,"explanation":"The k-th packet waits (k − 1) × 1.2 ms, so the average is (0 + 1 + … + 8)/9 × 1.2 ms = (N − 1)L/2R = 4.8 ms. 9.6 ms is the LAST packet's wait, not the average.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-277","question":"100 users each need to communicate privately with every other user. How many keys are needed with symmetric (secret-key) cryptography, and how many key pairs with public-key cryptography?","options":["100 secret keys; 4950 key pairs","4950 secret keys; 100 key pairs","9900 secret keys; 100 key pairs","4950 secret keys; 4950 key pairs"],"answer":1,"explanation":"Each pair of users needs its own shared secret: C(100, 2) = 100 × 99 / 2 = 4950. With public keys each user needs just one pair (200 keys in all), since anyone can encrypt with a user's public key.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-278","question":"Alice wants Bob to receive a message that only Bob can read AND that Bob can verify came from Alice. Which keys are used?","options":["Sign with Bob's public key, encrypt with Alice's private key","Sign and encrypt with Alice's private key","Sign with Alice's public key, encrypt with Bob's private key","Sign with Alice's private key, encrypt with Bob's public key"],"answer":3,"explanation":"Signing needs something only Alice has (her private key), checkable by anyone with her public key. Confidentiality needs something only Bob can undo (his private key), so Alice encrypts with Bob's public key.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-279","question":"How many of the following statements about IPsec are correct?\n1. In tunnel mode, ESP encrypts the entire original IP packet and adds a new outer IP header.\n2. AH provides integrity and origin authentication but no confidentiality.\n3. AH works smoothly through NAT because it does not cover IP addresses.\n4. In transport mode the original IP header is kept and only the payload is protected.","options":["4","3","2","1"],"answer":1,"explanation":"1, 2 and 4 are true. Statement 3 is false: AH's integrity check covers the immutable IP header fields, including the addresses, so NAT rewriting them breaks verification; ESP with UDP encapsulation is used through NAT.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-280","question":"A firewall applies the first matching rule:\n1. deny tcp from any to 10.0.0.0/8 port 23\n2. permit tcp from 192.168.1.0/24 to any port 22–23\n3. deny ip from 192.168.1.128/25 to any\n4. permit ip from any to any\nWhat happens to (a) TCP 192.168.1.200 → 10.1.1.1:23, (b) TCP 192.168.1.200 → 172.16.0.1:23, (c) UDP 192.168.1.130 → 8.8.8.8:53?","options":["deny, permit, deny","deny, deny, deny","deny, permit, permit","permit, permit, deny"],"answer":0,"explanation":"(a) matches rule 1 first: deny. (b) is not to 10/8, so rule 2 permits it before rule 3 (which would deny its source) is reached. (c) is UDP, so rules 1–2 do not apply and rule 3 denies it. Order matters more than specificity.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-281","question":"A 20 mW signal travels through 3 km of cable that loses 6 dB per km and then through an amplifier with 10 dB gain. What is the output power?","options":["0.32 mW","25.18 mW","3.17 mW","164.0 mW"],"answer":2,"explanation":"Net gain = −18 + 10 = −8 dB, so P = 20 mW × 10^(−0.8) ≈ 3.17 mW. Decibels add along a chain; treating 6 dB/km as a percentage loss, or using 20 log for power, gives wrong values.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-282","question":"172.20.0.0/22 is divided with VLSM for LANs of 500, 200, 100 and 60 hosts, largest first, each at the lowest free aligned address. Which subnet does the 60-host LAN get?","options":["172.20.3.192/26","172.20.3.128/25","172.20.2.192/26","172.20.3.128/26"],"answer":3,"explanation":"Blocks: 500 → /23 (172.20.0.0/23), 200 → /24 (172.20.2.0/24), 100 → /25 (172.20.3.0/25), 60 → /26 (172.20.3.128/26). Total 512 + 256 + 128 + 64 = 960 ≤ 1024, so everything fits with 64 addresses to spare.","difficulty":"very-hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-283","question":"From 10.10.10.0/26, one /28 is assigned to a server LAN. How many /30 point-to-point links can be carved from the remaining addresses?","options":["16","12","11","14"],"answer":1,"explanation":"A /26 has 64 addresses; the /28 uses 16, leaving 48. Each /30 uses 4 addresses (2 usable), so 48 / 4 = 12 links. 16 forgets the /28.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-284","question":"A firewall allows traffic to 10.0.0.0/9, 10.64.0.0/10, 10.128.0.0/10 and 10.192.0.0/11. How many distinct destination addresses are allowed?","options":["18,874,368","16,777,216","14,680,064","12,582,912"],"answer":2,"explanation":"10.64.0.0/10 lies inside 10.0.0.0/9 (10.0–10.127), so it adds nothing. The union is 2²³ + 2²² + 2²¹ = 14,680,064. Simply adding all four sizes double-counts the nested /10.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-285","question":"A packet capture shows the destination address as the hexadecimal value C0A80A64, on a network using /28 subnets. What is the address in dotted decimal, and which subnet is it in?","options":["192.168.10.100, subnet 192.168.10.96/28","192.168.10.100, subnet 192.168.10.64/28","192.168.10.64, subnet 192.168.10.64/28","192.168.10.100, subnet 192.168.10.112/28"],"answer":0,"explanation":"C0 = 192, A8 = 168, 0A = 10, 64 hex = 100. /28 blocks go in steps of 16, and 100 lies in 96–111, so the subnet is 192.168.10.96/28. Reading 64 as decimal gives the wrong host.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-286","question":"The first 20 bytes of an IPv4 header are (hex): 45 00 05 DC 1C 46 40 00 3F 11 B1 E6 C0 A8 00 01 C0 A8 00 C7. How many bytes of payload does the packet carry, which protocol does it carry, and may routers fragment it?","options":["1500 bytes of UDP; no, DF is set","1480 bytes of TCP; yes, DF is clear","1480 bytes of UDP; yes, MF is clear","1480 bytes of UDP; no, DF is set"],"answer":3,"explanation":"45: version 4, IHL 5 → 20-byte header. Total length 0x05DC = 1500, so payload = 1480. Flags/offset 0x4000 has the DF bit set. Protocol 0x11 = 17 = UDP (TCP would be 6). TTL is 0x3F = 63.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-287","question":"A TCP header begins (hex): 01 BB C3 50 00 00 00 00 7A 3F 10 01 50 12 FA F0. Which statement is correct?","options":["It is a SYN-ACK from port 443 to port 50000, acknowledging 0x7A3F1001","It is a SYN from port 50000 to port 443","It is a SYN-ACK from port 443 to port 50000 with a 40-byte header","It is a FIN-ACK from port 443 to port 50000"],"answer":0,"explanation":"Source port 0x01BB = 443, destination 0xC350 = 50000. Byte 12 = 0x50 gives data offset 5 (20-byte header); byte 13 = 0x12 sets ACK (0x10) and SYN (0x02). The ACK field 0x7A3F1001 is meaningful because ACK is set; FIN would be 0x01.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-288","question":"A 2024-byte IPv4 datagram has a 24-byte header (4 bytes of options that are copied into every fragment). It must cross a link with MTU 600. How many fragments are made, and what is the total-length field of the last one?","options":["4 fragments; last total length 280","5 fragments; last total length 296","4 fragments; last total length 296","4 fragments; last total length 272"],"answer":2,"explanation":"Each fragment carries at most 600 − 24 = 576 data bytes (already a multiple of 8). 2000 bytes → 576 + 576 + 576 + 272, offsets 0, 72, 144, 216. The last fragment's total length is 272 + 24 = 296. Assuming a 20-byte header gives 580-byte pieces and a different tail.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-289","question":"Stop-and-wait with 1-bit sequence numbers: the receiver gets frame 0 and its ACK is lost. What happens next?","options":["The receiver delivers frame 0 twice to the network layer","The sender resends frame 0; the receiver discards the duplicate and re-ACKs it","The sender moves on to frame 1 because the frame was received","The receiver sends a NAK for frame 1 to trigger progress"],"answer":1,"explanation":"The sequence bit is exactly what lets the receiver tell a retransmission from a new frame: it is expecting 1, sees 0 again, drops the copy but re-sends the ACK so the sender can advance.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-290","question":"Go-Back-N with cumulative ACKs sends frames 0–9 with a window of 5. Only the ACK for frame 2 is lost; every frame and every other ACK arrives in time. How many frame transmissions take place in total?","options":["13","11","10","15"],"answer":2,"explanation":"The ACK for frame 3 arrives before frame 2's timer expires, and a cumulative ACK for 3 also confirms 0–2, so nothing is resent. Retransmissions happen only if no later ACK arrives before the timeout.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-291","question":"A 10 Gbps path has an RTT of 100 ms. With 1500-byte frames, at least how many frames must be outstanding to keep it fully busy?","options":["83,334","8,333","166,667","833"],"answer":0,"explanation":"Bandwidth × RTT = 10¹⁰ × 0.1 = 10⁹ bits = 1.25 × 10⁸ bytes, i.e. 10⁹ / 12,000 ≈ 83,334 frames in flight. 8,333 uses a 10 ms RTT, and 166,667 uses 750-byte frames.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-292","question":"A client downloads a 64 KB file (MSS = 1 KB, so 64 segments) over a fast link with RTT = 100 ms. TCP starts with cwnd = 1 MSS, slow start doubles cwnd every RTT, there are no losses and the receiver window is large. Counting the handshake (1 RTT, with the request sent along with the final ACK), roughly how long until the last segment is received? Ignore transmission times.","options":["About 600 ms (6 RTTs)","About 750 ms (7.5 RTTs)","About 650 ms (6.5 RTTs)","About 6.4 s (64 RTTs)"],"answer":1,"explanation":"After the 1-RTT handshake, rounds send 1, 2, 4, 8, 16, 32 segments (63 in 6 rounds) and the 64th goes in round 7. The data of round 7 arrives half an RTT after it is sent: 1 + 6 + 0.5 = 7.5 RTTs = 750 ms. Without slow start (full window) it would take about 1.5 RTTs.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-293","question":"A TCP sender has cwnd = 20 MSS but the receiver's window is only 12 MSS, so 12 segments are in flight when a retransmission timeout occurs. Following RFC 5681 (ssthresh = max(FlightSize / 2, 2·SMSS)), what are the new ssthresh and cwnd?","options":["ssthresh = 10 MSS, cwnd = 1 MSS","ssthresh = 6 MSS, cwnd = 6 MSS","ssthresh = 10 MSS, cwnd = 10 MSS","ssthresh = 6 MSS, cwnd = 1 MSS"],"answer":3,"explanation":"RFC 5681 halves the amount of data actually in flight, not cwnd: FlightSize = min(cwnd, rwnd) = 12, so ssthresh = 6. After a timeout cwnd restarts at 1 MSS (the loss window). Halving cwnd = 20 is the common mistake.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-294","question":"Two TCP flows share a bottleneck and both use AIMD (additive increase, multiplicative decrease) with the same RTT. Starting from very unequal rates, what happens over time?","options":["The larger flow keeps its advantage forever","Both flows oscillate but their ratio stays constant","The smaller flow starves because it increases more slowly","Their rates converge toward an equal share of the link"],"answer":3,"explanation":"Additive increase moves both rates along a 45° line (equal gains), and multiplicative decrease pulls the point toward the origin, shrinking the difference each cycle. Repeated cycles converge to the fair-share line; with MIMD the ratio would stay fixed.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-295","question":"Which error does the 16-bit Internet checksum (ones'-complement sum) FAIL to detect?","options":["Two 16-bit words exchanging their positions in the data","A single flipped bit anywhere in the data","An odd number of flipped bits in the same bit position of different words","A burst error of up to 15 bits within one word"],"answer":0,"explanation":"Addition is commutative, so reordering words leaves the sum unchanged; this is a known weakness compared with CRC. A single bit flip always changes the sum, and an odd number of flips in one bit column changes that column's parity contribution.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-296","question":"A receiver using the CRC generator 11001 (x⁴ + x³ + 1) receives the 14-bit frame 11010010110100. What remainder does it compute, and what does it conclude?","options":["0000; the frame is accepted","1110; the frame is accepted because the data part is intact","1110; an error is detected","0000; an error is detected"],"answer":2,"explanation":"Dividing the whole received frame by 11001 gives remainder 1110, which is nonzero, so the frame is rejected. (The frame actually transmitted was 11010110110100; bit 6 was flipped.) Only a zero remainder means 'no error detected'.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-297","question":"A (7, 4) Hamming code uses ODD parity, with bit layout p1 p2 d3 p4 d5 d6 d7 (positions 1–7 from the left); each check bit makes its group (positions containing that power of two) have an odd number of 1s. The word 1101100 is received, with at most one bit in error. What are the corrected data bits d3 d5 d6 d7?","options":["0100","0000","0101","1011"],"answer":1,"explanation":"Group 1 (positions 1, 3, 5, 7), group 2 (2, 3, 6, 7) and group 4 (4, 5, 6, 7) are checked for ODD parity; the failing groups sum to position 5. Flipping it gives 1101000, whose data bits are 0000. Checking for even parity instead would point to a different bit.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-298","question":"How many of these MAC addresses are group (multicast or broadcast) addresses?\n01:00:5E:00:00:FB, 03:00:00:00:00:01, 02:1A:2B:3C:4D:5E, FF:FF:FF:FF:FF:FF, 00:1B:44:11:3A:B7","options":["2","4","3","1"],"answer":2,"explanation":"The I/G bit is the least significant bit of the first octet: 01, 03 and FF have it set, so they are group addresses (FF…FF is the broadcast). 02 has only the U/L bit set, making it a locally administered UNICAST address, and 00 is ordinary unicast.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-299","question":"Four switches are connected in a full mesh (every pair linked, 6 links) and run Spanning Tree. How many links end up blocked (forwarding on neither end)?","options":["2","3","4","6"],"answer":1,"explanation":"A spanning tree on 4 switches has exactly 3 links; the other 6 − 3 = 3 links each have one port in the blocking state, removing every loop. In general n switches with L links block L − (n − 1) links.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-300","question":"Routers A–B–C–D–E form a line (cost 1 per link) and start a synchronous distance-vector protocol knowing only their direct neighbours. After how many rounds of vector exchange does A first know its distance to E?","options":["3","4","2","5"],"answer":0,"explanation":"After round k each router knows destinations up to k + 1 hops away: round 1 gives A the route to C, round 2 to D, round 3 to E (4 hops). Good news spreads one hop per exchange.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-301","question":"Link-state routing on: R1–R2 2, R1–R3 5, R2–R3 1, R2–R4 7, R3–R4 2, R3–R5 6, R4–R5 1, R4–R6 4, R5–R6 2. In R1's forwarding table, what is the next hop and cost for R6?","options":["Next hop R3, cost 8","Next hop R2, cost 9","Next hop R3, cost 9","Next hop R2, cost 8"],"answer":3,"explanation":"Shortest path R1 → R2 → R3 → R4 → R5 → R6 costs 2 + 1 + 2 + 1 + 2 = 8 (R1 → R3 directly costs 5 > 3 via R2). The next hop is the first router on that path, R2. Going R4 → R6 directly costs 9.","difficulty":"very-hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-302","question":"Which statement about OSPF areas is correct?","options":["Routers in different areas exchange full link-state databases","An area border router belongs to exactly one area","Every non-backbone area must attach to area 0 through an ABR (or a virtual link)","Area 0 is optional when there are only two areas"],"answer":2,"explanation":"OSPF's hierarchy is two-level: inter-area traffic passes through the backbone, so each area attaches to area 0. ABRs sit in two or more areas and send summaries, not full LSDBs, between them.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-303","question":"A NAT router (public IP 203.0.113.5) holds the entry 192.168.1.20:51000 ↔ 203.0.113.5:62001 for a connection to 93.184.216.34:443. A packet arrives from 93.184.216.34:443 to 203.0.113.5:62001. What does the router forward into the LAN?","options":["A packet from 93.184.216.34:443 to 192.168.1.20:51000","A packet from 203.0.113.5:62001 to 192.168.1.20:51000","A packet from 93.184.216.34:443 to 192.168.1.20:62001","Nothing: inbound packets are always dropped by NAT"],"answer":0,"explanation":"For inbound traffic NAT rewrites only the DESTINATION (public IP and port) back to the private host's IP and port; the remote source stays as is. Unsolicited inbound packets with no table entry are dropped, but this one matches an existing mapping.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-304","question":"With HTTP/1.1 pipelining, a client sends requests for A (large, slow to generate), B and C on one connection without waiting. In what order must the server send the responses?","options":["B and C first, since they are ready sooner","Any order, matched by request IDs","Interleaved frames of A, B and C","A, B, C, in request order, so B and C wait behind A (head-of-line blocking)"],"answer":3,"explanation":"HTTP/1.1 has no request IDs, so responses must come back in the order the requests were sent. This head-of-line blocking is why pipelining was rarely enabled and why HTTP/2 introduced multiplexed streams with IDs.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-305","question":"An institution's users request 15 web objects per second on average, each 1 Mb, over a 15 Mbps access link. A proxy cache is installed with a 40% hit rate. What is the access link's utilisation before and after?","options":["100% before, 40% after","100% before, 60% after","100% before, 100% after","60% before, 24% after"],"answer":1,"explanation":"Before: 15 req/s × 1 Mb = 15 Mbps on a 15 Mbps link, utilisation 1.0, so queueing delay explodes. With 40% served locally only 60% cross the link: 9 Mbps, utilisation 0.6, which keeps queueing delay small.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-306","question":"A browser needs www.shop.example: the local resolver (RTT 2 ms) has nothing cached and contacts the root, TLD and authoritative servers iteratively (each RTT 40 ms). The page is a single small object fetched with non-persistent HTTP from a server 40 ms away. Ignoring transmission times, how long from typing the URL until the page arrives?","options":["82 ms","162 ms","202 ms","200 ms"],"answer":2,"explanation":"DNS: 2 ms to the local resolver plus 3 × 40 ms for root, TLD and authoritative = 122 ms. HTTP: 1 RTT for the TCP handshake and 1 RTT for request/response = 80 ms. Total 202 ms.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-307","question":"example.com has MX records with preference 10 (mx1.example.com) and 20 (mx2.example.com). How does a sending mail server deliver to user@example.com?","options":["It tries mx1 (preference 10) first and uses mx2 only if mx1 is unreachable","It tries mx2 first because 20 is the higher priority","It sends a copy to both servers at once","It load-balances 2:1 in favour of mx2"],"answer":0,"explanation":"Lower MX preference values are more preferred; equal values would share load. The higher-numbered record is a backup, used when the primary does not accept the connection.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-308","question":"With IEEE 802.3 Manchester coding (0 = high-to-low in mid-bit, 1 = low-to-high), how many signal transitions occur while sending the bits 110010 (count transitions inside the 6 bit times only)?","options":["6","8","9","12"],"answer":1,"explanation":"Every bit has a mid-bit transition (6). An extra boundary transition is needed only between two EQUAL bits (to reset the level). In 1 1 0 0 1 0 the adjacent pairs 11 and 00 are equal, adding 2, for a total of 8.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-309","question":"A 10 Gbps transatlantic fibre link is 6000 km long (signals at 2 × 10⁸ m/s). How much data is in flight in one direction when the link is full, and how much must a sender keep unacknowledged to fill it?","options":["30 MB in one direction; 60 MB unacknowledged","37.5 MB in one direction; 37.5 MB unacknowledged","300 MB in one direction; 600 MB unacknowledged","37.5 MB in one direction; 75 MB unacknowledged"],"answer":3,"explanation":"One-way delay = 6 × 10⁶ / 2 × 10⁸ = 30 ms, so 10¹⁰ × 0.03 = 3 × 10⁸ bits = 37.5 MB fill the fibre. ACKs take another 30 ms, so the window must cover the full RTT: 75 MB. 300 MB forgets to convert bits to bytes.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-310","question":"TCP sequence numbers are 32 bits, and no number may be reused within the maximum segment lifetime of 120 s (assume no PAWS/timestamps). What is the highest sending rate that respects this?","options":["About 286 Mbps","About 36 Mbps","About 143 Mbps","About 573 Mbps"],"answer":0,"explanation":"2³² bytes may be sent per 120 s: 4.29 × 10⁹ × 8 / 120 ≈ 286 Mbps. Above that (e.g. on 1 Gbps links) sequence numbers can wrap within an MSL, which PAWS with timestamps protects against.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-311","question":"When is the TCP window-scale option negotiated, and what happens if only one side includes it?","options":["In any segment, whenever the window grows beyond 64 KB","Only in the SYN; the side that sent it uses scaling anyway","Only in the SYN segments; if either side omits it, neither side uses scaling","During the FIN exchange, to size the final window"],"answer":2,"explanation":"Window scale is a SYN-only option and must be offered by both ends to take effect; each then shifts its own advertised windows by the shift count it announced. It cannot be added mid-connection.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-312","question":"How long does a TCP endpoint stay in TIME_WAIT if MSL = 2 minutes, and which side enters it?","options":["2 minutes, on the side that closes last","4 minutes (2 × MSL), on the side that closes first (sends the first FIN)","4 minutes, on the passive closer","30 seconds, on both sides"],"answer":1,"explanation":"The active closer waits 2 × MSL so that a lost final ACK can be resent and stray old segments die out before the same 4-tuple is reused. The passive closer goes through CLOSE_WAIT and LAST_ACK instead.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-313","question":"Which pair of TCP header fields is used to mark data that the receiving application should get without waiting behind ordinary buffered data (out-of-band style)?","options":["The PSH flag and the window field","The RST flag and the sequence number","The ECE flag and the checksum","The URG flag and the urgent pointer"],"answer":3,"explanation":"URG says the urgent pointer is valid; the pointer marks where the urgent data ends relative to the sequence number. PSH only asks the receiver to deliver buffered data promptly; RST aborts the connection; ECE signals congestion.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-314","question":"A 4 kHz voice channel is digitised with PCM using 256 quantisation levels. What bit rate results when sampling at the Nyquist rate?","options":["32 kbps","8 kbps","64 kbps","2048 kbps"],"answer":2,"explanation":"Nyquist sampling: 2 × 4 kHz = 8000 samples/s. 256 levels need log₂256 = 8 bits per sample: 8000 × 8 = 64 kbps, the standard telephony DS0 rate.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-315","question":"A host joins VLAN 10 and another joins VLAN 20 on the same switch. Host A (VLAN 10) pings host B (VLAN 20). What is required for the ping to succeed?","options":["A router or layer-3 switch routing between the two VLANs","Nothing: hosts on the same physical switch can always reach each other","Only a trunk port between the two hosts","Disabling Spanning Tree on the switch"],"answer":0,"explanation":"Each VLAN is a separate broadcast domain and IP subnet, so traffic between them must be routed. A trunk carries several VLANs between switches but does not route between them.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-316","question":"The RIP route to a network stops being refreshed. With default timers (updates every 30 s, timeout 180 s, garbage collection 120 s), when is the route removed from the table, measured from the last update received?","options":["After 180 s, immediately deleted","After 300 s: marked unreachable (metric 16) at 180 s, then deleted 120 s later","After 90 s, after three missed updates","After 30 s, at the next missed update"],"answer":1,"explanation":"After 180 s without an update the route times out and is advertised with metric 16 (infinity), so neighbours learn it is dead; the garbage-collection timer then removes it 120 s later, 300 s in total.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-317","question":"Which statement about IPv4 'Identification' field is correct?","options":["Each fragment gets a new Identification value so they can be ordered","It is the sequence number used by TCP to reorder segments","Routers increment it at every hop","All fragments of one datagram carry the same value, used to group them for reassembly"],"answer":3,"explanation":"Reassembly groups fragments by (source, destination, protocol, Identification) and orders them by fragment offset. Identification is set by the source and copied unchanged into every fragment.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-318","question":"What is the smallest single CIDR block that contains both 10.13.97.4 and 10.13.110.200?","options":["10.13.96.0/20","10.13.96.0/21","10.13.0.0/16","10.13.97.0/20"],"answer":0,"explanation":"Third octets: 97 = 0110 0001 and 110 = 0110 1110 agree only in their first 4 bits, so the common prefix is 8 + 8 + 4 = 20 bits: 10.13.96.0/20 (10.13.96.0–10.13.111.255). /21 covers only 96–103, and 10.13.97.0/20 is not a valid network address for a /20.","difficulty":"very-hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-319","question":"Which statement about /31 and /32 IPv4 prefixes is correct?","options":["A /31 has 0 usable addresses, so it can never be assigned","A /32 provides 2 usable addresses: network and broadcast","A /31 gives 2 usable addresses on a point-to-point link; a /32 is a host route","A /31 has 2 usable addresses only if broadcast is enabled"],"answer":2,"explanation":"The usual 'minus 2' rule exists because of the network and broadcast addresses; on a point-to-point link neither is needed, so RFC 3021 lets both /31 addresses be used. /32 matches exactly one address, used for loopbacks and host routes.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-320","question":"An ISP is allocated 200.50.32.0/19. How many /24 networks does it contain, and is 200.50.64.0/24 part of it?","options":["32 networks; yes","8 networks; no","64 networks; yes","32 networks; no"],"answer":3,"explanation":"A /19 spans 2⁵ = 32 consecutive /24s. Third octets run from 32 to 63, so 200.50.64.0 is the first address of the NEXT /19 and is not included.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-321","question":"Bulk data flows over 1 Gbps Ethernet in full-size TCP/IPv4 segments (MSS 1460, 20-byte IP and 20-byte TCP headers, no options). Each frame also costs 38 bytes on the wire (14 header + 4 FCS + 8 preamble + 12 inter-frame gap). What is the maximum application-level goodput?","options":["1000 Mbps","About 949 Mbps","About 973 Mbps","About 962 Mbps"],"answer":1,"explanation":"Each 1460 bytes of data costs 1460 + 40 + 38 = 1538 byte-times, so goodput = 1460/1538 ≈ 0.949 of the line rate ≈ 949 Mbps. Counting only the IP/TCP headers gives 973 Mbps; ignoring the preamble and gap gives 962 Mbps.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-322","question":"Which statement about TCP delayed acknowledgements is correct?","options":["A receiver sends exactly one ACK per received segment, always immediately","Delayed ACKs are sent only when the receiver has data to piggyback","An ACK may be held up to 500 ms, but every second full segment must be ACKed","A receiver may delay ACKs indefinitely until the window fills"],"answer":2,"explanation":"RFC 1122/5681 allow delaying an ACK (commonly ~200 ms, never more than 500 ms) to piggyback data or combine ACKs, but every second full-sized segment must be acknowledged. Out-of-order segments should be ACKed immediately (duplicate ACKs).","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-323","question":"A TCP sender uses ECN. A router on the path is congested. What happens?","options":["The router drops the packet and sends ICMP Source Quench","The router marks CE instead of dropping; ECE is echoed and the sender cuts cwnd","The router lowers the TCP window field in passing segments","The receiver reduces its advertised window to zero"],"answer":1,"explanation":"ECN lets routers signal congestion early without loss: the CE codepoint is set in packets whose endpoints negotiated ECN. The receiver reflects it with ECE until the sender confirms its window reduction with CWR. Source Quench is deprecated and routers do not rewrite TCP windows.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-324","question":"Two long-lived TCP Reno flows with the same loss rate share a 100 Mbps bottleneck. Flow 1 has RTT 20 ms, flow 2 has RTT 80 ms. Under the usual model that throughput is inversely proportional to RTT, roughly how is the bandwidth split?","options":["80 Mbps and 20 Mbps","50 Mbps and 50 Mbps","20 Mbps and 80 Mbps","67 Mbps and 33 Mbps"],"answer":0,"explanation":"Reno adds one MSS per RTT, so a flow with a 4× shorter RTT grows 4× faster and recovers 4× faster: shares are proportional to 1/RTT, i.e. 1/20 : 1/80 = 4 : 1 → 80 and 20 Mbps. This RTT unfairness is one motivation for CUBIC.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-325","question":"Selective Repeat is (wrongly) run with 3-bit sequence numbers and window size 5. The sender sends frames 0–4; all arrive and the receiver's window moves to 5, 6, 7, 0, 1, but every ACK is lost. The sender times out and retransmits. Which retransmitted frames would the receiver wrongly accept as NEW data?","options":["Only frame 0","Frames 0 to 4","None, because they are duplicates","Frames 0 and 1"],"answer":3,"explanation":"The receiver now expects 5, 6, 7, 0, 1; old frames 0 and 1 carry numbers that fall inside this window, so they are buffered as if they were the next 0 and 1. With window ≤ 2³/2 = 4 the windows would not overlap.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-326","question":"Stop-and-wait sends 1000-bit frames at 1 Mbps with one-way propagation delay 2 ms (ACKs negligible and error-free). Bits are corrupted independently with bit-error rate 10⁻⁴, and any corrupted frame is resent after a timeout of one RTT. What is the effective utilisation?","options":["20.0%","18.0%","18.1%","30.2%"],"answer":2,"explanation":"P(frame survives) = (1 − 10⁻⁴)¹⁰⁰⁰ ≈ 0.9048. Each attempt takes 1 + 4 = 5 ms, and the expected attempts per frame are 1/0.9048, so utilisation = 0.2 × 0.9048 ≈ 18.1%. Using 1 − 1000 × BER = 0.9 is only an approximation.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-327","question":"Each 8-bit byte is sent with one even-parity bit (9 bits in total), and bits flip independently with probability 10⁻³. Approximately what is the probability that a block contains errors but passes the parity check?","options":["About 3.6e-05","About 9.0e-03","About 1.8e-05","About 1.0e-06"],"answer":0,"explanation":"Parity misses every even number of errors; the dominant term is exactly 2 flips: C(9, 2) p² (1 − p)⁷ ≈ 36 × 10⁻⁶ ≈ 3.6e-05. 9 × 10⁻³ is roughly the probability of a (detected) single error.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-328","question":"What is the Hamming distance between the codewords 10110110 and 11010011?","options":["3","4","5","8"],"answer":1,"explanation":"XOR the words: 10110110 ⊕ 11010011 = 01100101, which has 4 ones, so they differ in 4 positions.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-329","question":"A CRC uses the generator polynomial x⁵ + x² + 1. What bit string is transmitted for the data 1001101?","options":["10011010011","100110110110","100110100000","100110111011"],"answer":3,"explanation":"x⁵ + x² + 1 is 100101 (coefficients of x⁵ … x⁰), so 5 check bits are appended. Dividing 100110100000 by 100101 modulo 2 leaves 11011. Writing the generator as 10101 (dropping the x⁴ place) is the common slip.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-330","question":"In the classic Ethernet contention model, each of N = 4 ready stations transmits in a contention slot with probability 1/N. What is the probability A that a slot is acquired (exactly one station transmits), and the mean number of slots until success?","options":["A = 0.250; 4.00 slots","A ≈ 0.422; about 1.37 slots","A ≈ 0.422; about 2.37 slots","A ≈ 0.368; about 2.72 slots"],"answer":2,"explanation":"A = N·(1/N)·(1 − 1/N)^(N−1) = (3/4)³ ≈ 0.422. Slots until the first success are geometric with mean 1/A ≈ 2.37 (the number of WASTED slots is 1/A − 1 ≈ 1.37). As N grows, A → 1/e.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-331","question":"In 802.11, why is SIFS shorter than DIFS?","options":["So that an ACK always goes out before another station can start a new frame","So that new data frames get priority over ACKs","Because SIFS is used only for beacon frames","So that stations can detect collisions while transmitting"],"answer":0,"explanation":"After a data frame, the receiver waits only SIFS before its ACK, while others must sense the medium idle for the longer DIFS, so the ACK always wins. Wi-Fi stations cannot detect collisions, which is why positive ACKs are needed at all.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-332","question":"Which comparison of link-state and distance-vector routing is correct?","options":["Distance-vector routers each know the full topology","Link-state floods link data to all routers; distance-vector talks only to neighbours","Link-state routers exchange information only with direct neighbours and never flood","Link-state routing suffers from count-to-infinity, distance-vector does not"],"answer":1,"explanation":"LS gives every router the whole graph (more messages, O(N·E), but fast, loop-free convergence). DV is distributed Bellman–Ford with neighbour exchanges and can count to infinity after failures.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-333","question":"Inside an AS, router R learns the same external prefix from two border routers via iBGP with identical BGP attributes. R's IGP cost to border router X is 5 and to Y is 8. Which exit does R choose under hot-potato routing, and why?","options":["Y, because it keeps the traffic inside the AS longer","Both, splitting traffic by cost ratio 8:5","Whichever border router has the lower router ID","X, because its IGP cost is lower, so traffic leaves the AS soonest"],"answer":3,"explanation":"When earlier BGP attributes tie, the decision process prefers the lowest IGP metric to the next hop: get the packet out of your own network quickly. Router ID is only a later tie-breaker.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-334","question":"Which statement about multicast forwarding is correct?","options":["A router accepts a packet only on its interface toward the SOURCE (RPF check)","Routers forward multicast only toward the destination address's unicast route","Hosts use ARP to join multicast groups","Multicast packets are sent to every host in the Internet and filtered by NICs"],"answer":0,"explanation":"Multicast has no single destination, so loops are avoided by RPF: a packet is accepted only on the interface on the shortest path back to its source, then copied to downstream interfaces with members. Hosts join groups with IGMP (MLD in IPv6).","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-335","question":"Two hosts, each behind a different NAT, want to set up a direct UDP connection for a video call. Why are STUN/TURN servers used?","options":["STUN assigns public IP addresses to hosts behind NAT","TURN converts the UDP stream to TCP so NAT can forward it","STUN reveals each public IP:port for hole punching; TURN relays if that fails","They replace DNS so the hosts can find each other's private addresses"],"answer":2,"explanation":"NATs drop unsolicited inbound packets, and hosts only know their private addresses. STUN reveals the external mapping; both sides then send to each other's public endpoint to open mappings. Symmetric NATs often defeat this, so TURN relays the media.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-336","question":"A recursive resolver starts with an empty cache. Client 1 resolves a.example.com, then client 2 resolves b.example.com. Counting only queries the resolver sends to root, TLD and authoritative servers, how many are sent in total?","options":["6","4","3","5"],"answer":1,"explanation":"First lookup: root → .com TLD → example.com authoritative (3 queries); the referrals (NS and glue records) are cached. The second lookup goes straight to the example.com server: 1 more query, 4 in total.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-337","question":"An HTTP/1.1 server streams a response whose final size is unknown when it starts sending. How does the client know where the body ends on a persistent connection?","options":["The server closes the TCP connection after every response","The client waits for a 2-second pause in the data","The server sends Content-Length: 0 and then the body","The server uses Transfer-Encoding: chunked, ending with a zero-length chunk"],"answer":3,"explanation":"Without Content-Length, chunked encoding prefixes each chunk with its size and terminates with a 0-size chunk, so the connection can be reused. Closing the connection also delimits a body, but then it is no longer persistent.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-338","question":"Which Cache-Control directive lets a cache store the response but requires it to revalidate with the origin server before every reuse?","options":["no-store","no-cache","max-age=0, immutable","public"],"answer":1,"explanation":"Despite its name, no-cache permits storing but forbids using the copy without a successful revalidation (e.g. a conditional GET returning 304). no-store forbids storing at all; public merely allows shared caches to store it.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-339","question":"Which statement about mail submission and retrieval is correct?","options":["Clients submit mail on port 587 with authentication; servers relay on port 25","POP3 keeps all mail on the server and synchronises folders across devices","IMAP downloads and deletes messages from the server by default","SMTP is used by clients to fetch new mail from their mailbox"],"answer":0,"explanation":"Port 587 (submission) requires authentication; port 25 is for server-to-server relay. IMAP keeps mail and folders on the server; POP3 typically downloads (and may delete). SMTP only pushes mail.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-340","question":"Using the TCP throughput model T ≈ 1.22 × MSS / (RTT × √p), what throughput can a Reno flow reach with MSS = 1460 bytes, RTT = 100 ms and loss rate p = 10⁻⁴?","options":["About 1.78 Mbps","About 1425 Mbps","About 1.42 Mbps","About 14.2 Mbps"],"answer":3,"explanation":"√(10⁻⁴) = 0.01, so T ≈ 1.22 × 11,680 bits / (0.1 × 0.01) ≈ 14.2 Mbps. To double it you would need four times lower loss, which is why long fat pipes need very low loss rates.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-341","question":"A 1000-byte packet is sent at 10 Mbps over a 100 km link (signals at 2 × 10⁸ m/s). At the moment the LAST bit leaves the sender, where is the FIRST bit?","options":["It is halfway along the link","It is still on the link, 0.5 ms from the receiver","It has already reached the receiver, 0.3 ms earlier","It reaches the receiver at exactly that moment"],"answer":2,"explanation":"Transmission takes 8000 / 10⁷ = 0.8 ms while propagation takes 10⁵ / 2 × 10⁸ = 0.5 ms. Since Tt > Tp, the first bit arrived at 0.5 ms, 0.3 ms before the last bit is even sent.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-342","question":"A 16-QAM modem signals at 3000 baud. What is its bit rate?","options":["48 kbps","3 kbps","6 kbps","12 kbps"],"answer":3,"explanation":"16 constellation points carry log₂16 = 4 bits per symbol: 3000 × 4 = 12,000 bps. 48 kbps multiplies by 16 instead of 4.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-343","question":"Diffie–Hellman uses p = 29 and g = 2. Alice's secret is a = 5 and Bob's is b = 11. What values do they send each other, and what shared key results?","options":["Alice sends 3, Bob sends 18, key 25","Alice sends 10, Bob sends 22, key 23","Alice sends 3, Bob sends 18, key 15","Alice sends 3, Bob sends 18, key 19"],"answer":2,"explanation":"A = 2⁵ mod 29 = 3, B = 2¹¹ mod 29 = 18. Alice computes B^a mod p and Bob A^b mod p, both equal to 2^(ab) = 2⁵⁵ mod 29 = 15. Multiplying the public values or using 2^(a+b) are common errors.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-344","question":"Textbook RSA uses p = 5, q = 11 and e = 3. What is the private exponent d, and what ciphertext does m = 9 produce?","options":["d = 27, c = 14","d = 13, c = 14","d = 27, c = 4","d = 7, c = 27"],"answer":0,"explanation":"n = 55 and φ(n) = 4 × 10 = 40. d is the inverse of 3 mod 40: 3 × 27 = 81 ≡ 1, so d = 27. c = 9³ mod 55 = 729 mod 55 = 14. Decryption 14²⁷ mod 55 returns 9.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-345","question":"A company places its public web and mail servers in a DMZ. Which arrangement matches this design?","options":["Public servers on the internal LAN, protected only by host antivirus","Public servers in a separate segment, firewalled from both Internet and LAN","Public servers outside any firewall, with the internal LAN behind one","Internal LAN in the DMZ and public servers behind two firewalls"],"answer":1,"explanation":"A DMZ is a separate segment reachable from the Internet on the permitted service ports, while traffic from the DMZ into the internal network is tightly restricted. This limits the damage if an exposed server is compromised.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-346","question":"How many of the following statements about QUIC are correct?\n1. It runs over UDP and implements reliability and congestion control itself.\n2. It integrates TLS 1.3, so a new connection usually needs one RTT before sending application data.\n3. A lost packet stalls all streams of the connection.\n4. Connection IDs let a connection survive a change of the client's IP address.","options":["4","3","2","1"],"answer":1,"explanation":"1, 2 and 4 are true. Statement 3 is false: QUIC streams are independent at the transport layer, so a loss delays only the streams whose data was in that packet, avoiding TCP's head-of-line blocking.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-347","question":"Which statement about TLS certificates is correct?","options":["A certificate is trusted if it is signed with the server's own private key","The certificate encrypts all application data directly","It is trusted if its signature chain reaches a trusted root and name/dates match","A self-signed certificate is trusted by default because it cannot be forged"],"answer":2,"explanation":"Each certificate in the chain is signed by the next CA's private key, ending at a pre-installed root. The client also checks the hostname (SAN), validity dates and revocation. Self-signed certificates are not trusted unless explicitly installed.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-348","question":"Which pair of primitives guarantees integrity and authenticity of a message between two parties that share a secret key, without providing non-repudiation?","options":["A MAC such as HMAC-SHA256","A plain SHA-256 hash","A digital signature with RSA","Encryption with AES in ECB mode"],"answer":0,"explanation":"A MAC needs the shared key to create or verify a tag, so it proves the message came from a key holder and was not changed; but either party could have made it, so no non-repudiation. A plain hash can be recomputed by an attacker, and signatures do provide non-repudiation.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-349","question":"A switch network accidentally has a loop and Spanning Tree is disabled. A host sends one ARP broadcast. What happens?","options":["The frame is dropped after 16 hops","The second switch detects the duplicate and discards it","Only one extra copy is created and then the loop stops","Copies circulate endlessly, since frames have no TTL: a broadcast storm"],"answer":3,"explanation":"Layer-2 frames have no hop limit, so each switch floods every copy out of all other ports, multiplying broadcasts until links saturate; MAC entries also flap between ports. STP exists to block redundant links.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-350","question":"What does a route to 0.0.0.0/0 in a routing table mean?","options":["It matches no destination and is ignored","It is the default route, used when no more specific entry matches","It routes only packets addressed to 0.0.0.0","It is the loopback route for the router itself"],"answer":1,"explanation":"A /0 prefix has no fixed bits, so every address matches it, but longest-prefix matching chooses it only when nothing longer matches, which is exactly the 'gateway of last resort'.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-351","question":"Root DNS servers are reachable at only 13 named addresses, yet there are well over a thousand server instances worldwide. How?","options":["Each address is announced from many sites (anycast); BGP picks a nearby one","Each address is shared by round-robin DNS among instances","Resolvers pick an instance by multicast","NAT translates the 13 addresses to different servers"],"answer":0,"explanation":"With anycast many physical servers advertise the same prefix; BGP sends each client to the 'closest' one in routing terms. This spreads load and absorbs DDoS traffic while keeping the address list fixed.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-352","question":"A router's buffer holds packets for an output link with arrival rate a = 900 packets/s, packet size 1250 bytes and link rate 8 Mbps. What is the traffic intensity, and what happens to queueing delay?","options":["La/R = 0.9, so the delay stays small","La/R = 1.125, but delay stays bounded because packets are equal-sized","La/R = 0.1125, so the link is mostly idle","La/R = 1.125 > 1, so the queue and the delay grow without bound"],"answer":3,"explanation":"La/R = 1250 × 8 × 900 / 8 × 10⁶ = 9 × 10⁶ / 8 × 10⁶ = 1.125. Bits arrive faster than they can be sent, so the queue grows on average no matter how packets are spaced; a finite buffer then drops packets.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-353","question":"Two hosts run TCP over a path whose MTU is 1500 at both ends but 1400 on an intermediate link, and an intermediate firewall blocks all ICMP. Small requests work but large transfers hang. What is the most likely cause?","options":["The TCP window is too small for large transfers","The receiver's MSS option is ignored by the sender","A path-MTU black hole: big DF packets die and the ICMP error is filtered","UDP traffic is being blocked by the firewall"],"answer":2,"explanation":"TCP sets DF and relies on ICMP type 3 code 4 to lower its segment size. With ICMP filtered, full-size segments vanish silently and retransmissions fail the same way. MSS clamping on the router or allowing that ICMP type fixes it.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-354","question":"A DHCP server hands out addresses from 192.168.10.0/24, excluding .1 (gateway) and .2–.10 (static servers). At most how many clients can hold leases at once?","options":["254","245","243","244"],"answer":3,"explanation":"A /24 has 254 usable host addresses (.1–.254). Removing .1 and .2–.10 (10 addresses) leaves 244 for dynamic leases. Counting .0 or .255 as usable is the usual slip.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-355","question":"Which statement correctly describes how a learning switch updates its MAC table and forwards a frame?","options":["It records the DESTINATION MAC with the incoming port","It forwards by source MAC and learns destinations from replies","It learns the SOURCE MAC on the incoming port and forwards by DESTINATION MAC","It floods every frame until its table is full"],"answer":2,"explanation":"Learning uses source addresses (the sender is reachable via the arrival port). Forwarding uses the destination: if it maps to the incoming port the frame is filtered, if known it goes out one port, and if unknown or broadcast it is flooded.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-356","question":"200.1.1.0/24 is subnetted with mask 255.255.255.224, and subnets are numbered from 0 (subnet zero is allowed). What is the broadcast address of subnet number 4, and its last usable host?","options":["200.1.1.127 and 200.1.1.126","200.1.1.191 and 200.1.1.190","200.1.1.159 and 200.1.1.129","200.1.1.159 and 200.1.1.158"],"answer":3,"explanation":"/27 blocks are 32 addresses: subnet k spans 32k … 32k + 31. Subnet 4 is .128–.159, so the broadcast is .159 and the last host .158. Counting from 1 instead gives subnet .96–.127.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-357","question":"10.0.0.0/8 is entirely divided into /27 subnets. How many addresses in the block are subnet broadcast addresses?","options":["134,217,728","524,288","32","1,048,576"],"answer":1,"explanation":"Each /27 has exactly one broadcast address, and a /8 holds 2^(27 − 8) = 2¹⁹ = 524,288 subnets, so 524,288 broadcast addresses (and as many network addresses).","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-358","question":"An admin must make sure two routed subnets do not overlap. Which pair DOES overlap?","options":["172.16.32.0/21 and 172.16.40.0/22","172.16.48.0/20 and 172.16.64.0/22","172.16.40.0/21 and 172.16.44.0/22","172.16.16.0/22 and 172.16.20.0/22"],"answer":2,"explanation":"172.16.40.0/21 spans third octets 40–47, which includes 44–47 (172.16.44.0/22). The others are adjacent but disjoint: 32–39 vs 40–43, 48–63 vs 64–67, 16–19 vs 20–23.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-359","question":"A single flat subnet must hold 3000 hosts. What is the longest prefix that works?","options":["/20","/21","/19","/22"],"answer":0,"explanation":"3000 + 2 addresses need 12 host bits (2¹² = 4096; 2¹¹ = 2048 is too small), so the prefix is /20, giving 4094 usable addresses.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-360","question":"A router decrements TTL from 0x3F to 0x3E in a packet whose header checksum is 0xB1E6 (the 16-bit word holding TTL and protocol changes from 0x3F11 to 0x3E11). Using the incremental update HC' = ~(~HC + ~m + m') in ones'-complement arithmetic, what is the new checksum?","options":["0xB0E6","0xB2E6","0xB1E6","0xB1E7"],"answer":1,"explanation":"The covered sum drops by 0x0100, so its complement (the checksum) rises by 0x0100: 0xB1E6 → 0xB2E6. Subtracting 0x100 from the checksum moves it the wrong way; leaving it unchanged would make the next hop discard the packet.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-361","question":"Why does the IPv6 base header have no header checksum?","options":["Because IPv6 packets are always encrypted","Because IPv6 headers never change in transit","Link CRCs and transport checksums already catch errors, and it avoids per-hop recomputation","Because routers in IPv6 recompute a CRC instead"],"answer":2,"explanation":"An IPv4 router must recompute the checksum at every hop because TTL changes. IPv6 removes this work and relies on link-layer CRCs plus the now-mandatory UDP checksum and TCP's checksum.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-362","question":"A TCP receiver sends ACK = 2000 with a window of 1000 bytes. The sender has already sent up to byte 2499. What is the highest byte number it may send, and how many more NEW bytes can go now?","options":["Up to byte 2999; 500 more bytes","Up to byte 2999; 1000 more bytes","Up to byte 3499; 1000 more bytes","Up to byte 2499; none"],"answer":0,"explanation":"The window is counted from the acknowledged point: bytes 2000–2999 are allowed. Bytes 2000–2499 are already in flight, so 500 new bytes (2500–2999) may be sent.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-363","question":"A TCP connection's RTO is 1 s when a segment's first transmission is lost, and its retransmissions are lost twice more. Under exponential backoff, how long does the sender wait before the fourth transmission, and how long has passed since the first one?","options":["8 s; 15 s in total","3 s; 6 s in total","4 s; 4 s in total","4 s; 7 s in total"],"answer":3,"explanation":"Each timeout doubles the RTO: the 2nd transmission goes at t = 1 s, the 3rd at t = 1 + 2 = 3 s and the 4th at t = 3 + 4 = 7 s. So the wait before the 4th is 4 s and 7 s have passed; 8 s would be the wait before a 5th attempt.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-364","question":"A Go-Back-N receiver expecting frame 4 receives frames 5 and 6 (frame 4 was lost). What does it do with them?","options":["It buffers 5 and 6 and ACKs them individually","It delivers 5 and 6 and then waits for 4","It discards 5 and 6 and re-sends the ACK for frame 3 each time","It sends a NAK for 5 and 6"],"answer":2,"explanation":"A Go-Back-N receiver has a window of size 1: it accepts only the next expected frame and repeats the cumulative ACK otherwise. The sender will later retransmit 4, 5, 6 and so on.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-365","question":"A CRC uses G(x) = x³ + x² + x + 1 = (x + 1)(x² + 1). Which error pattern E(x) would go undetected (bits from the highest power down)?","options":["1011","100001","1110001","1100110"],"answer":3,"explanation":"An error is undetected exactly when G divides E. Dividing each pattern by 1111 modulo 2, only 1100110 leaves remainder 000. Note that (x + 1) | G guarantees every ODD-weight error is caught, so the undetected pattern must have even weight.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-366","question":"A single-error-correcting Hamming code uses 5 check bits. What is the maximum number of data bits it can protect, and what is its code rate?","options":["26 data bits; rate 26/31","31 data bits; rate 31/36","25 data bits; rate 25/30","16 data bits; rate 16/21"],"answer":0,"explanation":"The check bits must label every single-bit error plus 'no error': 2ʳ ≥ m + r + 1, so m ≤ 32 − 6 = 26. That is the (31, 26) code with rate 26/31 ≈ 0.84; larger codes have higher rates.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-367","question":"On a CSMA/CD bus with end-to-end propagation delay τ, station A starts sending at t = 0 and station B (at the far end) starts just before A's signal reaches it. When does A detect the collision, in the worst case?","options":["At t = τ","Just before t = 2τ","At t = τ/2","At t = 4τ"],"answer":1,"explanation":"B's transmission starts at almost τ, and its signal needs another τ to travel back, so A notices the collision at nearly 2τ. That is why the minimum frame time must be at least 2τ: A must still be transmitting when the collision news arrives.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-368","question":"Which pair of ICMPv6 messages replaces ARP in IPv6 address resolution?","options":["Neighbor Solicitation and Neighbor Advertisement","Router Solicitation and Router Advertisement","Echo Request and Echo Reply","ARP Request and ARP Reply carried in IPv6"],"answer":0,"explanation":"Neighbor Discovery uses NS (to the target's solicited-node multicast group) and NA (the reply with the link-layer address). RS/RA are for router discovery and SLAAC prefixes; IPv6 has no ARP or broadcast.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-369","question":"Which statement about IPv6 address autoconfiguration is correct?","options":["SLAAC requires a DHCPv6 server to assign each address","Router Advertisements carry a full address for each host","IPv6 hosts must be configured manually unless DHCPv4 is present","With SLAAC a host combines an advertised prefix with its own interface ID"],"answer":3,"explanation":"Routers advertise on-link /64 prefixes; hosts append an EUI-64 or random interface ID and run duplicate address detection. DHCPv6 can be added (stateful or for DNS options), but SLAAC itself is stateless.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-370","question":"6to4 tunnelling builds a site's IPv6 prefix from 2002::/16 followed by its 32-bit public IPv4 address. What /48 prefix does a site with IPv4 address 192.0.2.4 get?","options":["2002:192:0:2:4::/48","2002:c000:0204::/64","2002:c000:204::/48","2002:0402:00c0::/48"],"answer":2,"explanation":"192.0.2.4 in hex is c0.00.02.04, so the next 32 bits after 2002 are c000:0204, giving 2002:c000:204::/48. Writing the decimal octets as hex groups or reversing the byte order are the usual mistakes.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-371","question":"How is the IPv4 address 192.0.2.128 written as an IPv4-mapped IPv6 address in hexadecimal form?","options":["::ffff:192:2128","::ffff:c000:280","::c000:280","::ffff:0:c000:280"],"answer":1,"explanation":"IPv4-mapped addresses are ::ffff:0:0/96 plus the 32-bit IPv4 address. 192.0.2.128 = c0 00 02 80 → c000:280, so the address is ::ffff:c000:280 (also written ::ffff:192.0.2.128). '::c000:280' is the deprecated IPv4-compatible form.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-372","question":"Why must iBGP speakers inside an AS be fully meshed (or use route reflectors/confederations)?","options":["Because iBGP runs over UDP and needs direct links","Because OSPF cannot carry any routes inside an AS","iBGP-learned routes are not passed to other iBGP peers, since AS_PATH cannot stop loops inside an AS","Because eBGP routes are discarded at the AS border"],"answer":2,"explanation":"Inside an AS the AS_PATH gives no loop protection, so the rule is: iBGP-learned routes are not passed to other iBGP peers. Every border-learned route must therefore reach each router directly, which a full mesh or route reflectors provide.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-373","question":"What does an MPLS label-switching router use to forward a labelled packet?","options":["The longest-prefix match on the destination IP address","The incoming label, swapped for an outgoing label and interface","The destination MAC address","The TCP port numbers"],"answer":1,"explanation":"MPLS replaces per-hop IP lookups with an exact-match label lookup; the ingress router classifies the packet once and pushes a label, core routers swap labels, and the egress pops it. This enables traffic engineering and VPNs.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-374","question":"In DiffServ QoS, where is a packet's traffic class marked, and how many bits are used?","options":["In the TCP header as a 3-bit priority","In the IPv4 flags field as a 2-bit class","In the Ethernet type field as an 8-bit code","In the IPv4 ToS / IPv6 Traffic Class byte, as a 6-bit DSCP"],"answer":3,"explanation":"DiffServ redefined the old ToS byte: 6 bits of DSCP (64 code points, e.g. EF = 46 for voice) plus 2 bits used by ECN. Routers apply per-hop behaviours based on the DSCP; 802.1p uses a separate 3-bit field in the VLAN tag.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-375","question":"Which cookie attribute stops JavaScript running in the page from reading the cookie through document.cookie?","options":["HttpOnly","Secure","SameSite=Strict","Path=/"],"answer":0,"explanation":"HttpOnly hides the cookie from scripts, limiting session theft by XSS. Secure sends it only over HTTPS, SameSite restricts cross-site sending (CSRF defence), and Path limits which URLs receive it.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-376","question":"A page at https://app.example.com uses fetch() to send a PUT request with a JSON body to https://api.example.com. What happens first?","options":["An OPTIONS preflight; the PUT follows only if CORS headers allow it","The browser sends the PUT immediately and blocks only the response","The server must reply with 301 before the PUT","Nothing special happens because both are subdomains of example.com"],"answer":0,"explanation":"Different subdomains are different origins. PUT with a JSON content type is not a 'simple' request, so the browser asks permission with OPTIONS (Access-Control-Request-Method) and proceeds only if Access-Control-Allow-Origin/Methods permit it.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-377","question":"How does a WebSocket connection start?","options":["As a separate UDP flow on port 81","With an HTTP 200 response followed by a new TCP connection","With a DNS SRV lookup and a TLS-only handshake","As an HTTP Upgrade request answered by 101 Switching Protocols"],"answer":3,"explanation":"The opening handshake reuses HTTP so it passes through ports 80/443 and proxies; the server proves it understood by returning Sec-WebSocket-Accept with 101. After that the connection is full-duplex message framing.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-378","question":"A REST API creates a resource in response to a POST. Which response is most appropriate?","options":["200 OK with no body","201 Created with a Location header pointing to the new resource","204 No Content with the new ID in the body","302 Found to the collection URL"],"answer":1,"explanation":"201 tells the client that a new resource exists and Location gives its URL. 204 means success with no body at all, and redirects (3xx) are for moving the client elsewhere, not for reporting creation.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-379","question":"Which application protocols use UDP by default? SNMP, NTP, SSH, DHCP","options":["SNMP, SSH and DHCP","NTP and SSH only","SNMP, NTP and DHCP","All four"],"answer":2,"explanation":"SNMP (161/162), NTP (123) and DHCP (67/68) use UDP for small request/response exchanges or broadcasts. SSH (22) needs a reliable byte stream and runs over TCP.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-380","question":"Uncompressed 1080p video (1920 × 1080 pixels, 24 bits per pixel, 30 frames/s) is sent over a network. What bit rate does it need?","options":["About 1.49 Gbps","About 187 Mbps","About 49.8 Mbps","About 2.99 Gbps"],"answer":0,"explanation":"1920 × 1080 × 24 = 49.8 Mbits per frame; × 30 = 1.49 Gbps. 187 Mbps is the same figure in megaBYTES per second; codecs such as H.264 reduce it by roughly 100–300×.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-381","question":"A 1 Gbps switch forwards a 1500-byte frame. A store-and-forward switch waits for the whole frame; a cut-through switch starts forwarding once it has read the 14-byte Ethernet header. Ignoring lookup time, roughly how much latency does each add?","options":["1.5 µs vs 0.112 µs","12 µs vs 12 µs","12 µs vs 0.112 µs","1.5 µs vs 0.014 µs"],"answer":2,"explanation":"Store-and-forward must receive 12,000 bits = 12 µs before transmitting; cut-through needs only 112 bits ≈ 0.112 µs. The price is that cut-through forwards corrupted frames, since the FCS arrives last.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-382","question":"A signal goes from a ground station up to a geostationary satellite (altitude about 35,786 km) and down to another ground station, travelling at 3 × 10⁸ m/s. Taking both ground stations directly below the satellite, roughly what is the one-way delay?","options":["About 119 ms","About 477 ms","About 24 ms","About 239 ms"],"answer":3,"explanation":"Up plus down is 2 × 35,786 km ≈ 71,572 km; at 3 × 10⁵ km/s that is ≈ 239 ms (more for stations away from the sub-satellite point). A request/response round trip therefore takes about half a second.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-383","question":"On a 1 Gbps path with RTT 10 ms, what throughput can one TCP connection reach with a 65,535-byte window, and with the same window scaled by 2⁴?","options":["About 52.4 Mbps and 1000.0 Mbps","About 52.4 Mbps and 838.8 Mbps","About 6.6 Mbps and 104.9 Mbps","About 26.2 Mbps and 419.4 Mbps"],"answer":1,"explanation":"Window-limited throughput = W / RTT: 524,280 bits / 0.01 s ≈ 52.4 Mbps. Scaling by 16 gives ≈ 838.8 Mbps, still below 1 Gbps; full speed needs W ≥ 1.25 MB (shift ≥ 5).","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-384","question":"The IPv4 fragment-offset field is 13 bits and counts 8-byte units. What is the largest offset (in bytes) a fragment can have, and why must fragment payloads (except the last) be multiples of 8?","options":["8,191 bytes; because the field is 13 bits","65,528 bytes; because offsets can only express multiples of 8 bytes","65,535 bytes; because the total length is 16 bits","65,528 bytes; because Ethernet frames are multiples of 8 bytes"],"answer":1,"explanation":"The maximum offset value is 2¹³ − 1 = 8191 units = 65,528 bytes. Since each later fragment's start must be expressible as offset × 8, every non-final fragment must carry a multiple of 8 data bytes.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-385","question":"How many of the following header-field facts are correct?\n1. IPv4 TTL is 8 bits.\n2. IPv4 Identification is 16 bits.\n3. IPv6 Flow Label is 20 bits.\n4. IPv6 Hop Limit is 16 bits.\n5. IPv4 Protocol / IPv6 Next Header are 8 bits.","options":["5","3","4","2"],"answer":2,"explanation":"1, 2, 3 and 5 are correct. The IPv6 Hop Limit is 8 bits, the same size as the IPv4 TTL it replaces; the only 16-bit field in the IPv6 base header is Payload Length.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-386","question":"The IPv4 Record Route option asks each router to append its address. At most how many router addresses can it hold, and why?","options":["9, because 40 option bytes minus 3 overhead bytes fit nine addresses","10, because 40 / 4 = 10","15, because HLEN can reach 15 words","255, because the length field is 8 bits"],"answer":0,"explanation":"The header can be at most 60 bytes, leaving 40 for options. Record Route uses type, length and pointer bytes (3) plus 4 bytes per address: 9 addresses fit, 10 would need 43 bytes. This limit is why traceroute replaced it.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-387","question":"How many of these situations should trigger an ICMP error message?\n1. A router drops a datagram whose TTL reached 0.\n2. A host receives a UDP datagram for a closed port.\n3. A router drops an ICMP Destination Unreachable message because of congestion.\n4. A router discards a non-first fragment of a datagram.\n5. A router drops a datagram sent to a broadcast address.","options":["3","4","5","2"],"answer":3,"explanation":"1 (Time Exceeded) and 2 (Port Unreachable) do. ICMP errors are never sent about ICMP error messages (3), about fragments other than the first (4), or about broadcast/multicast datagrams (5), to avoid storms of error messages.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-388","question":"traceroute sends 3 probes per hop and stops after at most 30 hops. If the destination is 12 hops away and every probe is answered, how many probes are sent?","options":["90","12","36","33"],"answer":2,"explanation":"Probes go out for TTL = 1, 2, …, 12 (3 each) and the 12th set reaches the destination, which answers with Port Unreachable or Echo Reply, ending the trace: 12 × 3 = 36. 90 would be the maximum with no destination reply.","difficulty":"moderate","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-389","question":"In a Smurf attack the attacker sends ICMP Echo Requests with the victim's spoofed source address. Where are they sent, and what common defence stops the amplification?","options":["To a network's directed broadcast address; routers should not forward directed broadcasts","To the victim's own address; firewalls block all ICMP","To a DNS resolver; rate-limit DNS responses","To a multicast group; disable IGMP"],"answer":0,"explanation":"Every host on the target subnet answers the broadcast echo, flooding the spoofed victim with replies. Disabling directed-broadcast forwarding (the default since RFC 2644) and ingress filtering against spoofing prevent it.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-390","question":"Why are open DNS resolvers attractive for DDoS amplification attacks?","options":["DNS uses TCP, so each query opens many connections","DNS servers forward every query to the victim's ISP","DNS responses are always encrypted and cannot be filtered","Small spoofed UDP queries trigger much larger responses aimed at the victim"],"answer":3,"explanation":"UDP has no handshake, so source addresses can be forged; queries such as ANY or DNSSEC records can produce responses tens of times larger. Response-rate limiting, closing open resolvers and BCP 38 ingress filtering reduce the risk.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-391","question":"A client's SYN gets no SYN-ACK (the SYN-ACK is lost). What does the client do?","options":["It sends an ACK anyway to complete the handshake","It retransmits the SYN after a timeout, doubling the timeout on each failure","It immediately opens a new connection with a different port","It waits for the server's keepalive probe"],"answer":1,"explanation":"Without a SYN-ACK the client has no server sequence number to acknowledge. The SYN is retransmitted with exponential backoff; the server, which did send a SYN-ACK, will retransmit it too, and either copy can complete the handshake.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-392","question":"A server restarts and its bind() to port 8080 fails with 'address already in use' because old connections are in TIME_WAIT. Which socket option is designed for this?","options":["SO_REUSEADDR","TCP_NODELAY","SO_KEEPALIVE","SO_LINGER with a timeout of 120 s"],"answer":0,"explanation":"TIME_WAIT entries keep the 4-tuples of old connections; new connections use different client ports, so binding the listener again is safe. TCP_NODELAY disables Nagle, SO_KEEPALIVE probes idle peers, and SO_LINGER controls close behaviour.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-393","question":"A Selective Repeat receiver uses a window of 8 frames. How much buffer space (in frames) must it reserve, and why?","options":["1 frame, like Go-Back-N","16 frames, twice the window","8 frames, a whole window of out-of-order frames","Only as many as the sequence space minus the window"],"answer":2,"explanation":"Selective Repeat accepts any frame inside its window and must keep it until the gap before it is filled, so the buffer equals the receive window. Go-Back-N needs only one frame of buffering.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-394","question":"What is the code rate of the (15, 11) Hamming code, and what fraction of transmitted bits is redundancy?","options":["Rate 4/15 ≈ 0.267; about 73.3% redundancy","Rate 11/4 = 2.75; about 36% redundancy","Rate 15/11 ≈ 1.36; about 36% redundancy","Rate 11/15 ≈ 0.733; about 26.7% redundancy"],"answer":3,"explanation":"Code rate = data bits / codeword bits = 11/15. The 4 check bits are 4/15 ≈ 26.7% of what is sent. Rate is always ≤ 1.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-395","question":"How many of the following statements about Ethernet switches versus routers are correct?\n1. A switch forwards using MAC addresses; a router forwards using IP addresses.\n2. A router decrements TTL; a layer-2 switch does not.\n3. A switch rewrites the source MAC address of every frame it forwards.\n4. A router separates broadcast domains; a switch (without VLANs) does not.","options":["4","3","2","1"],"answer":1,"explanation":"1, 2 and 4 are true. Statement 3 is false: a switch forwards frames unchanged (it is transparent); it is the ROUTER that writes a new Ethernet header, with its own interface MAC as the source, on each hop.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-396","question":"An organisation advertises 198.18.0.0/22 to its ISP, but internally uses only 198.18.0.0/23. Traffic for 198.18.3.10 arrives. With no route for it internally except a default route pointing back to the ISP, what happens?","options":["The organisation's router drops it immediately with no further action","The ISP rejects the packet because it is outside the /23","The packet is delivered to the nearest host in 198.18.0.0/23","It loops between the two routers until TTL expires; a discard route for the /22 fixes it"],"answer":3,"explanation":"The ISP sends it in because of the /22 advertisement; the internal router finds no specific route and follows its default back to the ISP, which sends it back again. Installing a discard route for the advertised aggregate breaks the loop.","difficulty":"very-hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-397","question":"A 4-port router has 3 interfaces on 10.1.1.0/24, 10.1.2.0/24 and 10.1.3.0/24. Which static route best summarises them for an upstream router, without including any 10.1.x.0/24 network outside 1–3 if avoidable?","options":["10.1.0.0/22 covers exactly the three networks","10.1.1.0/22 covers exactly the three networks","No single exact summary exists; 10.1.0.0/22 also covers 10.1.0.0/24","10.1.2.0/23 covers exactly the three networks"],"answer":2,"explanation":"A /22 must start at a multiple of 4 in the third octet, so the smallest block containing 1, 2 and 3 is 10.1.0.0/22 (0–3), which also includes 10.1.0.0/24. 10.1.1.0/22 is not a valid network address; 10.1.2.0/23 covers only 2 and 3.","difficulty":"very-hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-398","question":"A TCP receiver's advertised window is 0 and the sender's persist timer fires. What does the sender transmit?","options":["A RST to restart the connection","A tiny window probe that forces an ACK with the current window","A full-size segment, since the receiver must accept one MSS","A SYN to renegotiate the window"],"answer":1,"explanation":"Window probes are tiny so they never overrun the buffer; the receiver must ACK them, and the ACK reports the current window. If still zero, the probe interval backs off exponentially.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-399","question":"A home router performs NAT for 3 PCs that each open 2 TCP connections to the same web server on port 443. How many distinct (public IP, public port) pairs does the router's NAT table use for these connections?","options":["6","3","2","1"],"answer":0,"explanation":"Each connection needs a unique external 4-tuple; since the public IP and the server's IP:443 are the same for all six, the router must give each a different public source port. PAT distinguishes the connections only by port.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-400","question":"172.16.0.0/22 can be used as one subnet or split into four /24 subnets. How many usable host addresses are lost by splitting?","options":["0","8","4","6"],"answer":3,"explanation":"One /22 gives 1024 − 2 = 1022 usable addresses; four /24s give 4 × 254 = 1016. Each extra subnet costs its own network and broadcast address: 3 extra subnets × 2 = 6.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-401","question":"192.168.4.0/22 is divided into /28 subnets. In how many of them does the broadcast address end in .255?","options":["1","64","4","16"],"answer":2,"explanation":"There are 64 /28s, sixteen per /24. Only the last /28 of each /24 (.240–.255) has .255 as its broadcast, and the /22 contains four /24s, so 4 subnets.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-402","question":"For the host 10.200.75.130/18, what is its subnet's network address, and how many addresses after the network address does the host sit (its offset within the subnet)?","options":["10.200.64.0; offset 2946","10.200.75.0; offset 130","10.200.64.0; offset 2690","10.200.0.0; offset 19330"],"answer":0,"explanation":"/18 leaves 6 network bits in the third octet, blocks of 64: 75 lies in 64–127, so the network is 10.200.64.0. Offset = (75 − 64) × 256 + 130 = 2946; the subnet holds 16,382 usable hosts in all.","difficulty":"very-hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-403","question":"A TCP sender in congestion avoidance counts cwnd in MSS units and, for each new ACK, does cwnd ← cwnd + 1/cwnd. cwnd is 10 at the start of an RTT and the 10 segments of that window are ACKed one by one. What is cwnd after those 10 ACKs (to two decimals)?","options":["11.00","10.96","20.00","10.91"],"answer":1,"explanation":"The increments shrink as cwnd grows: 1/10, 1/10.1, 1/10.199, … summing to ≈ 0.95, so cwnd ≈ 10.96. It approximates the textbook '+1 MSS per RTT' from slightly below; doubling to 20 would be slow start.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-404","question":"What is the key difference between TCP Tahoe and TCP Reno when three duplicate ACKs arrive?","options":["Tahoe ignores duplicate ACKs; Reno retransmits","Reno sets cwnd to 1 MSS; Tahoe halves it","Both behave identically; they differ only on timeouts","Tahoe sets cwnd to 1 MSS and slow-starts; Reno halves cwnd and continues with fast recovery"],"answer":3,"explanation":"Both perform fast retransmit. Tahoe then treats the loss like a timeout (ssthresh = cwnd/2, cwnd = 1). Reno reasons that duplicate ACKs mean data is still flowing, so it sets cwnd ≈ ssthresh and avoids a slow-start restart.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-405","question":"A packet crosses 3 links; each link independently loses it with probability 0.1. Compare the expected number of LINK transmissions per delivered packet with (a) end-to-end retransmission from the source and (b) hop-by-hop retransmission on each link.","options":["(a) ≈ 1.37, (b) ≈ 3.33","(a) ≈ 3.72, (b) ≈ 3.33","(a) ≈ 3.33, (b) ≈ 3.72","(a) ≈ 4.12, (b) ≈ 3.00"],"answer":1,"explanation":"End to end: an attempt succeeds with 0.9³ = 0.729; each attempt uses 1 + 0.9 + 0.81 = 2.71 link transmissions on average, so 2.71 / 0.729 ≈ 3.72. Hop by hop: each link needs 1/0.9 transmissions, 3 × 1.11 ≈ 3.33. 1.37 is the number of end-to-end ATTEMPTS, not link transmissions.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-406","question":"A 1 MB file (10⁶ bytes) is sent with stop-and-wait using 1000-byte frames over a 5 Mbps path with RTT 100 ms (ACK size and processing negligible). Roughly how long does the transfer take?","options":["About 1.6 s","About 100.0 s","About 101.6 s","About 51.6 s"],"answer":2,"explanation":"Each frame costs its transmission time 1.6 ms plus one RTT of 100 ms waiting for the ACK: 1000 × 101.6 ms ≈ 101.6 s, versus 1.6 s if the pipe were kept full. This is why sliding windows exist.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-407","question":"A CRC-8 with generator x⁸ + x² + x + 1 (100000111) and no initial value or final XOR is computed over the byte 00110001 (ASCII '1'). What is the 8-bit remainder?","options":["10010111","10010110","11101001","10101101"],"answer":0,"explanation":"Append eight 0s and divide modulo 2 by the 9-bit generator 100000111; the remainder is 10010111 (0x97). Reversing the remainder or the input bits gives other values; real CRC-8 variants also specify bit order, initial value and final XOR.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-408","question":"A source must send a 10 MB burst at the full line rate of 50 MB/s through a token bucket whose tokens arrive at 10 MB/s. What is the smallest bucket capacity (starting full) that lets the whole burst go out at line rate?","options":["10 MB","2 MB","8 MB","40 MB"],"answer":2,"explanation":"Sending 10 MB at 50 MB/s takes 0.2 s, during which 10 × 0.2 = 2 MB of new tokens arrive. The bucket must therefore start with 10 − 2 = 8 MB (equivalently C = S(M − ρ) = 0.2 × 40).","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-409","question":"Router B uses distance-vector routing with split horizon. B's table: to X cost 3 via A, to Y cost 2 via C, to Z cost 5 via A. Which destinations appear in the vector B sends to A?","options":["X, Y and Z","Only Y (cost 2)","X and Z","Y and Z"],"answer":1,"explanation":"Split horizon forbids advertising a route back to the neighbour it was learned from: X and Z are both reached via A, so they are omitted from the update to A. With poisoned reverse they would be sent with cost ∞ instead.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-410","question":"Synchronous Bellman–Ford runs from S on an undirected graph S–A 4, S–B 1, B–A 2, A–C 1, B–C 6, C–D 2, A–D 7. In each round every node's estimate is recomputed from its neighbours' estimates of the PREVIOUS round. After exactly 2 rounds, what are the estimates for A, C and D?","options":["A = 3, C = 5, D = 11","A = 3, C = 4, D = 6","A = 4, C = 5, D = 11","A = 3, C = 7, D = 11"],"answer":0,"explanation":"Round 1 uses only round-0 values: A = 4, B = 1, others ∞. Round 2: A = min(4, 1 + 2) = 3, C = min(4 + 1, 1 + 6) = 5, D = 4 + 7 = 11. The true values (A = 3, C = 4, D = 6) need more rounds, since the best paths have 3–4 hops.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-411","question":"A page (base file 100 KB) references 10 images of 100 KB each on the same server (1 KB = 1000 bytes). The link is 1 Mbps with RTT 50 ms. Using one persistent HTTP connection WITH pipelining (all 10 image requests sent together once the base file has arrived), and ignoring DNS and slow start, about how long does the whole page take?","options":["About 9.40 s","About 8.80 s","About 8.90 s","About 8.95 s"],"answer":3,"explanation":"Handshake 0.05 s; base file 0.05 + 0.8 s; then one RTT for the pipelined requests plus 10 × 0.8 s of back-to-back transmission: total ≈ 8.95 s. Without pipelining each image adds its own RTT (9.40 s). Transmission time dominates on this slow link.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-412","question":"Ignoring DNS, how many RTTs does a fresh HTTPS request take until the response arrives with TCP + TLS 1.3, and with HTTP/3 over QUIC (no 0-RTT)?","options":["4 RTTs and 3 RTTs","3 RTTs and 1 RTT","2 RTTs and 2 RTTs","3 RTTs and 2 RTTs"],"answer":3,"explanation":"TCP handshake (1) + TLS 1.3 handshake (1) + request/response (1) = 3. QUIC merges the transport and TLS handshakes into a single RTT, so 1 + 1 = 2. With 0-RTT resumption QUIC can send the request in its first flight.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-413","question":"A 60-second video clip is encoded at a constant 2 Mbps, but the network delivers only 1.5 Mbps. What is the minimum start-up (prebuffering) delay that guarantees playback never stalls?","options":["20 s","15 s","30 s","45 s"],"answer":0,"explanation":"Playback must never overtake download: 1.5(t + D) ≥ 2t for all t ≤ 60 s, which is tightest at t = 60: D ≥ 60 × 0.5 / 1.5 = 20 s. Equivalently the 120 Mb clip needs 80 s to download and 60 s to play.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-414","question":"Which statement about BitTorrent piece selection and peer choice is correct?","options":["Peers download pieces strictly in file order to allow streaming","The tracker sends every piece to every peer","Rarest-first piece selection with tit-for-tat uploading and optimistic unchoking","Peers upload only to the seeder"],"answer":2,"explanation":"Rarest-first keeps all pieces available in the swarm; tit-for-tat rewards cooperative peers, and optimistic unchoking lets newcomers and better partners be discovered. The tracker only helps peers find each other.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-415","question":"What is the Shannon capacity of a 1 MHz channel whose SNR is 20 dB?","options":["About 4.39 Mbps","About 6.66 Mbps","About 20.00 Mbps","About 13.32 Mbps"],"answer":1,"explanation":"20 dB means S/N = 10^(20/10) = 100, so C = 10⁶ × log₂101 ≈ 6.66 Mbps. Using 20 as the ratio gives 4.39 Mbps; doubling B confuses Shannon with Nyquist's 2B.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-416","question":"What is the maximum size of an Ethernet frame carrying an 802.1Q VLAN tag (destination MAC through FCS, standard 1500-byte payload)?","options":["1522 bytes","1518 bytes","1526 bytes","1500 bytes"],"answer":0,"explanation":"An untagged frame is 14 + 1500 + 4 = 1518 bytes; the 4-byte 802.1Q tag makes it 1522. 1526 would add the preamble's start byte or a second tag; 1500 is just the payload (MTU).","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-417","question":"With TCP/IPv4 (40 bytes of headers) and 38 bytes of Ethernet per-frame wire overhead, how does the maximum goodput fraction compare for 9000-byte jumbo frames versus standard 1500-byte frames?","options":["About 99.6% versus 97.3%","100% in both cases","About 94.9% versus 99.1%","About 99.1% versus 94.9%"],"answer":3,"explanation":"Goodput fraction = payload / wire bytes: 8960 / 9038 ≈ 99.1% and 1460 / 1538 ≈ 94.9%. Jumbo frames also cut per-packet CPU and interrupt work by about 6×, which often matters more than the 4% bandwidth gain.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-418","question":"Flow A uses only link 1 (10 Mbps); flow B uses links 1 and 2; flow C uses only link 2 (6 Mbps). What is the max-min fair allocation?","options":["A = 5, B = 5, C = 1 Mbps","A = 7, B = 3, C = 3 Mbps","A = 5, B = 3, C = 3 Mbps","A = 10, B = 0, C = 6 Mbps"],"answer":1,"explanation":"Raise all flows equally until a link fills: link 2 saturates first at 3 + 3 = 6, fixing B = C = 3. Then A alone grows on link 1 until 10 − 3 = 7. No flow can gain without taking from a flow that has less or equal.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-419","question":"A TDMA frame has 10 slots of 1 ms each, and every slot includes a 0.1 ms guard time with no data. What fraction of capacity carries data, and what rate does each station get on a 10 Mbps channel?","options":["100%; 1 Mbps per station","90%; 9 Mbps per station","90%; 0.9 Mbps per station","99%; 0.99 Mbps per station"],"answer":2,"explanation":"Each slot loses 0.1 / 1 = 10% to guard time, so 90% carries data. With 10 stations sharing the channel equally, each gets 10 × 0.9 / 10 = 0.9 Mbps.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-420","question":"Frames take T = 1 ms to transmit. What are the vulnerable periods of pure ALOHA and slotted ALOHA, and why does slotting double the maximum throughput?","options":["1 ms and 0.5 ms; slots halve the frame time","2 ms and 2 ms; slotting only synchronises clocks","2 ms and 1 ms; collisions can only come from frames sent in the same slot","4 ms and 2 ms; slots add guard times"],"answer":2,"explanation":"In pure ALOHA a frame collides with any frame started up to T before or after it (2T). Slotting aligns starts, so only frames in the same slot collide (T). Throughput becomes G·e^(−G) instead of G·e^(−2G), peaking at 1/e vs 1/(2e).","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-421","question":"Which statement about CSMA persistence strategies is correct?","options":["1-persistent sends the moment the channel idles, so waiting stations collide; p-persistent sends with probability p","Non-persistent CSMA senses continuously and always transmits immediately","p-persistent CSMA always waits a full random backoff even when the channel is idle","1-persistent CSMA never causes collisions"],"answer":0,"explanation":"With 1-persistent, every station that queued up during a transmission jumps in at the same instant. Non-persistent waits a random time before sensing again (lower collisions, more idle time); p-persistent compromises in slotted channels.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-422","question":"A link has a bit-error rate of 10⁻⁶ (independent errors). What fraction of 1500-byte frames contain at least one bit error?","options":["About 0.15%","About 0.012%","About 0.0001%","About 1.19%"],"answer":3,"explanation":"P(error) = 1 − (1 − 10⁻⁶)^12000 ≈ 1 − e^(−0.012) ≈ 1.19%. 0.15% counts bytes instead of bits.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-423","question":"Which fields form the pseudo-header included in the TCP checksum over IPv4?","options":["Source port, destination port and sequence number","Source IP, destination IP, a zero byte, protocol number and TCP length","Source MAC, destination MAC and EtherType","TTL, identification and fragment offset"],"answer":1,"explanation":"Including the IP addresses and protocol lets TCP detect segments delivered to the wrong host or protocol. Fields that change in transit (TTL, fragmentation) are deliberately excluded; MAC addresses are link-local.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-424","question":"A SYN scan sends a SYN to each port of a host. Which pairing of response and conclusion is correct?","options":["SYN-ACK → closed; RST → open","SYN-ACK → open; RST → closed; no reply (or ICMP unreachable) → filtered","RST → filtered; no reply → open","Any reply → open; no reply → closed"],"answer":1,"explanation":"An open port completes the second step of the handshake (the scanner then sends RST instead of the final ACK); a closed port answers RST; a firewall dropping packets produces silence or an ICMP error.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-425","question":"A router has a /24 LAN. After assigning one /25 and one /26 to two departments, how many /30 point-to-point subnets can be carved from what remains?","options":["32","8","64","16"],"answer":3,"explanation":"/25 uses 128 and /26 uses 64 addresses, leaving one /26 (64 addresses). Each /30 needs 4 addresses: 64 / 4 = 16.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-426","question":"What are the dotted-decimal subnet mask and the ACL wildcard mask for a /21 prefix?","options":["255.255.248.0 and 0.0.7.255","255.255.240.0 and 0.0.15.255","255.255.248.0 and 0.0.8.255","255.255.252.0 and 0.0.3.255"],"answer":0,"explanation":"/21 = 8 + 8 + 5 bits: the third octet is 11111000 = 248. The wildcard is the bitwise inverse: 255 − 248 = 7 in the third octet and 255 in the fourth.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-427","question":"An IPv4 header has HLEN = 6 and the total length field is 576. How many bytes of options and payload does the packet carry?","options":["0 bytes of options; 556 bytes of payload","6 bytes of options; 550 bytes of payload","4 bytes of options; 552 bytes of payload","4 bytes of options; 556 bytes of payload"],"answer":2,"explanation":"HLEN 6 → 24-byte header, i.e. 4 bytes beyond the fixed 20. Payload = 576 − 24 = 552 bytes.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-428","question":"A TCP header has data offset = 8. How many bytes of options does it contain, and could they hold MSS (4 bytes), window scale (3 bytes) and SACK-permitted (2 bytes)?","options":["8 bytes; no","32 bytes; yes, with room for timestamps too","12 bytes; yes, 9 bytes plus 3 bytes of padding/NOPs","12 bytes; no, options must be multiples of 8"],"answer":2,"explanation":"Data offset counts 32-bit words: 8 × 4 = 32-byte header, 12 bytes of options. 4 + 3 + 2 = 9 bytes fit, with NOPs/padding to reach a 4-byte boundary; adding timestamps (10 bytes) would need 20.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-429","question":"On an Ethernet path (MTU 1500), what is the largest ICMP echo data size (ping payload) that still fits in one unfragmented IPv4 packet?","options":["1480 bytes","1500 bytes","1460 bytes","1472 bytes"],"answer":3,"explanation":"1500 − 20 (IPv4 header) − 8 (ICMP header) = 1472. That is why 'ping -s 1472 -M do' is used to test a 1500-byte path MTU. 1460 is TCP's MSS (20-byte TCP header).","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-430","question":"A PPPoE DSL link has an MTU of 1492. What TCP MSS should the router clamp SYNs to (IPv4, no options), and why?","options":["1452, so data plus 40 header bytes fit in 1492","1460, the standard Ethernet MSS","1472, the ICMP payload limit","1484, subtracting only the 8-byte PPPoE header"],"answer":0,"explanation":"PPPoE takes 8 bytes of the 1500-byte Ethernet payload, leaving an IP MTU of 1492. Subtracting 40 bytes of IP and TCP headers gives MSS 1452; clamping avoids relying on PMTUD, which ICMP filtering often breaks.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-431","question":"A GRE tunnel over IPv4 adds a 20-byte outer IP header and a 4-byte GRE header. If the physical path MTU is 1500, what MTU should the tunnel interface use to avoid fragmenting encapsulated packets?","options":["1480","1476","1500","1472"],"answer":1,"explanation":"Each inner packet gains 20 + 4 = 24 bytes, so it must be at most 1500 − 24 = 1476 bytes. 1480 accounts only for the outer IP header (as for IP-in-IP).","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-432","question":"A UDP header shows a length field of 0x0040. How many bytes of application data does the datagram carry?","options":["64","40","56","48"],"answer":2,"explanation":"0x0040 = 64 bytes, and the UDP length includes its own 8-byte header, so the payload is 64 − 8 = 56 bytes.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-433","question":"Which statement about TCP's three-way handshake is correct?","options":["It negotiates the encryption keys for the connection","It agrees on both initial sequence numbers; each SYN uses up one sequence number","Only the client chooses an initial sequence number; the server reuses it","The third segment (ACK) can never carry data"],"answer":1,"explanation":"Each side picks a random ISN and the other acknowledges ISN + 1, so both directions agree on where the byte stream starts. The final ACK MAY carry data. Encryption is TLS's job.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-434","question":"Two stations 2.5 km apart share a 10 Mbps bus (signals at 2 × 10⁸ m/s). What is the 'a' parameter (propagation time / transmission time) for 512-bit frames, and what does it imply for CSMA/CD?","options":["a = 0.0244; collisions are impossible","a = 4.10; CSMA/CD cannot work","a = 0.488; frames must be at least 2a long","a = 0.244; small enough for carrier sensing to work well"],"answer":3,"explanation":"Tp = 2500 / 2 × 10⁸ = 12.5 µs and Tt = 512 / 10⁷ = 51.2 µs, so a ≈ 0.244. A small a means a station learns about other transmissions quickly relative to frame length; since 2Tp = 25 µs < 51.2 µs, collisions are always detected while sending.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-435","question":"Which statement about switches with VLAN trunks is correct?","options":["A trunk carries several VLANs' frames, each tagged with its VLAN ID","A trunk port belongs to exactly one VLAN and strips all tags","Trunks route traffic between VLANs without a router","A trunk port floods every frame to all VLANs"],"answer":0,"explanation":"An access port belongs to one VLAN and sends untagged frames; a trunk multiplexes VLANs with 802.1Q tags. Inter-VLAN communication still requires layer-3 routing.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-436","question":"A server sends to a client over a 100 Mbps path with RTT 200 ms. The client's receive buffer is 64 KB and window scaling is unavailable. Roughly what throughput results, and what is the simplest fix?","options":["100 Mbps; nothing needs fixing","About 2.6 Mbps; enable window scaling with a larger receive buffer","About 1.3 Mbps; disable Nagle's algorithm","About 2.6 Mbps; increase the congestion window"],"answer":1,"explanation":"Throughput ≤ window / RTT = 524,288 bits / 0.2 s ≈ 2.6 Mbps. The receiver window, not cwnd, is the limit, so cwnd cannot exceed it; filling 100 Mbps × 0.2 s needs 2.5 MB, i.e. window scaling.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-437","question":"Ten stations use slotted ALOHA, each transmitting in a slot with probability 0.1. What is the probability that a slot is wasted (idle or collision)?","options":["0.387","0.349","0.632","0.613"],"answer":3,"explanation":"P(success) = 10 × 0.1 × 0.9⁹ ≈ 0.387, so a slot is wasted with probability 0.613. Of that, 0.9¹⁰ ≈ 0.349 is idle and the rest collisions. 1 − 1/e is the limit for large N.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-438","question":"Host A's IP is 192.168.1.10/24 with gateway 192.168.1.1, but A is misconfigured with mask 255.255.0.0. What happens when A sends to 192.168.7.20 (a host on another subnet behind the gateway)?","options":["A sends the packet to the gateway as usual","The switch rewrites the mask and forwards correctly","A ARPs for 192.168.7.20 directly, gets no reply, and the traffic fails","A broadcasts the IP packet to 192.168.255.255"],"answer":2,"explanation":"With /16, 192.168.7.20 appears local, so A skips the gateway and ARPs for it. The target is not on A's LAN, so no reply arrives; a router with proxy ARP could answer on its behalf and mask the mistake.","difficulty":"very-hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-439","question":"A router receives an IPv4 packet whose destination matches no route and there is no default route. What does it do?","options":["Drops it and returns ICMP Destination Unreachable to the source","Floods the packet out of all interfaces","Returns the packet to the previous router with TTL reset","Holds the packet until a route appears"],"answer":0,"explanation":"IP routers do not flood or queue unroutable packets. They drop them and, rate-limited, report Destination Unreachable (type 3, code 0) so the sender learns of the failure.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-440","question":"Two TCP connections share a link with a FIFO drop-tail queue. Connection 1 uses one TCP flow; application 2 opens 9 parallel TCP flows with the same RTT. Roughly what share of the bottleneck does application 2 get?","options":["About 50%","About 10%","About 90%","About 100%"],"answer":2,"explanation":"TCP fairness is per flow: 10 flows share roughly equally, so the 9-flow application gets about 9/10. This is why download managers and some browsers open several connections, and why per-flow fairness is not per-user fairness.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-441","question":"Which pairing of port number and protocol is correct for each of: 53, 67, 110, 143, 443?","options":["DNS, DHCP client, IMAP, POP3, HTTPS","DHCP server, DNS, POP3, IMAP, HTTP","DNS, BOOTP client, SMTP, IMAP, HTTPS","DNS, DHCP server, POP3, IMAP, HTTPS"],"answer":3,"explanation":"53 is DNS, 67 the DHCP/BOOTP server (68 is the client), 110 POP3, 143 IMAP and 443 HTTPS. Mixing up 110 and 143 is the usual slip.","difficulty":"hard","source":"GATE CS · Product company CS fundamentals"},
  {"id":"cs-computer-networks-442","question":"An organisation has a /23 and needs subnets for 120, 60, 60, 30 and 10 hosts. Allocated with VLSM (largest first, aligned), how many addresses remain unallocated?","options":["192","208","256","224"],"answer":1,"explanation":"Block sizes: 120 → 128, 60 → 64, 60 → 64, 30 → 32 (30 + 2 = 32 fits exactly), 10 → 16. Total 128 + 64 + 64 + 32 + 16 = 304 of the /23's 512 addresses, so 208 remain. Rounding 30 hosts up to 64 (forgetting that 32 − 2 = 30 is enough) would give 176.","difficulty":"very-hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-443","question":"A router's output queue behaves like an M/M/1 queue. Each packet needs 2 ms of transmission on average, and the measured average time a packet spends at the link (queueing + transmission) is 10 ms. What is the link utilisation?","options":["0.8","0.2","0.5","0.9"],"answer":0,"explanation":"For M/M/1, T = (1/μ) / (1 − ρ), so 10 = 2 / (1 − ρ) gives ρ = 0.8. Utilisation 0.2 would be the ratio 2/10 itself; at ρ = 0.9 the delay would already be 20 ms.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-444","question":"Go-Back-N with window N = 7 runs on a link long enough that a whole window is outstanding when an error is discovered (N ≤ 1 + 2a). Frames are lost independently with probability p = 0.1. Using the standard result that each loss costs a retransmission of the whole window, what is the expected number of transmissions per successfully delivered frame, (1 − p + Np)/(1 − p)?","options":["1.11","1.78","1.70","2.09"],"answer":1,"explanation":"(1 − 0.1 + 0.7) / 0.9 = 1.6 / 0.9 ≈ 1.78. Selective Repeat would need only 1/(1 − p) ≈ 1.11, which is why GBN degrades badly on lossy, long links.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-445","question":"A TCP sender's first data byte has sequence number 4,294,966,296 (that is, 2³² − 1000). It sends five 512-byte segments back to back. What is the sequence number of the third segment, and what ACK number acknowledges all five?","options":["4294967320 and 4294968856","23 and 1559","536 and 1560","24 and 1560"],"answer":3,"explanation":"The third segment starts 2 × 512 = 1024 bytes later: 2³² − 1000 + 1024 = 2³² + 24 → 24 after wrapping modulo 2³². All five cover 2560 bytes, so the ACK is 2³² − 1000 + 2560 = 1560 (mod 2³²). Sequence arithmetic must always be done modulo 2³².","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-446","question":"A host is configured as 172.31.200.77/21. What are the network address and the broadcast address of its subnet?","options":["172.31.192.0 and 172.31.207.255","172.31.200.0 and 172.31.200.255","172.31.200.0 and 172.31.207.255","172.31.192.0 and 172.31.199.255"],"answer":2,"explanation":"A /21 leaves 3 network bits in the third octet, so blocks there are 8 wide: 200 lies in 200–207. The network is 172.31.200.0 and the broadcast 172.31.207.255; 192–207 would be a /20 block.","difficulty":"moderate","source":"GATE CS · TCS NQT"},
  {"id":"cs-computer-networks-447","question":"The block 10.20.0.0/14 is used as one flat subnet. Which of these addresses can be assigned to a host in it?","options":["10.23.255.255","10.22.255.255","10.24.0.1","10.20.0.0"],"answer":1,"explanation":"A /14 spans 4 values of the second octet: 10.20.0.0 to 10.23.255.255. 10.22.255.255 is an ordinary interior address; 10.20.0.0 is the network address, 10.23.255.255 the broadcast and 10.24.0.1 lies outside.","difficulty":"moderate","source":"GATE CS · Cisco/networking placement"},
  {"id":"cs-computer-networks-448","question":"An organisation holds 150.20.0.0/16 and needs at least 50 subnets, each with at least 1000 usable host addresses, all of one size. Which mask works, and how many subnets of that size are left unused after allocating 50 (subnet zero and the all-ones subnet allowed)?","options":["255.255.248.0, with no subnets left over","255.255.252.0, with 12 subnets left over","255.255.254.0, with 78 subnets left over","255.255.252.0, with 14 subnets left over"],"answer":3,"explanation":"50 subnets need 6 subnet bits (64), leaving 10 host bits: 1022 usable hosts, so /22 = 255.255.252.0 works and 64 − 50 = 14 are spare. A /21 gives only 32 subnets, a /23 only 510 hosts, and 12 spare comes from wrongly discarding subnet zero and the all-ones subnet.","difficulty":"very-hard","source":"GATE CS · Cisco/networking placement"},
  {"id":"cs-computer-networks-449","question":"A router's table has 131.23.0.0/16 → A, 131.23.128.0/17 → B, 131.23.144.0/20 → C, 131.23.148.0/22 → D and a default route → E. Where does it forward packets to 131.23.150.9, 131.23.160.1, 131.23.127.5 and 131.23.152.1, in that order?","options":["D, B, A, C","C, B, A, C","D, C, A, D","D, B, E, C"],"answer":0,"explanation":"The /22 covers third octet 148–151 (so .150 → D), the /20 covers 144–159 (.152 → C, but .160 is outside → B via the /17 that covers 128–255) and .127 matches only the /16 → A. Longest prefix wins in every case.","difficulty":"hard","source":"GATE CS · Cisco/networking placement"},
  {"id":"cs-computer-networks-450","question":"An ISP wants to advertise the four customer networks 200.10.8.0/24, 200.10.9.0/24, 200.10.10.0/24 and 200.10.12.0/24 as a single CIDR prefix. What is the longest prefix that covers all four, and how many addresses does it cover that belong to none of them?","options":["200.10.8.0/22, covering no extra addresses","200.10.8.0/21, covering 1024 extra addresses","200.10.8.0/21, covering 768 extra addresses","200.10.0.0/20, covering 3072 extra addresses"],"answer":1,"explanation":"A /22 starting at 8 ends at 11, so 12 forces a /21 (third octet 8–15). That block holds 8 /24s, of which 4 are not the customer's: 4 × 256 = 1024 extra addresses. The /20 also covers them but is not the longest such prefix.","difficulty":"hard","source":"GATE CS · Cisco/networking placement"},
  {"id":"cs-computer-networks-451","question":"A firewall rule must match exactly the addresses 192.168.1.20 to 192.168.1.75 (inclusive) and nothing else, using CIDR blocks. What is the fewest number of blocks needed?","options":["3","1","4","5"],"answer":3,"explanation":"Each block must be aligned to its own size: 20/30 (20–23), 24/29 (24–31), 32/27 (32–63), 64/29 (64–71) and 72/30 (72–75), so 5 blocks. Fewer blocks always overshoot, e.g. a single /25 or a /28 starting at 16.","difficulty":"very-hard","source":"GATE CS · Cisco/networking placement"},
  {"id":"cs-computer-networks-452","question":"A 4000-byte IPv4 datagram (20-byte header, no options, DF = 0) first crosses a link with MTU 1500, then a link with MTU 620; no reassembly happens on the way. How many fragments reach the destination, and what is the fragment-offset field of the last one?","options":["7 fragments, offset 445","8 fragments, offset 3560","8 fragments, offset 445","7 fragments, offset 370"],"answer":2,"explanation":"First link: payloads 1480, 1480, 1020 at offsets 0, 185, 370 (units of 8 bytes). Each is re-fragmented separately into 600-byte pieces: 3 + 3 + 2 = 8 fragments, and the last carries the final 420 bytes at offset 370 + 600/8 = 445. 7 comes from splitting 3980 bytes as if it were whole; 3560 is that offset in bytes, not 8-byte units.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-453","question":"A 4 Mbps link carries 1000-byte frames with a one-way propagation delay of 20 ms. Go-Back-N uses 3-bit sequence numbers with the largest window that is safe. Ignoring ACK size and processing, what is the link utilisation?","options":["33.3%","38.1%","35.0%","19.0%"],"answer":0,"explanation":"Tt = 8000/4×10⁶ = 2 ms, and one cycle is Tt + 2Tp = 42 ms. GBN with 3-bit numbers allows a window of 7, so utilisation = 7 × 2 / 42 = 33.3%. 38.1% uses a window of 8, 35% forgets Tt in the cycle, and 19% uses the Selective Repeat window of 4.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-454","question":"Stop-and-wait runs at 1 Mbps with 1000-byte frames and a one-way propagation delay of 11 ms (ACKs take no transmission time). Each data frame is lost with probability 0.2 and each ACK independently with probability 0.1; a timeout fires exactly one cycle after sending. What is the expected useful throughput?","options":["213.3 kbps","192.0 kbps","186.7 kbps","266.7 kbps"],"answer":1,"explanation":"A frame succeeds only if it and its ACK both survive: probability 0.8 × 0.9 = 0.72, so 1/0.72 cycles of 8 + 22 = 30 ms are needed on average. Throughput = 8000 × 0.72 / 0.030 = 192 kbps. 213.3 ignores ACK loss, 186.7 wrongly uses 1 − 0.2 − 0.1 = 0.7, and 266.7 ignores losses altogether.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-455","question":"A TCP Tahoe sender starts with cwnd = 1 MSS and ssthresh = 16 MSS; cwnd doubles each round in slow start (but never jumps above ssthresh) and grows by 1 MSS per round in congestion avoidance. A timeout occurs during round 7 and nothing else is lost. What is cwnd during round 13?","options":["14 MSS","17 MSS","18 MSS","10 MSS"],"answer":3,"explanation":"Rounds 1–7: 1, 2, 4, 8, 16, 17, 18. The timeout sets ssthresh = 18/2 = 9 and cwnd = 1, so rounds 8–13 are 1, 2, 4, 8, 9, 10. 14 restarts at cwnd = 9 as in Reno's fast recovery, 17 ignores the new ssthresh, and 18 forgets to halve it.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-456","question":"A client's SYN carries sequence number 5000. After the handshake it sends three data segments of 200, 300 and 100 bytes and then a FIN, all received in order. What acknowledgement number does the server send to acknowledge the FIN?","options":["5601","5603","5602","5600"],"answer":2,"explanation":"The SYN consumes 5000, so data occupies 5001–5600 and the FIN takes sequence number 5601; acknowledging it means ACK = 5602. 5601 forgets that a FIN consumes a sequence number, and 5600 also forgets the SYN.","difficulty":"hard","source":"GATE CS · Product-company placement"},
  {"id":"cs-computer-networks-457","question":"A TCP connection runs over a 1 Gbps path with an RTT of 80 ms. What is the smallest window-scale shift count S (window = 65,535 × 2^S bytes) that lets one connection fill the path?","options":["8","7","11","14"],"answer":0,"explanation":"The bandwidth-delay product is 10⁹ × 0.08 / 8 = 10⁷ bytes; 10⁷ / 65,535 ≈ 152.6, so 2^S must be at least 256, S = 8. 7 uses the one-way delay, 11 forgets to convert bits to bytes, and 14 is merely the maximum allowed value.","difficulty":"hard","source":"GATE CS · Product-company placement"},
  {"id":"cs-computer-networks-458","question":"A production server shows thousands of TCP sockets stuck in CLOSE_WAIT that never go away. What is the most likely cause?","options":["The clients are not sending their final ACK, so the server waits for it","The server application received the peers' FIN but never calls close() on those sockets","The server closed first and is waiting 2 × MSL before releasing the ports","A firewall is dropping the server's SYN-ACKs during connection setup"],"answer":1,"explanation":"CLOSE_WAIT means the peer has sent FIN and the local side has acknowledged it; the socket leaves this state only when the local application calls close(). Waiting 2 × MSL is TIME_WAIT on the side that closed first, and a missing final ACK leaves the closer in LAST_ACK.","difficulty":"hard","source":"Product-company placement · SRE interview"},
  {"id":"cs-computer-networks-459","question":"A TCP server listens on port 80. Three clients connect and the server accept()s all of them. How many TCP sockets does the server process now hold, and what local port do the connected ones use?","options":["4 sockets, all with local port 80","3 sockets, each on a new ephemeral port","4 sockets: the listener on 80, the others on ephemeral ports","1 socket on port 80 shared by all three connections"],"answer":0,"explanation":"accept() returns a new connected socket for each client while the listening socket stays open, so there are 1 + 3 = 4. Connected sockets keep local port 80; they are told apart by the full 4-tuple (local IP, local port, remote IP, remote port).","difficulty":"moderate","source":"Product-company placement · TCS NQT"},
  {"id":"cs-computer-networks-460","question":"Karn's algorithm is applied to TCP's RTT estimation. Which statement is correct?","options":["The RTT sample of a retransmitted segment is taken from the first transmission's send time","RTT samples are taken only from retransmitted segments, since they show the real delay under loss","RTT samples are not taken for retransmitted segments, and the backed-off RTO is kept until a sample comes from a segment sent only once","The RTO is reset to its initial value after every retransmission"],"answer":2,"explanation":"After a retransmission the ACK is ambiguous (it may answer either copy), so Karn ignores such samples and keeps the doubled RTO until an unambiguous sample arrives. Timing from the first send can grossly overestimate, and timing from the retransmission can underestimate.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-461","question":"The data 1001101110 is protected by a CRC with generator x⁴ + x + 1. What check bits are appended to it?","options":["1110","1010","0010","0001"],"answer":3,"explanation":"Append 4 zeros (the generator's degree) and divide 10011011100000 by 10011 with XOR: the remainder is 0001, and 10011011100001 divides exactly. 1110 comes from not appending zeros, 1010 from writing the generator as 11001, and 0010 from appending 5 zeros.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-462","question":"A block code must correct every pattern of up to 2 bit errors and, at the same time, detect (without miscorrecting) every pattern of up to 4 bit errors. What is the minimum Hamming distance it needs?","options":["5","7","9","11"],"answer":1,"explanation":"To correct t errors and also detect d > t errors you need d_min ≥ t + d + 1 = 2 + 4 + 1 = 7, so a 4-error word stays outside the radius-2 sphere of every other codeword. 5 handles only the correction, and 9 adds the separate requirements 2t + 1 and d + 1.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-463","question":"Data is sent as a block of bits with an even-parity bit for every row and every column (two-dimensional parity). How many of these statements are correct?\n1. Every 1-bit error is detected and can be corrected.\n2. Every 2-bit error is detected.\n3. Every 3-bit error is detected.\n4. Every 4-bit error is detected.","options":["1","2","4","3"],"answer":3,"explanation":"Statements 1–3 are true: an odd number of flips in some row or column always shows, and a single error is located by its row and column. Four errors at the corners of a rectangle leave every row and column parity unchanged, so 4 is false.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-464","question":"An HDLC sender bit-stuffs the payload 0111111111111101111101111110 (a 0 after every five consecutive 1s, counting restarting after each stuffed 0). How many 0s does it insert?","options":["4","3","5","2"],"answer":0,"explanation":"The run of 13 ones gets a 0 after the 5th and 10th ones; the next run of exactly 5 ones still gets a 0 even though a 0 follows; the run of 6 ones gets one. Total 4. Answering 3 assumes stuffing happens only when a sixth 1 would follow.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-465","question":"Stations on a 56 kbps pure-ALOHA channel send 1000-bit frames, and together they generate 21 frames per second (new plus retransmitted, Poisson). About how many frames per second get through successfully?","options":["14.4","7.7","9.9","10.3"],"answer":2,"explanation":"G = 21 × 1000/56,000 = 0.375 frames per frame time, and pure ALOHA gives S = G·e^(−2G) ≈ 0.177, i.e. 0.177 × 56 ≈ 9.9 frames/s. 14.4 uses the slotted formula G·e^(−G), and 10.3 just assumes the 18.4% maximum.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-466","question":"A 1 Gbps CSMA/CD network has a maximum cable length of 200 m and signals travel at 2 × 10⁸ m/s. What is the minimum frame size that guarantees a sender detects any collision while still transmitting?","options":["125 bytes","250 bytes","2000 bytes","500 bytes"],"answer":1,"explanation":"The frame must last at least one round trip: 2 × 200 / (2 × 10⁸) = 2 µs, which is 2000 bits at 1 Gbps = 250 bytes. 125 bytes uses only the one-way delay, and 2000 bytes forgets to convert bits to bytes.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-computer-networks-467","question":"A new learning switch has hosts A, B, C and D on ports 1–4. These frames are sent in order: A→B, C→D, B→A, D→C, A→D, then B sends a broadcast. How many of the six frames does the switch flood out of all other ports?","options":["2","4","5","3"],"answer":3,"explanation":"A→B and C→D are flooded because B and D are unknown. B→A, D→C and A→D go out one port, since A, C, B and D were learned from the source addresses of earlier frames. The broadcast is always flooded: 3 in total. A switch learns from source, never destination, addresses.","difficulty":"very-hard","source":"GATE CS · Cisco/networking placement"},
  {"id":"cs-computer-networks-468","question":"Assertion (A): Split horizon with poisoned reverse does not always prevent count-to-infinity in distance-vector routing.\nReason (R): It only stops a router from feeding a route back to the neighbour it learned it from, so a loop through three or more routers can still pass stale routes around.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Poisoned reverse kills two-node loops only. In a triangle, X can hear the stale route from Y, which learned it from Z, so counts still climb to infinity; R gives exactly this reason.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-469","question":"A token bucket has capacity 1 MB, fills at 2 MB/s, and is full at t = 0, when a host starts sending a long burst. The host's link runs at 10 MB/s. How much data leaves in the first 0.25 s?","options":["2.5 MB","1.25 MB","1.5 MB","0.5 MB"],"answer":2,"explanation":"At full rate the bucket empties after C/(M − ρ) = 1/(10 − 2) = 0.125 s, after which output is limited to 2 MB/s. Total = C + ρt = 1 + 2 × 0.25 = 1.5 MB. 2.5 MB assumes full rate throughout, and 1.25 MB counts only the burst phase.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-470","question":"A 100 Mbps link is 3000 km long and signals travel at 2 × 10⁸ m/s. For what packet size does the transmission delay equal the propagation delay?","options":["1.5 MB","375 KB","93.75 KB","187.5 KB"],"answer":3,"explanation":"Tp = 3 × 10⁶ / 2 × 10⁸ = 15 ms, and 100 Mbps × 15 ms = 1.5 × 10⁶ bits = 187,500 bytes. 1.5 MB confuses bits with bytes, and 375 KB uses the round trip.","difficulty":"moderate","source":"GATE CS · TCS NQT"},
  {"id":"cs-computer-networks-471","question":"A home router does port address translation using one public IPv4 address and source ports 1024–65535. Ten PCs behind it all open TCP connections to the same server 93.184.216.34 port 443. At most how many such connections can be open at once?","options":["64,512 per PC, so 645,120 in total","64,512 in total","65,536 in total","Unlimited, because the PCs have different private addresses"],"answer":1,"explanation":"Outside the router every connection has the same public IP, server IP, server port and protocol, so only the translated source port can differ: 65,535 − 1024 + 1 = 64,512 connections in total, however many PCs there are. The private addresses are invisible on the outside.","difficulty":"very-hard","source":"Product-company placement · Cisco/networking"},
  {"id":"cs-computer-networks-472","question":"A form sends a POST to /old, and the server must redirect it to /new so that the browser repeats the POST with the same body, and the move is permanent. Which status code fits?","options":["301 Moved Permanently","303 See Other","307 Temporary Redirect","308 Permanent Redirect"],"answer":3,"explanation":"308 is permanent and forbids changing the method or body. 301 (like 302) historically lets clients turn POST into GET, 303 explicitly tells the client to use GET, and 307 keeps the method but is temporary.","difficulty":"hard","source":"Product-company placement"},
  {"id":"cs-computer-networks-473","question":"A TLS 1.3 client resumes a session and sends application data in 0-RTT (early data). Which statement is correct?","options":["Early data has forward secrecy and replay protection identical to normal data","Early data can be replayed by an attacker, so servers should accept only idempotent requests in it","Early data is sent in plaintext because no keys exist yet","0-RTT removes the TCP handshake as well as the TLS handshake"],"answer":1,"explanation":"0-RTT data is encrypted with a key derived from the pre-shared resumption secret, but nothing in it proves freshness, so it can be replayed, and it lacks forward secrecy for that key. TCP still needs its own handshake unless TCP Fast Open or QUIC is used.","difficulty":"very-hard","source":"Product-company placement · Security interview"},
  {"id":"cs-computer-networks-474","question":"A developer authenticates API messages as tag = SHA-256(secret ‖ message) instead of using HMAC. Why is this unsafe?","options":["SHA-256 is not collision-resistant, so two messages share a tag","The secret can be recovered from the tag by inverting SHA-256","An attacker who knows one message and its tag can compute a valid tag for that message with extra data appended, without the secret","The tag is too short to resist brute force"],"answer":2,"explanation":"Merkle–Damgård hashes like SHA-256 expose their internal state as the output, so from H(secret ‖ m) one can continue hashing to get H(secret ‖ m ‖ padding ‖ extra): a length-extension attack. HMAC's nested construction blocks this; SHA-256 itself is still collision- and preimage-resistant.","difficulty":"very-hard","source":"Product-company placement · Security interview"},
  {"id":"cs-computer-networks-475","question":"Two sites connect through a router that performs NAT. An IPsec tunnel using AH fails, while one using ESP with NAT traversal works. Why?","options":["AH authenticates the IP header including the addresses, so the NAT rewrite makes the integrity check fail","AH encrypts the IP header, so the NAT cannot read the destination","ESP does not provide authentication, so it ignores the rewrite","NAT cannot forward any protocol other than TCP and UDP"],"answer":0,"explanation":"AH's integrity check covers the immutable IP header fields, including source and destination addresses, which NAT changes. ESP authenticates only its own payload and, wrapped in UDP 4500 by NAT-T, gives the NAT a port to translate. AH encrypts nothing.","difficulty":"hard","source":"GATE CS · Security interview"},
  {"id":"cs-computer-networks-476","question":"Asha sends one email with To: Ravi and Bcc: Meena, both at the same domain. How does Meena's server know to deliver a copy to her, given that her address is not in the headers Ravi sees?","options":["The receiving server parses the Bcc header, delivers, then deletes the header","POP3 forwards a copy to every address in the Bcc header","Meena's address is hidden inside the MIME boundary of the body","The sender's SMTP client gives a separate RCPT TO for each recipient in the envelope, independent of the message headers"],"answer":3,"explanation":"SMTP delivery is driven by the envelope (MAIL FROM, RCPT TO), not the To/Cc/Bcc headers in the DATA part. The client sends RCPT TO for Ravi and Meena and strips the Bcc header, so Ravi never sees it.","difficulty":"hard","source":"GATE CS · Product-company placement"},
  {"id":"cs-computer-networks-477","question":"A stateless packet filter at a campus edge allows all outbound TCP, and allows inbound TCP only when the ACK flag is set (so only replies to connections opened from inside get in). Users find that active-mode FTP transfers fail while passive-mode ones work. Why?","options":["In active mode the server opens the data connection from its port 20 to the client, and that inbound SYN has no ACK flag","Active mode encrypts the control channel, so the filter cannot inspect port 21","In passive mode the data connection uses UDP, which the filter does not check","Active mode needs inbound ICMP, which the filter blocks"],"answer":0,"explanation":"In active FTP the client sends PORT and the server then connects back, so the data connection's first packet is an inbound SYN without ACK and is dropped. In passive mode the client opens the data connection outbound, so every inbound packet is a reply carrying ACK.","difficulty":"very-hard","source":"GATE CS · Cisco/networking placement"},
  {"id":"cs-computer-networks-478","question":"A company wants its bare domain example.com to point at a hosting provider's name, as www.example.com does with a CNAME. Why does standard DNS not allow a CNAME at example.com itself?","options":["CNAME records may only point to names in a different top-level domain","A name with a CNAME can have no other records, but the zone apex must hold SOA and NS records","CNAME records are allowed only for names with at least three labels","Resolvers never follow CNAMEs for names queried by browsers"],"answer":1,"explanation":"A CNAME says the name is an alias, so no other data may exist at that name. The apex of every zone must carry SOA and NS, which conflicts; providers work around this with non-standard ALIAS/ANAME flattening.","difficulty":"very-hard","source":"Product-company placement · SRE interview"},
  {"id":"cs-computer-networks-479","question":"How many of these are valid IPv6 addresses?\n1. 2001:db8::1:0:0:1\n2. 2001:db8::1::5\n3. fe80::abcd:12345\n4. ::ffff:192.0.2.1\n5. 2001:0db8:0:0:0:0:0:0:1","options":["2","1","3","4"],"answer":0,"explanation":"1 is valid (:: stands for one run of zero groups) and 4 is a valid IPv4-mapped form. 2 uses :: twice, 3 has a five-digit group, and 5 has nine groups, so all three are invalid.","difficulty":"hard","source":"GATE CS · Cisco/networking placement"},
  {"id":"cs-computer-networks-480","question":"Host 192.168.1.10/24 with gateway 192.168.1.1 has an empty ARP cache. It pings 8.8.8.8, then 1.1.1.1, then 192.168.1.20. How many ARP requests does it send (assume all replies arrive and nothing expires)?","options":["3","1","2","4"],"answer":2,"explanation":"Off-subnet destinations are reached through the gateway, so it ARPs once for 192.168.1.1 and reuses that entry for 1.1.1.1, then ARPs for the on-link 192.168.1.20: 2 requests. A host never ARPs for an off-link IP.","difficulty":"moderate","source":"TCS NQT · Cisco/networking placement"},
  {"id":"cs-computer-networks-481","question":"A client writes a 50-byte header and then a 200-byte body to a TCP socket as two separate write() calls, then waits for the reply. Nagle's algorithm is on at the client and delayed ACKs are on at the server. What typically happens?","options":["Both writes are sent at once because they fit in one MSS","The body waits until the server's delayed ACK for the header arrives, adding up to the delayed-ACK timeout to each request","The server discards the header because it is smaller than the MSS","Nagle sends the body first since it is larger"],"answer":1,"explanation":"Nagle holds small data while earlier data is unacknowledged, and the server delays its ACK hoping to piggyback on a reply it cannot produce without the body. The deadlock lasts until the delayed-ACK timer fires; the fix is one write (or TCP_NODELAY).","difficulty":"hard","source":"Product-company placement"},
  {"id":"cs-computer-networks-482","question":"A page has a base HTML file and 6 small embedded images on the same server. The RTT is 20 ms and transmission times are negligible. With persistent HTTP/1.1 WITHOUT pipelining (one connection), how long does it take from starting the TCP handshake until the last image arrives?","options":["280 ms","60 ms","160 ms","120 ms"],"answer":2,"explanation":"One RTT for the handshake, then each of the 7 objects needs its own request–response RTT: 8 × 20 = 160 ms. 280 ms is non-persistent (2 RTT per object), 60 ms is persistent with pipelining, and 120 ms is non-persistent with 3 parallel connections.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-483","question":"The bit string 10111001 is sent once with NRZ-I (a level transition at the start of every 1 bit, none for a 0, counting the transition at the start of the first bit) and once with Manchester coding (counting mid-bit transitions and any transitions needed at bit boundaries, but not before the first bit). How many signal transitions does each produce?","options":["NRZ-I 3, Manchester 11","NRZ-I 5, Manchester 8","NRZ-I 5, Manchester 11","NRZ-I 5, Manchester 12"],"answer":2,"explanation":"NRZ-I changes level once per 1 bit: five 1s give 5 transitions. Manchester has 8 mid-bit transitions plus one boundary transition wherever two adjacent bits are equal (1-1, 1-1, 0-0), so 8 + 3 = 11. Counting the 0s (3) is the NRZ-S trap.","difficulty":"moderate","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-484","question":"A token ring has a circumference of 2 km, 50 stations each adding a 1-bit delay, a data rate of 16 Mbps and a signal speed of 2 × 10⁸ m/s. What is the ring latency expressed in bits?","options":["160 bits","210 bits","260 bits","130 bits"],"answer":1,"explanation":"Propagation round the ring takes 2000 / (2 × 10⁸) = 10 µs, which is 10 µs × 16 Mbps = 160 bits; the 50 station delays add 50 bits, giving 210 bits. 160 ignores the stations and 260 assumes 2 bits per station.","difficulty":"hard","source":"GATE CS · BARC"},
  {"id":"cs-computer-networks-485","question":"Wireless host H sends an IP datagram to a server on the Internet. H is associated with access point AP, which is bridged to an Ethernet LAN whose first-hop router interface is R. In the 802.11 data frame from H to AP, what do Address 1, Address 2 and Address 3 hold?","options":["H, AP, R","AP, R, H","R, H, AP","AP, H, R"],"answer":3,"explanation":"Address 1 is the immediate receiver (the AP), Address 2 the transmitter (H) and Address 3 the MAC the AP must forward to on the wired side (router interface R). The AP later builds an Ethernet frame with destination R and source H.","difficulty":"very-hard","source":"GATE CS · Cisco / networking placement"},
  {"id":"cs-computer-networks-486","question":"A binary code has length 10 and must correct every single-bit error. What upper limit does the Hamming (sphere-packing) bound place on the number of codewords?","options":["93","64","102","512"],"answer":0,"explanation":"Each codeword needs a decoding sphere of 1 + 10 = 11 words, so M ≤ 2¹⁰ / 11 = 93.09, i.e. at most 93. A shortened Hamming code actually reaches 64 (6 data bits), which is achievable but is not the bound; 102 forgets the codeword itself in the sphere.","difficulty":"very-hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-487","question":"A 7-bit cyclic code uses the generator x³ + x + 1. Bits are indexed by powers of x, from x⁶ (leftmost) down to x⁰ (rightmost). A received word gives the remainder (syndrome) 110 when divided by the generator. Assuming exactly one bit is in error, which bit is it?","options":["The x⁴ bit, third from the left","The x¹ bit, second from the right","The x² bit, fifth from the left","The x⁶ bit, the leftmost one"],"answer":0,"explanation":"A single error at xⁱ leaves the syndrome xⁱ mod (x³ + x + 1). Working up: x³ → 011, x⁴ = x·x³ → x² + x = 110. So the x⁴ bit (third from the left) is wrong; this code is the cyclic (7, 4) Hamming code, which can locate single errors.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-488","question":"A link has a = propagation delay / frame transmission time = 2, and each frame is lost independently with probability 0.2 (ACKs never lost). The window is large enough to keep the pipe full. Using the model in which every loss makes Go-Back-N resend 1 + 2a frames, what are the link utilisations of Go-Back-N and Selective Repeat?","options":["GBN 0.16, SR 0.80","GBN 0.80, SR 0.80","GBN 0.44, SR 0.80","GBN 0.44, SR 0.64"],"answer":2,"explanation":"GBN: U = (1 − p) / (1 + 2ap) = 0.8 / 1.8 ≈ 0.44. SR resends only the lost frame, so U = 1 − p = 0.80. 0.16 = 0.8 / 5 is the stop-and-wait figure, and 0.64 squares the success probability.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-489","question":"Stop-and-wait: a frame takes 1 ms to transmit and the one-way propagation delay is 4 ms (ACK time negligible). Each data frame is lost with probability 0.25; ACKs are never lost. After a loss the sender waits a 12 ms timeout, measured from the end of transmission, and resends. What is the expected time to deliver one frame successfully?","options":["12.00 ms","13.33 ms","12.25 ms","17.33 ms"],"answer":1,"explanation":"A successful attempt costs 1 + 8 = 9 ms and a failed one 1 + 12 = 13 ms. The expected number of failures before success is p/(1 − p) = 1/3, so E[T] = 9 + 13/3 ≈ 13.33 ms. 12 ms (9/0.75) wrongly charges failures at the success cost.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-490","question":"A sliding-window protocol uses 3-bit sequence numbers with sender window Ws and receiver window Wr. Which (Ws, Wr) combination can make the receiver accept an old duplicate as new data?","options":["Ws = 7, Wr = 1","Ws = 6, Wr = 2","Ws = 4, Wr = 4","Ws = 5, Wr = 4"],"answer":3,"explanation":"Correctness needs Ws + Wr ≤ 2ᵏ = 8. 7 + 1 (Go-Back-N), 6 + 2 and 4 + 4 (Selective Repeat) all fit, but 5 + 4 = 9 lets a retransmitted old frame fall inside the receiver's advanced window.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-491","question":"Selective Repeat with individual (non-cumulative) ACKs and window 4 sends frames 0–3. All four arrive; ACKs 0, 1 and 3 arrive, but ACK 2 is lost. What happens next?","options":["Nothing is resent, because ACK 3 implicitly confirms frame 2","Frames 2 and 3 are resent when the timer for frame 2 expires","Only frame 2 is resent on its timeout; the receiver discards the duplicate and ACKs it again","The receiver sends a NAK for frame 2, and then the sender resends frames 2 and 3"],"answer":2,"explanation":"In SR each frame has its own timer and an ACK confirms only that frame, so frame 2 alone is retransmitted. The receiver has already delivered it, so it drops the copy but must re-ACK it or the sender would retry forever. With cumulative ACKs (Go-Back-N) ACK 3 would have covered frame 2.","difficulty":"hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-492","question":"On one switch, host A is set as 192.168.1.100/25 and host B as 192.168.1.200/24; both use the router 192.168.1.1 as gateway, and the router is 192.168.1.1/24. Hosts answer ARP for their own address whatever the sender's subnet. How do packets travel between A and B?","options":["A to B goes through the router; B to A goes directly over the LAN","Both directions go directly, since the hosts share one switch","Both directions go through the router, since the masks differ","A to B goes directly; B to A goes through the router"],"answer":0,"explanation":"With /25, A's subnet is .0–.127, so .200 looks remote and A frames the packet to the gateway's MAC. B's /24 includes .100, so B ARPs for A and sends directly. The asymmetry is the classic symptom of a wrong mask.","difficulty":"hard","source":"GATE CS · Cisco / networking placement"},
  {"id":"cs-computer-networks-493","question":"A subnet's directed broadcast address is 172.16.47.255 and it offers exactly 4094 usable host addresses. What is its network address?","options":["172.16.40.0","172.16.44.0","172.16.0.0","172.16.32.0"],"answer":3,"explanation":"4094 usable hosts means 12 host bits, a /20, so the third octet moves in blocks of 16. 47 lies in 32–47, giving 172.16.32.0/20. 172.16.40.0 is what a /21 would give and 172.16.44.0 a /22.","difficulty":"moderate","source":"GATE CS · CCNA-style placement"},
  {"id":"cs-computer-networks-494","question":"For slotted ALOHA, which offered loads G (frames per slot) give a throughput of exactly 0.1 successful frames per slot?","options":["About 0.130 and about 1.27","About 0.112 and about 3.58","Only about 0.112, since throughput has a single solution","About 0.100 and about 10.0"],"answer":1,"explanation":"Solve G e^(−G) = 0.1: the curve rises to 1/e at G = 1 and then falls, so there are two roots, G ≈ 0.112 (light load) and G ≈ 3.58 (heavy load, mostly collisions). 0.130 and 1.27 solve the pure-ALOHA equation G e^(−2G) = 0.1.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-495","question":"Ten OSPF routers share one Ethernet segment. How many full adjacencies form if every router peers with every other, and how many when a DR and a BDR are elected?","options":["45 and 17","45 and 9","90 and 18","10 and 2"],"answer":0,"explanation":"Full mesh: 10 × 9 / 2 = 45. With a DR and BDR, each of the other 8 routers is adjacent to both (16), plus the DR–BDR adjacency, so 2n − 3 = 17. 9 counts only adjacencies to the DR.","difficulty":"hard","source":"GATE CS · Cisco / networking placement"},
  {"id":"cs-computer-networks-496","question":"How many of the following statements about router switching fabrics are correct?\n1. With 8 input ports of 10 Gbps each, the fabric must move at least 80 Gbps to avoid queuing at the inputs.\n2. Head-of-line blocking occurs when a packet at the front of an input queue waits for a busy output and blocks packets behind it bound for idle outputs.\n3. Under uniform random traffic with FIFO input queues and large N, head-of-line blocking caps throughput near 58.6%.\n4. A fabric N times faster than one line removes the need for any output queues.","options":["1","2","4","3"],"answer":3,"explanation":"1, 2 and 3 are standard results (the 2 − √2 ≈ 58.6% saturation limit). Statement 4 is false: a fast fabric moves the queue to the output, because several inputs can still target one output faster than its line can drain.","difficulty":"very-hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-497","question":"A core router link runs at 10 Gbps, the typical RTT is 200 ms and about 10,000 long-lived TCP flows share it. What buffer does the classic rule (RTT × C) suggest, and what does the small-buffer rule (RTT × C / √N) suggest?","options":["250 MB and 25 MB","250 MB and 2.5 MB","2 Gb and 200 kb","250 MB and 25 KB"],"answer":1,"explanation":"RTT × C = 0.2 s × 10 Gbps = 2 Gb = 250 MB. Dividing by √10,000 = 100 gives 20 Mb = 2.5 MB. 25 KB divides by N rather than √N, and 25 MB slips a factor of 10.","difficulty":"very-hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-498","question":"Why does a virtual-circuit network change the VC number of a packet at every switch instead of keeping one number end to end?","options":["Each link then picks numbers locally, so no network-wide agreement on a free number is needed","Changing the number lets each switch encrypt the circuit with a fresh key on every hop","A fresh number on each hop lets the destination reorder packets that arrive out of sequence","The VC number must grow at each hop so that it can act as a hop counter like TTL"],"answer":0,"explanation":"A VC number only has to be unique on one link, and each switch's table maps (in-port, in-VC) to (out-port, out-VC). One global number would need every switch on the path to agree on a value that is free on all its links, which is slow and wasteful.","difficulty":"moderate","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-499","question":"Two TCP hosts perform a simultaneous open: each sends a SYN to the other before receiving one. How many segments are exchanged to set up the connection, and through which states does each side pass?","options":["3 segments; SYN_SENT then ESTABLISHED","4 segments; LISTEN, SYN_RCVD, then ESTABLISHED","4 segments; SYN_SENT, SYN_RCVD, then ESTABLISHED","3 segments; SYN_SENT, SYN_RCVD, then ESTABLISHED"],"answer":2,"explanation":"Each side sends SYN (2 segments) and moves to SYN_SENT; on receiving the other's SYN it goes to SYN_RCVD and sends SYN+ACK (2 more). When each SYN+ACK arrives, both enter ESTABLISHED. Neither side passes through LISTEN, and four segments are needed rather than three.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-500","question":"Client A sends FIN to server B, and B ACKs it but has not yet closed. How many of these are correct?\n1. A is in FIN_WAIT_2 and B is in CLOSE_WAIT.\n2. B may still send data to A.\n3. A must keep acknowledging data that B sends.\n4. A may still send new data to B on this connection.","options":["1","3","2","4"],"answer":1,"explanation":"After its FIN is ACKed, A sits in FIN_WAIT_2 while B is in CLOSE_WAIT (1). The connection is half-closed: B can keep sending (2) and A must ACK it (3). A gave up the right to send data when it sent FIN, so 4 is false.","difficulty":"hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-501","question":"On a 40 Gbps path a TCP connection's 32-bit sequence space can wrap within the network's maximum segment lifetime, so an old delayed segment could carry an apparently valid sequence number. Which mechanism lets the receiver reject such a segment?","options":["Selective acknowledgement (SACK) blocks naming the bytes already received","The window-scale option, which widens the sequence-number field to 46 bits","PAWS, which discards segments whose timestamp option value is older than the latest one seen","Karn's algorithm, which ignores RTT samples taken from retransmitted segments"],"answer":2,"explanation":"Protection Against Wrapped Sequences (RFC 7323) uses the monotonically increasing timestamp in each segment: one with an older timestamp than recently accepted is dropped. Window scaling changes only the window field, not the sequence space.","difficulty":"very-hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-502","question":"Two HTTPS sites, a.example and b.example, share one IP address and port 443, each with its own certificate. How does the server know which certificate to present?","options":["From the Host header of the first HTTP request on the connection","From the Server Name Indication the client sends in its TLS ClientHello","From the DNS query, which the server sees before the TCP handshake begins","From the client's source port, which browsers pick per site being visited"],"answer":1,"explanation":"The certificate is sent during the TLS handshake, before any HTTP bytes, so the Host header is not available yet. SNI carries the hostname in the ClientHello so the server can choose. The Host header still selects the virtual host for plain HTTP.","difficulty":"hard","source":"GATE CS · product-company placement"},
  {"id":"cs-computer-networks-503","question":"A download of a 10,000,000-byte file over HTTP broke after the first 4,000,000 bytes (bytes 0 to 3,999,999) arrived. To resume, which request header does the client send, and what response does a supporting server give?","options":["Range: bytes=4000000- ; 206 with Content-Range: bytes 4000000-9999999/10000000","Range: bytes=4000001- ; 206 with Content-Range: bytes 4000001-10000000/10000000","Range: bytes=4000000- ; 200 with Content-Range: bytes 4000000-10000000/10000000","Range: bytes=3999999- ; 206 with Content-Range: bytes 3999999-9999999/10000000"],"answer":0,"explanation":"Byte ranges are zero-based and inclusive, so the next needed byte is 4,000,000 and the last is 9,999,999. A partial response uses 206 Partial Content; 200 would mean the whole body is sent.","difficulty":"hard","source":"GATE CS · product-company placement"},
  {"id":"cs-computer-networks-504","question":"In an SMTP session between two mail servers, in which order are these commands sent?\nP. DATA   Q. RCPT TO   R. EHLO   S. MAIL FROM   T. QUIT","options":["R, Q, S, P, T","S, R, Q, P, T","R, S, P, Q, T","R, S, Q, P, T"],"answer":3,"explanation":"The client greets (EHLO), names the envelope sender (MAIL FROM), then each recipient (RCPT TO), then sends the message after DATA, ending it with a line holding a single dot, and finally QUIT.","difficulty":"moderate","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-505","question":"A system identifies records by a 64-bit hash. Roughly how many random records must be hashed before the chance of at least one collision reaches about 50%?","options":["About 2³² (around 5 × 10⁹)","About 2⁶³ (around 9 × 10¹⁸)","About 2⁶⁴ (around 1.8 × 10¹⁹)","About 2¹⁶ (around 65,000)"],"answer":0,"explanation":"By the birthday bound a collision becomes likely after about 1.18 × √(2⁶⁴) ≈ 5 × 10⁹ items, i.e. near 2³². 2⁶³ is the effort to hit one particular hash value (a second preimage), a much harder goal.","difficulty":"hard","source":"GATE CS · security placement"},
  {"id":"cs-computer-networks-506","question":"Alice and Bob run plain Diffie–Hellman with no authentication of the exchanged values. Mallory sits on the path and can modify messages. What can she achieve?","options":["Nothing useful, because the shared key itself is never sent over the wire","Only block or delay the exchange, since she cannot compute g^ab herself","Share one key with Alice and another with Bob, and relay traffic she can read","Recover Alice's secret exponent from g^a quickly, then derive the session key"],"answer":2,"explanation":"Mallory replaces g^a and g^b with her own g^m, so she shares g^am with Alice and g^bm with Bob and relays everything. Discrete log stays hard; the weakness is the missing authentication, which TLS fixes by signing the DH share.","difficulty":"moderate","source":"GATE CS · security placement"},
  {"id":"cs-computer-networks-507","question":"Host H is set as 10.1.5.20 with mask 255.255.0.0, but the network is really split into /24 subnets joined by router R. H pings 10.1.200.7, which sits on another /24 behind R, and the ping succeeds. What makes this work?","options":["H's default gateway entry routes the packet, since the destination is off-subnet","R answers H's ARP request for 10.1.200.7 with R's own MAC (proxy ARP) and forwards the packet","The switch floods the ICMP packet to every subnet because the destination MAC is unknown","10.1.200.7 replies to H's broadcast ARP directly, because ARP crosses routers"],"answer":1,"explanation":"Because of its wide mask H thinks the destination is on-link and ARPs for it. ARP broadcasts do not cross routers, so only proxy ARP on R (replying with its own MAC for addresses it can reach) lets the frame reach R, which then routes it.","difficulty":"hard","source":"GATE CS · Cisco / networking placement"},
  {"id":"cs-computer-networks-508","question":"Which SNMP message does an agent send without first being polled, and to which UDP port does it normally go?","options":["GetResponse, to UDP port 161","Trap, to UDP port 161","SetRequest, to UDP port 162","Trap, to UDP port 162"],"answer":3,"explanation":"Agents listen on 161 for Get/Set requests from the manager; unsolicited event notifications (Traps, and Informs in v2c/v3) go to the manager on port 162. A GetResponse is only a reply to a request.","difficulty":"moderate","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-509","question":"Frames take 1 ms to transmit and the one-way propagation delay is 10 ms (ACKs negligible, no errors). For Go-Back-N to reach at least 60% link utilisation, what is the smallest window and the fewest sequence-number bits that support it?","options":["Window 13 with 5-bit sequence numbers","Window 12 with 4-bit sequence numbers","Window 13 with 4-bit sequence numbers","Window 21 with 5-bit sequence numbers"],"answer":2,"explanation":"One cycle is 1 + 2a = 21 frame times, so U = W/21 ≥ 0.6 needs W ≥ 12.6, i.e. 13. Go-Back-N needs W ≤ 2ᵏ − 1, and 2⁴ − 1 = 15 suffices. 5 bits applies the Selective Repeat rule (W ≤ 2ᵏ⁻¹); 12 gives only 57%.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-510","question":"A source must be allowed bursts of 2 s at its peak rate of 25 Mbps, and a token bucket refilling at 5 Mbps polices it. What is the smallest bucket capacity that lets a full burst through when the bucket starts full?","options":["50 Mb","40 Mb","10 Mb","30 Mb"],"answer":1,"explanation":"During a burst of length S the bucket must supply what the refill cannot: C = S(M − ρ) = 2 × (25 − 5) = 40 Mb. 50 Mb ignores the tokens added during the burst, and 10 Mb is just S × ρ.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-511","question":"A 1 Gbps half-duplex CSMA/CD network uses a 512-byte minimum frame and signals travel at 2 × 10⁸ m/s. Considering propagation only, what is the longest cable on which every collision is still detected before a minimum frame finishes?","options":["819.2 m","51.2 m","204.8 m","409.6 m"],"answer":3,"explanation":"The frame time 4096 bits / 1 Gbps = 4.096 µs must cover the round trip 2L/v, so L ≤ 4.096 µs × 2 × 10⁸ / 2 = 409.6 m. 819.2 m forgets the round trip, and 51.2 m uses a 512-bit (not byte) frame.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-512","question":"A recursive resolver has an empty cache apart from the root hints. A client asks for the A record of www.a.com, which is a CNAME for cdn.b.net. Every referral includes glue, and a.com's server is not authoritative for b.net. How many queries does the resolver send to authoritative servers?","options":["6","5","3","4"],"answer":0,"explanation":"Root → com → a.com yields the CNAME (3 queries). The .com referral does not help with .net, so it asks the root again, then the net servers, then b.net's server (3 more): 6 in all. Answering 5 wrongly assumes the root step can be skipped.","difficulty":"very-hard","source":"GATE CS · product-company placement"},
  {"id":"cs-computer-networks-513","question":"A bank's session cookie is set with SameSite=Lax. While logged in, the user visits evil.example, which (1) auto-submits a hidden POST form to the bank, (2) shows a link to the bank that the user clicks, and (3) loads an image from a bank URL. In which cases does the browser send the cookie?","options":["Only (2), the top-level GET navigation","(1) and (2), because both are navigations","(2) and (3), because both are GET requests","All three, because the cookie belongs to the bank"],"answer":0,"explanation":"Lax sends the cookie on cross-site requests only for top-level navigations with a safe method such as GET. A cross-site POST (the classic CSRF vector) and a cross-site sub-resource like an image are sent without it.","difficulty":"hard","source":"GATE CS · product-company placement"},
  {"id":"cs-computer-networks-514","question":"A router has four equal-cost paths to a destination and uses ECMP. Why does it usually choose the path by hashing each packet's 5-tuple rather than sending packets round-robin?","options":["Hashing spreads load more evenly than round-robin when all packets are equal","So that every packet of one flow takes the same path and TCP does not see reordering","Round-robin would break the IP checksum, which covers the outgoing interface","Hashing lets the router skip the longest-prefix lookup for the remaining packets"],"answer":1,"explanation":"Per-packet spraying over paths of slightly different delay reorders a flow's packets, which TCP treats as loss (duplicate ACKs). Per-flow hashing keeps each flow on one path; the price is that a few heavy flows can unbalance the links.","difficulty":"hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-515","question":"An IPv6 packet has Payload Length = 1240 and carries one 8-byte Fragment extension header before the upper-layer data. What is the total packet size, and how many bytes follow the extension header?","options":["1240 bytes total; 1192 bytes follow","1280 bytes total; 1240 bytes follow","1288 bytes total; 1240 bytes follow","1280 bytes total; 1232 bytes follow"],"answer":3,"explanation":"Payload Length excludes the fixed 40-byte header but includes extension headers, so the packet is 40 + 1240 = 1280 bytes and 1240 − 8 = 1232 bytes follow. Treating it like IPv4 Total Length (which includes the header) gives 1192.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-516","question":"Match each IPv6 address with its type.\nP. ff02::1   Q. fe80::1   R. fd12:3456::1   S. ::1\n1. Loopback   2. Link-local unicast   3. All-nodes multicast on the link   4. Unique local unicast","options":["P-3, Q-2, R-4, S-1","P-2, Q-3, R-4, S-1","P-3, Q-4, R-2, S-1","P-4, Q-2, R-3, S-1"],"answer":0,"explanation":"ff00::/8 is multicast and ff02::1 is all nodes on the link; fe80::/10 is link-local; fc00::/7 (in practice fd00::/8) is unique local; ::1 is loopback.","difficulty":"moderate","source":"GATE CS · CCNA-style placement"},
  {"id":"cs-computer-networks-517","question":"Three PCs behind one NAT router ping the same public server at the same time. ICMP Echo messages have no port numbers. How does the NAT deliver each Echo Reply to the right PC?","options":["It keeps one ping at a time per server and queues the others until a reply returns","It maps on the ICMP query Identifier field, rewriting it if needed, as it would a port","It gives each PC its own public address taken from a pool for ICMP traffic only","It matches the replies by IP Identification field, which the server copies back"],"answer":1,"explanation":"For ICMP query messages NAT treats the 16-bit Identifier as the 'port': it records (inside address, identifier) and may rewrite the identifier to keep it unique. The IP Identification field is set fresh by the replying host, so it cannot be used.","difficulty":"hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-518","question":"An 802.1Q trunk is configured with native VLAN 1 on switch A but native VLAN 99 on switch B. What happens to an untagged frame that A sends on the trunk from VLAN 1?","options":["B drops it, because a trunk carries only tagged frames","B tags it with VLAN 1, since the original VLAN is recorded in the frame's FCS","B places it in VLAN 99, so traffic leaks between VLAN 1 and VLAN 99","B floods it to every VLAN, because its VLAN cannot be determined"],"answer":2,"explanation":"Native-VLAN frames cross a trunk untagged, and the receiver assigns untagged frames to its own native VLAN. A mismatch therefore bridges two different VLANs, which is why switches warn about it.","difficulty":"hard","source":"Cisco / networking placement"},
  {"id":"cs-computer-networks-519","question":"Why does 802.11 use collision avoidance with ACKs rather than the collision detection used by classic Ethernet?","options":["A transmitting radio cannot hear weak signals over its own, and collisions occur at the receiver, which the sender may not hear","Radio links have negligible propagation delay, so once carrier is sensed idle two stations can never start sending at the same moment","Wireless frames are so short that a collision would finish before the sender's receiver could measure any change in signal level","802.11 radios are full-duplex and each station transmits on its own frequency, which makes collision detection unnecessary"],"answer":0,"explanation":"A station's own transmission swamps any distant signal, so it cannot detect collisions while sending, and with hidden terminals the collision happens at the receiver only. Hence random backoff before sending and an explicit ACK after.","difficulty":"moderate","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-520","question":"Ten (7, 4) Hamming codewords are written as rows of a 10 × 7 array, and the array is sent column by column. What is the longest burst of consecutive bit errors that is always corrected?","options":["7 bits","1 bit","10 bits","70 bits"],"answer":2,"explanation":"Consecutive transmitted bits belong to different rows, so a burst of up to 10 bits puts at most one error in each codeword, which each Hamming codeword corrects. An 11-bit burst puts two errors into one codeword.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-521","question":"A CDN maps www.shop.example (a CNAME into the CDN's domain) to a nearby server cluster through its own DNS. A user in Chennai uses a public resolver whose only server is in Frankfurt, and no EDNS Client Subnet is sent. Which cluster is the user likely to get, and why?","options":["Chennai, because the CDN looks up the user's IP from the TCP connection","A random cluster, because CNAMEs disable location-based answers","Chennai, because the CNAME carries the user's location to the CDN","Frankfurt, because the CDN's DNS sees only the resolver's address"],"answer":3,"explanation":"DNS-based redirection decides before any TCP connection exists, using the source of the DNS query, which is the resolver. Without ECS the CDN picks a cluster near Frankfurt; ECS was added to pass part of the client's address.","difficulty":"hard","source":"GATE CS · product-company placement"},
  {"id":"cs-computer-networks-522","question":"Bob's textbook RSA key is p = 7, q = 17, e = 5, d = 77. He signs the message m = 10 without hashing. What signature does he send, and how does Alice check it?","options":["s = 40; Alice checks that 40^77 mod 119 = 10","s = 96; Alice checks that 96^77 mod 119 = 10","s = 64; Alice checks that 64^5 mod 96 = 10","s = 96; Alice checks that 96^5 mod 119 = 10"],"answer":3,"explanation":"n = 119 and signing uses the private key: s = 10^77 mod 119 = 96. Anyone verifies with the public key: 96^5 mod 119 = 10. 40 = 10^5 mod 119 is encryption with the public key, and 64 wrongly reduces mod φ(n) = 96.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-523","question":"How many of these statements about DNSSEC are correct?\n1. It lets a resolver verify that records really come from the zone owner and were not altered.\n2. It encrypts queries so that on-path observers cannot see which names are looked up.\n3. A zone's key is vouched for by a DS record in the parent zone, forming a chain of trust up to the root.\n4. It can prove that a name does not exist, using signed NSEC or NSEC3 records.","options":["3","2","4","1"],"answer":0,"explanation":"Statements 1, 3 and 4 are correct. DNSSEC gives origin authentication and integrity, including signed denial of existence, but no confidentiality; privacy needs DNS over TLS or HTTPS.","difficulty":"hard","source":"GATE CS · security placement"},
  {"id":"cs-computer-networks-524","question":"A satellite link runs at 1 Mbps with 1000-bit frames and a one-way propagation delay of 270 ms (ACKs negligible, no errors). What utilisation does Go-Back-N reach with 3-bit sequence numbers, and with 7-bit ones?","options":["About 2.6% and about 47%","About 1.3% and about 23.5%","About 1.5% and about 25.4%","About 1.3% and about 24%, then 100% with 8 bits"],"answer":1,"explanation":"One cycle is 1 + 2a = 1 + 540 = 541 frame times. Maximum windows are 7 and 127, so U = 7/541 ≈ 1.3% and 127/541 ≈ 23.5%. Using a one-way cycle (271) doubles the figures, and even 8 bits (window 255) is far below 541.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-525","question":"How many of these statements about full-duplex switched Ethernet (each host on its own switch port) are correct?\n1. CSMA/CD is turned off, since a link cannot have collisions.\n2. A host can send and receive at the same time at the full rate.\n3. The 64-byte minimum frame is kept for compatibility, not to detect collisions.\n4. Cable length is still limited by the collision round-trip time, not by signal quality.","options":["1","2","3","4"],"answer":2,"explanation":"1, 2 and 3 hold. With no shared medium there is no collision window, so the length limit (100 m for twisted pair) comes from attenuation and signal quality, which makes 4 false.","difficulty":"hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-526","question":"A softphone must find which host and port serve SIP over TCP for the domain example.com, with priorities and load weights among several servers. Which DNS record type provides this?","options":["MX, queried for example.com","SRV, queried for _sip._tcp.example.com","NAPTR, queried for sip.example.com","TXT, queried for _sip.example.com"],"answer":1,"explanation":"An SRV record at _service._proto.domain gives priority, weight, port and target host. MX is only for mail, and gives no port.","difficulty":"moderate","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-527","question":"Match each email-authentication mechanism with what it does.\nP. SPF   Q. DKIM   R. DMARC\n1. Signs selected headers and the body with a key published in the sender domain's DNS.\n2. Lists which IP addresses may send mail for the envelope-sender domain.\n3. Publishes the domain's policy for mail that fails checks and requires alignment with the visible From domain.","options":["P-1, Q-2, R-3","P-2, Q-3, R-1","P-2, Q-1, R-3","P-3, Q-1, R-2"],"answer":2,"explanation":"SPF authorises sending IPs for the envelope (MAIL FROM) domain, DKIM attaches a domain signature checked with a public key in DNS, and DMARC ties the result to the From header and tells receivers to reject, quarantine or allow.","difficulty":"hard","source":"Product-company placement · security"},
  {"id":"cs-computer-networks-528","question":"A 1 MHz channel has SNR = 15. The bandwidth is doubled to 2 MHz while the noise power per hertz and the signal power stay the same, so the SNR halves to 7.5. What is the new Shannon capacity?","options":["About 6.2 Mbps","8 Mbps","4 Mbps","About 5.8 Mbps"],"answer":0,"explanation":"Before: 1 × log₂16 = 4 Mbps. After: 2 × log₂(1 + 7.5) ≈ 2 × 3.09 ≈ 6.2 Mbps; capacity grows but less than double because the extra bandwidth admits more noise. 5.8 Mbps forgets the '1 +'.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-529","question":"Five 100 kHz voice channels are multiplexed by FDM with a 10 kHz guard band between each adjacent pair (none at the outer edges). What is the minimum bandwidth of the link?","options":["550 kHz","540 kHz","500 kHz","560 kHz"],"answer":1,"explanation":"Five channels need 5 × 100 = 500 kHz, and five channels have four gaps between them, adding 4 × 10 = 40 kHz: 540 kHz. 550 kHz counts five guard bands.","difficulty":"moderate","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-530","question":"A company compares signature-based and anomaly-based intrusion detection. Which statement is correct?","options":["Signature-based detection catches new attacks well but flags far more normal traffic as hostile","Anomaly-based detection needs no training period, because it relies on a vendor's attack list","Anomaly-based detection can flag never-seen attacks but tends to raise more false positives","Both kinds miss attacks only when the traffic travels inside an encrypted TLS session"],"answer":2,"explanation":"Signature IDS matches known patterns: few false alarms but blind to zero-days. Anomaly IDS learns a baseline of normal behaviour and flags deviations, so it can catch novel attacks but also flags unusual yet legitimate traffic.","difficulty":"hard","source":"Security placement · networking"},
  {"id":"cs-computer-networks-531","question":"A site wants /api/* requests sent to one server pool and /static/* to another, and all traffic arrives over HTTPS. What must the load balancer do?","options":["Work at layer 4 and route on the destination port, since both paths use 443","Work at layer 7 and terminate (or decrypt) TLS so it can read the URL path","Work at layer 3 and route on the client's IP address, using a hash","Work at layer 4 and read the path from the SNI field of the ClientHello"],"answer":1,"explanation":"The path is inside the encrypted HTTP request, so only a layer-7 balancer that ends the TLS session can see it. SNI carries just the hostname, and both paths share one host and port.","difficulty":"hard","source":"Product-company placement · system design"},
  {"id":"cs-computer-networks-532","question":"The Internet checksum is computed over the three bytes 01 02 03 (hex). As the standard requires for an odd length, the data is padded with one zero byte. What checksum is sent?","options":["0xFEFA","0xFBFD","0x0402","0xFDFB"],"answer":1,"explanation":"Padding goes at the end, so the 16-bit words are 0x0102 and 0x0300; their sum is 0x0402 and its ones' complement is 0xFBFD. Padding at the front (0x0003) gives 0xFEFA, and 0x0402 forgets to complement.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-533","question":"A link-state network sets each link's cost to the traffic it currently carries. Two equal routes connect the same pair of regions, and after each route computation most traffic moves to the cheaper route. What is the likely result?","options":["Routes settle after one recomputation, because Dijkstra always converges","Traffic splits evenly at once, because both costs quickly become equal","Routes oscillate, with traffic flipping between the two paths","Count-to-infinity begins, because the link costs keep climbing with no limit"],"answer":2,"explanation":"Load-dependent costs make the chosen path expensive at the next computation, so everyone switches back and forth. Fixes include not making costs depend on load, or randomising when routers rerun the algorithm. Count-to-infinity is a distance-vector problem.","difficulty":"hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-534","question":"Why does TCP wait for three duplicate ACKs, rather than one, before a fast retransmit?","options":["Because the first two duplicate ACKs are always lost as the queue overflows","Because the receiver sends duplicates only after its buffer is two segments full","Because one duplicate cannot be told apart from an ordinary window update","Because one or two duplicates often come from mild reordering, not a lost segment"],"answer":3,"explanation":"Any segment arriving out of order produces a duplicate ACK, and small reorderings are common, so one duplicate is weak evidence of loss. Three duplicates make loss likely enough to resend without waiting for the timeout.","difficulty":"moderate","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-535","question":"A 100,000-byte response is sent with MSS 1460 bytes over a path with plenty of bandwidth, no loss, no delayed ACKs and a large receive window. The request goes with the handshake's final ACK, and transmission time is ignored. From the client's SYN until the last byte arrives, how many RTTs pass with an initial window of 10 segments, and with an initial window of 1 segment?","options":["4 and 8","3 and 7","4 and 7","5 and 9"],"answer":0,"explanation":"The response needs ⌈100000/1460⌉ = 69 segments. Doubling from 10 gives 10 + 20 + 40 = 70 after 3 rounds; from 1, 1 + 2 + … + 64 = 127 needs 7 rounds (63 after 6 is too few). Adding 1 RTT for the handshake gives 4 and 8.","difficulty":"very-hard","source":"GATE CS · product-company placement"},
  {"id":"cs-computer-networks-536","question":"A shared cache stores a response from origin that carries Vary: Accept-Encoding. A later client asks for the same URL with a different Accept-Encoding value. What should the cache do?","options":["Serve the stored copy, because the URL alone is the cache key","Serve the stored copy and add a Warning header naming the encoding difference","Recompress the stored body into the new encoding and then serve it","Treat it as a miss unless it holds a variant stored for that Accept-Encoding"],"answer":3,"explanation":"Vary makes the listed request headers part of the cache key, so a gzip variant must not be served to a client that asked for identity or br. Ignoring Vary is a classic cause of browsers getting compressed bytes they cannot decode.","difficulty":"hard","source":"Product-company placement · web"},
  {"id":"cs-computer-networks-537","question":"A site's A record has a TTL of 86,400 s. The team will move the site to a new IP at 10:00 on Friday and wants every cache to pick up the change within about 5 minutes of the switch. What should they do?","options":["Lower the TTL to 300 s at least 24 hours before Friday 10:00, then change the address","Lower the TTL to 300 s at 10:00 on Friday together with the address change","Change the address on Friday and ask resolvers to obey a 300 s TTL from then on","Raise the TTL so the new record is cached for longer once resolvers fetch it"],"answer":0,"explanation":"Resolvers that fetched the record under the old TTL can keep it for up to 24 h. The short TTL must already be in all caches when the address changes, so it has to be published at least one old-TTL period earlier.","difficulty":"hard","source":"Product-company placement · DevOps"},
  {"id":"cs-computer-networks-538","question":"A bank sends Strict-Transport-Security: max-age=31536000 and is not on any browser's HSTS preload list. Which statement is correct?","options":["It protects even the first visit, because the browser reads the header before any TLS handshake","After one HTTPS visit the browser upgrades later http:// requests itself; a first HTTP visit can still be stripped","It lets the browser accept the site's self-signed or expired certificates without warning for a year","It forces the server to redirect every HTTP request, which by itself defeats SSL-stripping attacks"],"answer":1,"explanation":"HSTS is remembered from a response received over HTTPS; afterwards the browser never makes plain HTTP requests to the host and refuses certificate click-through. A first visit before any HSTS response is the gap that preload lists close.","difficulty":"hard","source":"Product-company placement · security"},
  {"id":"cs-computer-networks-539","question":"A bitmap image is encrypted with AES, and the ciphertext still shows the outline of the picture. Which mode of operation was used, and why?","options":["CBC, because each block is XORed with the previous ciphertext block","CTR, because the counter repeats every few blocks","ECB, because identical plaintext blocks give identical ciphertext blocks","GCM, because authentication tags leak the plaintext layout"],"answer":2,"explanation":"ECB encrypts each block independently with the same key, so repeated regions of the image map to repeated ciphertext. CBC and CTR mix in a chaining value or a unique counter, so identical blocks encrypt differently.","difficulty":"moderate","source":"GATE CS · security placement"},
  {"id":"cs-computer-networks-540","question":"A developer encrypts two different messages with the same one-time-pad key K: C1 = M1 ⊕ K and C2 = M2 ⊕ K. What can an eavesdropper holding C1 and C2 compute without knowing K?","options":["Nothing, because a one-time pad stays perfectly secret","K itself, by XORing C1 with C2 and reading off the result","M1 ⊕ M2, by XORing the two ciphertexts together","M1 alone, by XORing C1 with C2 and then with C1 again"],"answer":2,"explanation":"C1 ⊕ C2 = M1 ⊕ M2 because the key cancels. Guessing likely words in one message (crib-dragging) then exposes the other. Perfect secrecy holds only if the key is never reused.","difficulty":"hard","source":"GATE CS · security placement"},
  {"id":"cs-computer-networks-541","question":"A layer-2 switch carries an IPTV multicast stream. Without any special feature it floods the stream to every port in the VLAN. Which feature limits the stream to ports with interested receivers?","options":["IGMP snooping, learning group members from IGMP joins and leaves","Spanning Tree, which blocks every port that has no multicast receiver","Proxy ARP, which answers the group's ARP requests on behalf of receivers","Port security, which limits each port to one learned MAC address"],"answer":0,"explanation":"Multicast destination MACs are never learned as a source, so a plain switch floods them. With IGMP snooping the switch reads membership reports and forwards each group only to ports that joined it, plus the router port.","difficulty":"hard","source":"Cisco / networking placement"},
  {"id":"cs-computer-networks-542","question":"An AS with two upstream ISPs wants inbound traffic to prefer ISP A, so it advertises its prefix to ISP B with its own AS number repeated three extra times. Why does this work?","options":["It sets a higher local preference for the route inside ISP B's own network","A longer AS-path through B loses BGP's shorter-AS-path tie-break","It lowers the MED sent to B, which every AS on the Internet then compares","Routers drop routes whose AS-path contains repeats, so B's route disappears"],"answer":1,"explanation":"AS-path prepending lengthens the path seen through B, and many routers break ties on AS-path length. It is only a hint: an AS that sets a higher local preference for B still uses B. Repeats of the origin's own AS do not trigger loop rejection elsewhere.","difficulty":"very-hard","source":"Networking placement"},
  {"id":"cs-computer-networks-543","question":"In 802.11, SIFS = 10 µs, a CTS and an ACK each take 44 µs, and the data frame takes 1000 µs. Station X hears the CTS from the receiver but not the RTS. For how long after the end of the CTS does X set its NAV?","options":["1118 µs","1054 µs","1064 µs","1044 µs"],"answer":2,"explanation":"The CTS's duration field covers what follows it: SIFS + DATA + SIFS + ACK = 10 + 1000 + 10 + 44 = 1064 µs. 1118 µs is the RTS's duration field, which also includes a SIFS and the CTS.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-544","question":"VoIP packets are generated every 20 ms (at t = 0, 20, 40, 60, 80 ms) and suffer network delays of 50, 70, 45, 95 and 60 ms. The receiver plays the first packet p ms after it arrives and the rest every 20 ms after that. What is the smallest p for which no packet arrives after its playout time?","options":["95 ms","45 ms","25 ms","50 ms"],"answer":1,"explanation":"The first packet arrives at 50 ms, so packet i plays at 50 + p + 20i and arrives at 20i + dᵢ; it is late if dᵢ > 50 + p. The largest delay is 95 ms, so p ≥ 45 ms. 95 ms confuses the playout offset with the delay itself.","difficulty":"hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-545","question":"A 12 Mbps link uses weighted fair queueing with weights 3, 2 and 1 for classes X, Y and Z. What rate does each class get when all three are backlogged, and what do X and Y get when Z has nothing to send?","options":["6, 4, 2 Mbps; then 7.2 and 4.8 Mbps","4, 4, 4 Mbps; then 6 and 6 Mbps","6, 4, 2 Mbps; then 8 and 4 Mbps","6, 4, 2 Mbps; then 6 and 4 Mbps"],"answer":0,"explanation":"Backlogged classes share by weight: 12 × 3/6, 2/6 and 1/6 give 6, 4 and 2 Mbps. WFQ is work-conserving, so Z's share is redistributed in the ratio 3 : 2, giving 7.2 and 4.8 Mbps; 6 and 4 Mbps would waste capacity.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-546","question":"For how many prefix lengths from /20 to /30 (inclusive) is 10.17.83.191 the directed broadcast address of its subnet?","options":["6","3","4","5"],"answer":3,"explanation":"An address is a broadcast when all host bits are 1. The last octet 191 = 10111111 ends in six 1s and is preceded by a 0, so the host part may have at most 6 bits: prefixes /26 to /30, which is 5.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-547","question":"A load-test client makes 500 short TCP connections per second to one server IP and port, and the client closes each first. Its TIME_WAIT lasts 60 s, and its ephemeral port range is 32768–60999. Which statement is correct?","options":["It can sustain about 546 per second, so 500 per second is safe","It can sustain about 941 per second, since TIME_WAIT counts once per 30 s","It runs out of ports, since only about 470 new connections per second can be sustained","Ports are never a limit, because each connection has its own server-side socket"],"answer":2,"explanation":"To the same server IP and port, each new connection needs a distinct local port, and each stays in TIME_WAIT for 60 s. 28,232 ports / 60 s ≈ 470 per second, below 500. 546 per second assumes the range runs to 65535.","difficulty":"very-hard","source":"Product-company placement · networking"},
  {"id":"cs-computer-networks-548","question":"A SEC-DED memory code adds one overall parity bit to a Hamming code. On a read, the Hamming syndrome is non-zero but the overall parity check passes. What does the controller conclude?","options":["A single error in a data bit, which it corrects","A double error, which it flags as uncorrectable","A single error in the overall parity bit only","No error, since overall parity passed"],"answer":1,"explanation":"One error always flips overall parity. A non-zero syndrome with correct overall parity means an even number of errors, assumed to be two, which SEC-DED detects but cannot correct. A zero syndrome with failed parity means the parity bit itself flipped.","difficulty":"hard","source":"GATE CS · ISRO Scientist"},
  {"id":"cs-computer-networks-549","question":"On an office LAN, users suddenly receive addresses with an unknown gateway, while the real DHCP server logs that its pool is exhausted. Which defence addresses both problems?","options":["Port security, limiting each access port to a single learned MAC address","Spanning Tree BPDU guard, shutting any access port that sends BPDUs","Dynamic ARP inspection on every VLAN, checking each ARP reply against a list","DHCP snooping: trust server replies only on uplinks and rate-limit requests"],"answer":3,"explanation":"Pool exhaustion (DHCP starvation) followed by a rogue server is the attack. DHCP snooping drops OFFER/ACK messages arriving on untrusted ports and can rate-limit DISCOVERs; its binding table also feeds dynamic ARP inspection.","difficulty":"hard","source":"Cisco / networking placement · security"},
  {"id":"cs-computer-networks-550","question":"An attacker floods a switch with frames from thousands of random source MAC addresses. What happens, and which feature limits the damage?","options":["The MAC table fills, so unknown unicasts flood everywhere; port security limits it","The switch reboots and reloads its last saved table; storm control then restores it","Spanning Tree recalculates and blocks the attacker's port; BPDU guard then limits it","Every frame is dropped because its FCS no longer matches; VLAN tagging then limits it"],"answer":0,"explanation":"With its table full, the switch cannot learn genuine hosts and floods their traffic like a hub, so the attacker can sniff it. Port security caps learned MACs per port and shuts or restricts violating ports.","difficulty":"moderate","source":"Cisco / networking placement · security"},
  {"id":"cs-computer-networks-551","question":"An NTP client sends a request at t1 = 100 ms (client clock); the server receives it at t2 = 150 ms and replies at t3 = 152 ms (server clock); the reply arrives at t4 = 120 ms (client clock). What are the clock offset (server minus client) and the round-trip delay?","options":["Offset 50 ms, delay 20 ms","Offset 41 ms, delay 20 ms","Offset 41 ms, delay 18 ms","Offset 32 ms, delay 18 ms"],"answer":2,"explanation":"θ = ((t2 − t1) + (t3 − t4)) / 2 = (50 + 32) / 2 = 41 ms and δ = (t4 − t1) − (t3 − t2) = 20 − 2 = 18 ms. Using t4 − t1 alone for the delay forgets the server's 2 ms of processing.","difficulty":"very-hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-552","question":"An IPv6-only phone uses DNS64 and NAT64 with the well-known prefix 64:ff9b::/96 to reach an IPv4-only server at 192.0.2.33. What AAAA record does DNS64 synthesise?","options":["::ffff:c000:221","64:ff9b::c000:221","64:ff9b::192:2:33","2002:c000:221::"],"answer":1,"explanation":"DNS64 places the 32-bit IPv4 address in the low bits of the /96 prefix: 192.0.2.33 = c0 00 02 21, giving 64:ff9b::c000:221. ::ffff: is the IPv4-mapped form used inside a host's stack, and 2002::/16 is 6to4.","difficulty":"very-hard","source":"Networking placement"},
  {"id":"cs-computer-networks-553","question":"Which split of the 16-bit port space matches IANA's registry?","options":["Well-known 0–1023, registered 1024–49151, dynamic/private 49152–65535","Well-known 0–255, registered 256–1023, dynamic/private 1024–65535","Well-known 0–1023, registered 1024–32767, dynamic/private 32768–65535","Well-known 1–1024, registered 1025–49152, dynamic/private 49153–65535"],"answer":0,"explanation":"IANA defines system (well-known) ports 0–1023, user (registered) ports 1024–49151 and dynamic/private ports 49152–65535. Many Linux systems choose ephemeral ports from 32768–60999, which is an OS setting, not the IANA split.","difficulty":"moderate","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-554","question":"A switch port is set to 100 Mbps full duplex, but the attached server auto-negotiates and falls back to half duplex. Under load, what is typically seen?","options":["No errors, only lower throughput on both ends of the link","Collisions counted only on the switch, since it is full duplex","Late collisions on the server and FCS/CRC errors on the switch port","Link flapping, as each side resets the link every few seconds"],"answer":2,"explanation":"The half-duplex server senses collisions when the switch sends while it transmits, often after 64 bytes (late collisions), and aborts frames midway. The full-duplex switch never backs off and sees those truncated frames as CRC/runt errors.","difficulty":"very-hard","source":"Cisco / networking placement"},
  {"id":"cs-computer-networks-555","question":"A router's output queue uses RED instead of drop-tail. What problem does RED mainly address?","options":["It guarantees that no packet is dropped as long as the buffer still has space","It gives strict priority to short packets such as TCP ACKs and DNS queries","It removes the need for TCP congestion control at the end hosts on the path","It drops a few packets early, at random, so flows do not back off in lockstep"],"answer":3,"explanation":"Drop-tail drops from all flows at once when the buffer overflows, causing global synchronisation and a full, laggy queue. RED drops (or marks) with rising probability as the average queue grows, signalling a few flows early.","difficulty":"hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-556","question":"An 802.11 station uses CWmin = 15, doubling the contention window (as 2ᵏ(CWmin + 1) − 1) after each failed attempt, with a 9 µs slot. After three failed attempts, what is the window and the longest random backoff the station can choose?","options":["CW = 63; up to 567 µs","CW = 127; up to 1143 µs","CW = 120; up to 1080 µs","CW = 255; up to 2295 µs"],"answer":1,"explanation":"After k = 3 failures CW = 2³ × 16 − 1 = 127, so the backoff is 0–127 slots, at most 127 × 9 = 1143 µs. 63 is the window after two failures, and 120 simply multiplies 15 by 8.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-557","question":"An alternating-bit (stop-and-wait) sender sets its timeout to 0.75 × RTT by mistake; there is no loss. What happens?","options":["Frames are lost, because the receiver rejects any frame arriving before its previous ACK has left","The protocol deadlocks, because the sender keeps waiting for an ACK it has already received","Data reaches the application twice, because the receiver cannot recognise duplicate frames","Every frame is sent twice; duplicates are spotted by the sequence bit, so only efficiency suffers"],"answer":3,"explanation":"Every frame times out before its ACK returns and is resent. The 1-bit sequence number lets the receiver recognise the duplicate and only re-ACK it, and the sender ignores ACKs for frames it has finished. Correctness survives; efficiency does not.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-558","question":"A ping reply arrives with TTL = 52. Common operating systems start packets with TTL 64, 128 or 255. What is the most likely initial TTL, and how many routers did the reply cross?","options":["64, after 12 routers","128, after 76 routers","255, after 203 routers","64, after 13 routers"],"answer":0,"explanation":"Each router decrements TTL by one, and real Internet paths are far shorter than 76 hops, so the nearest default above 52 (64) is likely: 64 − 52 = 12 routers. The sending host itself does not decrement.","difficulty":"hard","source":"Networking placement"},
  {"id":"cs-computer-networks-559","question":"A G.711 VoIP call puts 20 ms of audio (160 bytes) into each packet, carried in RTP (12-byte header), UDP and IPv4 without options. What is the bandwidth of one direction at the IP layer?","options":["64 kbps","72 kbps","80 kbps","87.2 kbps"],"answer":2,"explanation":"Each packet is 160 + 12 + 8 + 20 = 200 bytes and 50 packets go per second, so 200 × 8 × 50 = 80 kbps. 64 kbps is the codec alone, and 87.2 kbps adds 18 bytes of Ethernet header and FCS.","difficulty":"hard","source":"Networking placement"},
  {"id":"cs-computer-networks-560","question":"For an 8 kHz audio stream sent in RTP with 20 ms of audio per packet, by how much does the RTP timestamp increase from one packet to the next, and how much does the sequence number increase?","options":["Timestamp by 20, sequence number by 1","Timestamp by 160, sequence number by 1","Timestamp by 160, sequence number by 160","Timestamp by 1, sequence number by 20"],"answer":1,"explanation":"The timestamp counts sampling-clock ticks: 8000 × 0.020 = 160 per packet. The sequence number counts packets, so it rises by 1 and lets the receiver detect loss and reordering separately from timing.","difficulty":"hard","source":"Networking placement"},
  {"id":"cs-computer-networks-561","question":"A TCP connection crosses a Wi-Fi link that corrupts about 2% of frames, with no link-layer retransmission. Throughput is far below the link rate although the network is not congested. Why, and what is the usual fix?","options":["TCP treats each loss as congestion and shrinks cwnd; link-layer retransmission hides the losses","UDP traffic on the same link takes priority over TCP, so moving to a separate Wi-Fi channel fixes it","The TCP checksum cannot detect radio errors, so corrupted data is passed up, and a larger MSS fixes it","Wi-Fi blocks TCP ACKs because they are short frames, so turning on delayed ACKs fixes it"],"answer":0,"explanation":"Standard TCP assumes loss means congestion, so random radio losses keep cutting cwnd. 802.11 therefore retransmits at the link layer, and some networks split the connection so the wireless hop has its own recovery.","difficulty":"hard","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-562","question":"In software-defined networking with OpenFlow, which statement is correct?","options":["Each switch still runs its own routing protocol and merely reports results to the controller","A central controller installs match-action rules in switches' flow tables","The controller forwards every data packet itself, so switches need no forwarding tables at all","OpenFlow replaces IP addressing with flow IDs that the controller assigns to each host"],"answer":1,"explanation":"SDN moves decisions to a controller that programs flow tables (match on header fields, then forward, drop, modify or send to the controller). Switches still forward packets at line rate; only unmatched packets go to the controller.","difficulty":"moderate","source":"GATE CS · networking placement"},
  {"id":"cs-computer-networks-563","question":"A data centre uses a k-ary fat-tree built from identical 8-port switches (k = 8). How many hosts can it connect, and how many switches does it use?","options":["64 hosts and 48 switches","512 hosts and 80 switches","128 hosts and 64 switches","128 hosts and 80 switches"],"answer":3,"explanation":"A k-ary fat-tree has k pods, each with k/2 edge and k/2 aggregation switches, plus (k/2)² core switches: 8 × 8 + 16 = 80 switches. Each edge switch serves k/2 hosts, giving k³/4 = 128 hosts. 512 is k³.","difficulty":"very-hard","source":"Product-company placement · networking"},
  {"id":"cs-computer-networks-564","question":"Why do large cloud data centres use VXLAN rather than only 802.1Q VLANs to separate tenants?","options":["VXLAN encrypts each tenant's frames end to end, which plain VLAN tags cannot do","VXLAN removes encapsulation overhead, so frames on the fabric get smaller than with VLANs","Its 24-bit ID allows about 16 million segments, carried over a routed IP/UDP network","VXLAN runs one Spanning Tree across every rack, which stops loops between tenants"],"answer":2,"explanation":"The 12-bit VLAN ID gives only 4094 usable VLANs; VXLAN's 24-bit VNI gives about 16.7 million. It wraps Ethernet frames in UDP/IP (adding about 50 bytes), so tenant networks span a routed fabric without Spanning Tree. It provides no encryption.","difficulty":"hard","source":"Product-company placement · networking"},
  {"id":"cs-computer-networks-565","question":"A flow is shaped by a token bucket with bucket size 1 Mb and rate 20 Mbps, then enters a 100 Mbps link with weighted fair queueing where its weight is 1/4 of the total. What is the maximum queueing delay its packets can suffer at that link?","options":["40 ms","10 ms","50 ms","12.5 ms"],"answer":0,"explanation":"WFQ guarantees the flow at least 100 × 1/4 = 25 Mbps, which exceeds its 20 Mbps token rate, so the worst case is a full 1 Mb burst draining at 25 Mbps: 1 / 25 = 40 ms. 10 ms uses the full link rate and 50 ms the token rate.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-566","question":"An internal API is protected with HTTP Basic authentication over plain HTTP. A security reviewer objects. Why?","options":["Basic sends a salted password hash, which an eavesdropper can still crack offline","Credentials are only Base64-encoded in every request, so anyone on the path can read them","Basic authentication works only with GET requests, so every write is unprotected","The password is sent only on the first request, so a stolen session cannot be revoked"],"answer":1,"explanation":"The Authorization header holds base64(user:password), an encoding, not encryption, and it is sent with every request. Basic is acceptable only inside TLS.","difficulty":"moderate","source":"Product-company placement · security"},
  {"id":"cs-computer-networks-567","question":"What problem does OCSP stapling solve in TLS?","options":["It lets the browser skip certificate-chain validation entirely for pinned sites","It replaces CRLs with a short-lived key that the server signs afresh per session","The server sends a recent CA-signed 'not revoked' status, so clients need not ask the CA","It encrypts the certificate so that on-path observers cannot learn which site is visited"],"answer":2,"explanation":"Plain OCSP makes each client query the CA, adding latency and telling the CA which sites users visit. With stapling the server fetches a signed, time-limited OCSP response and sends it in the handshake.","difficulty":"hard","source":"Product-company placement · security"},
  {"id":"cs-computer-networks-568","question":"Why can an attacker who captures one WPA2-Personal (PSK) four-way handshake try to crack the Wi-Fi passphrase offline?","options":["The handshake sends the passphrase itself, encrypted under a key published in the standard","WPA2 reuses a single RC4 keystream for every frame, exactly as WEP did before it","The access point broadcasts the PMK inside its beacons, so any listener can collect it","The handshake MIC lets each passphrase guess be checked offline from captured nonces and MACs"],"answer":3,"explanation":"The PMK is derived from the passphrase and SSID, and the handshake MIC is computed from keys derived from the PMK, the two nonces and the MAC addresses, all visible. An attacker tests dictionary guesses offline, so a weak passphrase falls. WPA3-SAE removes this.","difficulty":"very-hard","source":"Networking placement · security"},
  {"id":"cs-computer-networks-569","question":"A DNS resolver once sent every query from the same source port with a random 16-bit transaction ID. Why did randomising the source port as well make cache-poisoning attacks much harder?","options":["The attacker must guess both ID and port, about 2³² combinations instead of 2¹⁶","Random ports force DNS onto TCP, and spoofed packets cannot complete a TCP handshake","Random ports make the resolver ignore any answer that arrives suspiciously fast","Each port carries a signature that forged responses have no way to reproduce"],"answer":0,"explanation":"A forged answer is accepted only if it matches the query's ID and the destination port. With a fixed port the attacker races just 65,536 IDs (Kaminsky's attack); a random port multiplies the search by up to another 2¹⁶.","difficulty":"hard","source":"Networking placement · security"},
  {"id":"cs-computer-networks-570","question":"A company announces 198.51.100.0/22 in BGP. An attacker's AS starts announcing 198.51.101.0/24 without permission. What happens, and what defends against it?","options":["Nothing changes, because routers prefer the older, established route; MD5 session keys stop it","Traffic is split equally between the two origins as equal-cost paths; route-flap dampening stops it","The /24 wins wherever it spreads, since forwarding uses the longest prefix; RPKI origin validation stops it","Only the attacker's own customers are affected; BGP's AS-path loop check stops it elsewhere"],"answer":2,"explanation":"Longest-prefix forwarding makes the more specific /24 win over the /22 regardless of BGP path preference. RPKI route origin validation lets networks reject the /24 because no ROA authorises that AS to originate it.","difficulty":"very-hard","source":"Networking placement · security"},
  {"id":"cs-computer-networks-571","question":"10GBASE-R carries 10 Gbps of data with 64B/66B line coding. What is the line (baud) rate, and what fraction of line bits is overhead?","options":["12.5 Gbaud; 20%","10.3125 Gbaud; about 3.0%","10.3125 Gbaud; 3.125%","10 Gbaud; 0%"],"answer":1,"explanation":"Each 64 data bits travel as 66 line bits, so the line rate is 10 × 66/64 = 10.3125 Gbaud, and 2 of every 66 bits (≈ 3.0%) are overhead. 3.125% = 2/64 measures overhead against the data, and 12.5 Gbaud is 8B/10B.","difficulty":"very-hard","source":"Networking placement"},
  {"id":"cs-computer-networks-572","question":"In a DNS response, which flags show that the stub asked for recursion and that the server offers it?","options":["AA set in the query and TC set in the response","QR set in the query and AA set in the response","RA set in the query and RD set in the response","RD set in the query and echoed; RA set in the response"],"answer":3,"explanation":"Recursion Desired is set by the client and echoed back; Recursion Available is set by a server willing to recurse. AA marks an authoritative answer and TC a truncated one; QR distinguishes a response from a query.","difficulty":"hard","source":"Networking placement"},
  {"id":"cs-computer-networks-573","question":"A server keeps each half-open connection in its SYN backlog for 75 s, and the backlog holds 1024 entries. With spoofed sources that never reply, at least how many SYNs per second must an attacker send to keep the backlog full?","options":["About 14 per second","About 1024 per second","About 7 per second","About 27 per second"],"answer":0,"explanation":"Each entry lives 75 s, so a steady 1024 / 75 ≈ 13.7 SYNs per second keeps all 1024 slots occupied. Such a low rate is why SYN cookies or larger backlogs are needed rather than rate alarms alone.","difficulty":"hard","source":"Networking placement · security"},
  {"id":"cs-computer-networks-574","question":"Three flows on a bottleneck get throughputs of 10, 10 and 40 Mbps. What is Jain's fairness index (Σx)² / (n × Σx²)?","options":["0.50","0.75","0.67","0.25"],"answer":2,"explanation":"Σx = 60, so (Σx)² = 3600; Σx² = 100 + 100 + 1600 = 1800, and 3 × 1800 = 5400. 3600 / 5400 ≈ 0.67. The index is 1 for equal shares and 1/n when one flow takes everything.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-575","question":"A traceroute shows replies for hops 1–5, then '* * *' for hops 6 and 7, then replies again from hop 8 up to the destination. What is the most reasonable reading?","options":["Hops 6 and 7 drop all traffic, so the destination should really be unreachable","Hops 6 and 7 forward packets but do not send (or rate-limit) ICMP Time Exceeded","The path changed midway, so hops 6 and 7 belong to a different route altogether","Hops 6 and 7 are layer-2 switches, which never decrement TTL or answer probes"],"answer":1,"explanation":"Later hops answer, so packets clearly pass hops 6 and 7. Those routers simply do not generate ICMP errors for expiring probes or filter them, which is common.","difficulty":"moderate","source":"Networking placement"},
  {"id":"cs-computer-networks-576","question":"Match each symptom with its most likely cause.\nP. Pinging hosts on the same subnet works, but no other subnet is reachable.\nQ. Pinging 8.8.8.8 works, but browsing by name fails and lookups time out.\nR. The PC shows an address in 169.254.0.0/16.\n1. DHCP failed   2. Wrong or missing default gateway   3. DNS server unreachable or misconfigured","options":["P-3, Q-2, R-1","P-1, Q-3, R-2","P-2, Q-1, R-3","P-2, Q-3, R-1"],"answer":3,"explanation":"Local-only reachability points at the gateway; IP works but names fail points at DNS; a 169.254 address is link-local self-assignment after DHCP gets no answer.","difficulty":"moderate","source":"Networking placement"},
  {"id":"cs-computer-networks-577","question":"A link has a bit error rate of 10⁻⁶ with independent errors, and data goes in 1000-bit blocks. To move 10⁶ data bits, compare (a) a Hamming code correcting single errors in each block and (b) one parity bit per block with retransmission of bad blocks. Roughly how many extra bits does each cost?","options":["(a) 1,000; (b) 2,001","(a) 10,000; (b) 1,000","(a) 10,000; (b) 2,001","(a) 11,000; (b) 1,001"],"answer":2,"explanation":"(a) A 1000-bit block needs 10 check bits (2¹⁰ ≥ 1000 + 10 + 1), and 1000 blocks need 10,000. (b) 1000 parity bits plus, on average, one corrupted block resent (1001 bits) gives 2,001. On a clean link detection plus retransmission is cheaper.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-computer-networks-578","question":"In the 2.4 GHz Wi-Fi band, channels are 5 MHz apart and each 802.11 signal is about 20 MHz wide. Which set of channels can neighbouring access points use without overlapping?","options":["1, 6 and 11","1, 5 and 9","1, 2 and 3","1, 4, 7 and 10"],"answer":0,"explanation":"A 20 MHz signal spans about four channel steps, so channels must be five steps apart: 1, 6 and 11 (2412, 2437, 2462 MHz). Channels 1, 4, 7, 10 are only 15 MHz apart and partly overlap.","difficulty":"moderate","source":"Networking placement"},
  {"id":"cs-computer-networks-579","question":"Which part of an Ethernet frame does the 4-byte FCS (CRC-32) protect?","options":["The whole frame, including the preamble and the start-frame delimiter","Only the payload, since the Ethernet header carries its own checksum","From destination MAC through payload and padding, but not preamble or SFD","Only the two MAC addresses, since IP already protects the payload"],"answer":2,"explanation":"The FCS covers everything from the destination address through the data (padding included). The preamble and SFD are only for clock sync and frame start; Ethernet has no separate header checksum.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-580","question":"A routing loop sends packets back and forth between R1 and R2. A host sends a packet with TTL 64 to R1. Each router decrements TTL and drops the packet when it reaches 0. How many times does the packet cross the R1–R2 link?","options":["64","32","62","63"],"answer":3,"explanation":"R1 makes the TTL 63 and sends it across (1st crossing); each crossing lowers it by one more. A packet is forwarded only while the decremented TTL is at least 1, so crossings happen for TTL values 63 down to 1: 63 times.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-computer-networks-581","question":"TCP smooths RTT samples with EstimatedRTT ← 0.875 × EstimatedRTT + 0.125 × Sample. The true RTT jumps from 100 ms to 200 ms and stays there. After how many samples does the estimate first reach at least 190 ms?","options":["8","17","10","18"],"answer":3,"explanation":"After n samples the estimate covers 1 − 0.875ⁿ of the jump. We need 0.875ⁿ ≤ 0.1, so n ≥ ln 0.1 / ln 0.875 ≈ 17.2, i.e. 18 samples (17 gives about 189.7 ms). 8 = 1/0.125 is the 'time constant' guess.","difficulty":"very-hard","source":"GATE CS"},
];

export default questions;
